COLLDATA("asabahur","ur",[[9105,"§۱۰۴۹۵ ۔ ابوالمجبر(1)\nیحیی بن عبدالحمید حمانی اپنی مسند میں بحوالہ ابوالمجبر روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے دو بیٹیوں یا دو بیٹوں دو پھوپھیوں یا دو دادیوں (نانیوں ایک دادی اور ایک نانی) کی کفالت اور خرچ کا بندوبست کیا وہ جنت میں اس طرح میرے ساتھ ہوگا جیسے یہ دو انگلیاں ہیں۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے انگشت شہادت اور ساتھ والی انگلی کو ملا لیا۔(2) تم اگر تین ہوں تو وہ مفرح (فرحت پہنچانے والا) ہے اور اگر چار یا پانچ ہوں تو اللہ کے بندو! اس کا خیال رکھنا، اسے قرض دے دینا اس سے مشترکہ کاروبار کر لینا۔ مطین نے ”الصحابہ“ میں بحوالہ حمانی اور طبرانی نے مطین سے جبکہ ابو موسیٰ نے ان کے طریق سے یہ روایت نقل کی ہے اور بطریق حسن بن عرفہ بحوالہ مبارک اسی سند سے ایک اور حدیث نقل کی ہے۔","",{"fn":"(1) اسد الغابہ (۶۲۱۹)\n(2) المعجم الکبیر (۹۵۹/۲۲) مجمع الزوائد (۱۵۸/۸) جامع المسانید (۴۵۶/۱۴) اسد الغابہ (۸۹/۵)"}],[9106,"§۱۰۴۹۶ ۔ ابومجزأہ اسلمی\nزاہر ہیں۔ جو مجزأہ کے والد ہیں، نام سے مشہور ہیں۔ پہلے تذکرہ ہو چکا ہے۔ مسند بھی میں کنیت کے ساتھ مذکور ہے۔"],[9107,"§۱۰۴۹۷ ۔ ابومجیبہ(1)\nابن حبان نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ ابو عمر رحمہ اللہ یہ فرماتے ہیں: مجھے ان کا حال معلوم نہیں، جبکہ بغوی کا قول ہے: ابومجیبہ یا ان کے چچا بصرہ کے رہائشی ہیں۔ میں کہتا ہوں: یہ مجیبہ باہلی یا باہلیہ کے والد ہیں۔ ابن ماجہ میں مجیبہ باہلی سے بحوالہ ان کے والد لکھا ہے، جبکہ ابن ابی داؤد کی کتاب میں ہے مجیبہ باہلیہ اپنے والد سے روایت کرتی ہیں۔ بغوی نے یہ فائدے کی بات لکھی ہے کہ مجیبہ کے والد کا نام عبد بن حارث ہے۔ درست یہی ہے کہ مجیبہ خاتون ہے۔ چنانچہ سعید بن منصور کی کتاب میں، ابن علیہ سے بواسطہ جزیری، ابوسلیل سے ان کی قوم کی بڑھیا مجیبہ باہلیہ سے مروی ہے۔","",{"fn":"(1) اسد الغابہ (۶۲۲۰) تجرید (۲۲۰/۲)"}],[9108,"§۱۰۴۹۸ ۔ ابو محجن ثقفی\nمشہور شاعر۔ نام میں اختلاف ہے۔ ایک قول کے مطابق: عمرو بن حبیب بن عمرو بن عمیر بن عوف بن عقدہ بن غیرہ (غزہ) بن عوف بن ثقیف اور ایک قول کے مطابق ان کی کنیت ہی ان کا نام ہے اور ان کی کنیت ابو عبید ہے۔ کسی نے مالک کسی نے عبداللہ نام بتایا ہے، والدہ کا نام کنود بنت عبداللہ بن عبد شمس ہے۔ بقول ابواحمد الحاکم: صحابی ہیں۔ فرماتے ہیں: مجھے لگتا ہے یہ وہی ہیں جو نشے کی حالت میں سعد بن ابی وقاص کے پاس لائے گئے اگر یہ وہی ہیں تو پھر ان کا نام مالک ہے۔ پھر بطریق ابو سعد بقال بحوالہ ابو محجن یہ حدیث نقل کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”مجھے اپنی امت کے بارے میں اپنے بعد تین چیزوں کا سب سے زیادہ خوف ہے، ستاروں پر ایمان لانا، تقدیر کو جھوٹ سمجھنا اور بادشاہوں کا ظلم و ستم کرنا“۔ پھر تیسری چیز کا ذکر کیا۔ ابونعیم نے اسی سند سے یہ حدیث نقل کی ہے اور تیسری چیز بادشاہوں کا ظلم ہے۔(1) ابو سعد ضعیف ہے، اس نے ابو محجن کا دور نہیں پایا، ابواحمد الحاکم کا قول ہے: اس بات کی دلیل ہے کہ ان کا نام مالک ہے، یہ روایت ہے جو ہم سے ابوالعباس ثقفی نے زیاد بن ایوب سے، ابو معاویہ، عمرو بن مہاجر، ابراہیم بن محمد، سعد سے بحوالہ ان کے والد نقل کی ہے۔ قادسیہ کے روز سیدنا سعد کے پاس ابو محجن ثقفی کو لایا گیا جو نشے میں تھے، آپ نے انہیں بیڑیاں پہنا دیں سیدنا سعد کے زخم تھا آپ نے لشکر کا امیر خالد بن عرفطہ کو مقرر کر دیا اور خود بالا خانے پر بیٹھ کر سارا منظر دیکھنے لگے، تو ابو محجن یہ اشعار پڑھنے لگے:(2) ”اس سے بڑھ کر کیا غم ہوگا کہ لشکر تیروں سے زخمی ہو رہا ہے اور مجھے بیڑیوں میں کس کے چھوڑ دیا گیا ہے۔“ اس کے بعد سیدنا سعد کی بیوی سے جو بنت خصفہ تھیں کہنے لگے: خدا تمہارا بھلا کرے، میں تم سے عہد کرتا ہوں کہ اگر میں بچ نکلا تو خود آ کر بیڑیاں پہن لوں گا اور اگر جنگ میں کام آگیا تو تم لوگوں کو مجھ سے راحت مل جائے گی۔ چنانچہ انہوں نے رہا کر دیا، وہ کود کر سیدنا سعد کے گھوڑے بلقاء پر سوار ہو گئے۔ نیزہ لیا اور معرکہ میں جا پہنچے۔ جس طرف رُخ کرتے دشمن کے چھکے چھوٹ جاتے۔ تو لوگ کہنے لگے: یہ فرشتہ ہے اور سعد بیٹھے سارا منظر دیکھ رہے ہیں۔ وہ کہنے لگے: ”اس گھوڑے کی اچھل کود تو بلقاء جیسی ہے اور حملہ ابومحجن جیسا ہے حالانکہ ابومحجن تو گرفتار ہے۔ جب دشمن کو شکست ہوگئی تو ابومحجن نے واپس آکر بیڑیاں پہن لیں۔ بنت خصفہ نے سیدنا سعد کو ساری بات بتا دی۔ تو آپ نے فرمایا: اللہ کی قسم! میں ایسے شخص پر کوئی حد جاری نہیں کر سکتا(3) جس کی وجہ سے اللہ تعالیٰ نے آج مسلمانوں کو اس آزمائش سے نکالا۔ آپ نے انہیں چھوڑ دیا۔ ابو محجن یہ سلوک دیکھ کر فورا بولے: پہلے میں اگر پیتا تھا تو حد کی وجہ سے میں پاک ہو جاتا تھا، اب جبکہ آپ نے مجھے بری کر دیا تو میں کبھی بھی اسے نہیں پیوں گا۔ میں کہتا ہوں: ابواحمد نے اس واقعہ میں لوگوں کے اس قول کو دلیل بنا کر کہ یہ کوئی فرشتہ (ملک) ہے، ان کا نام مالک بتایا تو یہ ان کی مراد کی واضح دلیل نہیں۔ بلکہ بظاہر وہ انہیں فرشتہ سمجھ بیٹھے تھے جس کی تائید ابوبکر بن ابی شیبہ کی روایت ہے کہ اسی سند سے ابو معاویہ سے مروی ہے کہ لوگوں نے انہیں فرشتہ سمجھا۔ ”الضبر ضبر البلقاء“ کو جس نے ”الصبر صبر البلقاء“ لکھا ہے اسے وہم ہوا ہے جیسا کہ ابن فتحون نے ”اوھام الاستیعاب“ میں متنبہ کیا ہے۔ سیدنا سعد رضی اللہ عنہ کی مذکورہ بیوی کا نام سلمی تھا جس کا سیف نے ”الفتوح“ میں ذکر کیا ہے۔ ابوعمر نے بھی ان کا یہی نام لیا ہے۔ اور یہ واقعہ لمبا ذکر کیا ہے۔ اور چند اور اشعار نقل کیے ہیں۔ اس واقعہ میں ہے: انہوں نے جنگ کا رنگ بدل دیا تکبیر کہتے ہوئے جس پر حملہ کرتے ان کے سامنے کوئی نہ ٹکتا تھا وہ بڑے عجیب طریقے سے لوگوں کی گردنیں اڑاتے۔ جس سے لوگوں کو تعجب ہوا کیونکہ کوئی نہیں جانتا نہ تھا۔ عبدالرزاق نے بحوالہ ابن سیرین صحیح سند سے نقل کیا ہے کہ ابو محجن کو شراب پینے پر ہمیشہ کوڑے لگائے جاتے لیکن جب وہ باز نہ آئے تو انہیں گرفتار کر لیا گیا۔ جب قادسیہ کی جنگ ہوئی تو انہوں نے لوگوں کو جنگ کرتے دیکھا پھر سابقہ واقعے جیسا واقعہ نقل کیا۔ لیکن مسلمانوں کا یہ قول نہیں نقل کیا: یہ فرشتہ ہے۔ بلکہ اس میں ہے کہ سیدنا سعد نے فرمایا: میں اگر ابومحجن کو بیڑیوں میں گرفتار نہ کر آیا ہوتا تو مجھے اس کی کارروائی لگتی۔ واقعے کے آخر میں ہے، سیدنا سعد رضی اللہ عنہ نے فرمایا: میں تمہیں شراب کی وجہ سے کبھی حد نہیں لگاؤں گا۔ ابومحجن نے کہا: میں بھی اللہ کی قسم! اب اسے کبھی نہیں پیوں گا۔ مجھے تمہارے کوڑوں کی وجہ سے اسے چھوڑنے میں عار محسوس ہو رہی تھی۔ پھر انہوں نے کبھی شراب نہ پی۔ مدائنی کا بیان ہے کہ عاصم بن عمرو کا قول ہے: سیدنا عمر رضی اللہ عنہ نے ابو محجن کو شراب نوشی کی وجہ سے جلا وطن کر دیا تھا اور ابو جھراء بصری اور ایک دوسرے آدمی کو حکم دیا کہ انہیں سمندری راستے سے لے جائیں، بقول بعض: وہ ان کے ہاتھ سے بھاگ نکلے اور جنگ قادسیہ کے دنوں میں عراق آگئے ابو عمر نے کچھ اضافے کے ساتھ اس کا مفہوم نقل کیا ہے کہ سیدنا عمر رضی اللہ عنہ نے سیدنا سعد کو لکھا کہ انہیں گرفتار کر لو چنانچہ انہوں نے قید کر لیا۔ ابوالاعرابی بحوالہ ابن داب روایت کرتے ہیں کہ ابومحجن انصار کی ایک عورت پر فریفتہ ہو گئے جس کا نام شموس تھا اسے دیکھنا چاہا لیکن بس نہ چل سکا جس کا حیلہ یہ کیا کہ اس کے گھر کے پاس جو گھر تعمیر ہو رہا تھا وہاں کام کرنے والے مستری کے پاس مزدور رہ کر ایک طاقچے سے اسے جھانک کر یہ اشعار کہے:(4) ”میں نے شموس کو دیکھا، جس کے درمیان رحمن تعالی کی طرف سے تھوڑی تنگی اور رکاوٹ نہ تھی۔“ اس کے خاوند نے سیدنا عمر رضی اللہ عنہ سے شکایت کر دی جس کی وجہ سے انہوں نے انہیں جلا وطن کر دیا۔ اور ان کے ساتھ ابو جھراء نامی ایک شخص روانہ کیا جن سے سیدنا ابو بکر مختلف امور میں مدد لیا کرتے تھے۔ پھر وہ واقعہ نقل کیا۔ اس میں ہے: ابو جھراء نے ابومحجن کے پاس تلوار دیکھی تو وہ ان سے ڈر کر سیدنا عمر رضی اللہ عنہ کے پاس بھاگ آئے۔ سیدنا عمر نے سیدنا سعد رضی اللہ عنہ کو لکھا کہ انہیں گرفتار کر لو، چنانچہ انہوں نے انہیں قید کر لیا۔ پھر جنگ قادسیہ والا واقعہ ذکر کیا۔ عبدالرزاق بحوالہ ابن جریج روایت کرتے ہیں کہ مجھے معلوم ہوا ہے کہ سیدنا عمر رضی اللہ عنہ نے ابو محجن بن حبیب بن عمرو بن عمیر ثقفی کو سات مرتبہ شراب نوشی کی حد لگائی، ایک قول ہے: ابومحجن سیدنا عمر رضی اللہ عنہ کے پاس آئے آپ نے سمجھا انہوں نے شراب پی رکھی ہے۔ آپ نے فرمایا: اس کا منہ سونگھو جس پر ابو محجن بولے یہ تو وہ تجسس ہے جس سے آپ کو روکا گیا ہے۔ چنانچہ آپ نے انہیں چھوڑ دیا۔ ابن الاعرابی بحوالہ فضل فمی روایت کیا ہے اپنی شراب نوشی کے ترک کرنے پر ابومحجن نے یہ اشعار کہے:(5) ”میں شراب کو اچھا سمجھتا تھا جبکہ اس میں عقلمند آدمی کی ہلاکت کا سامان ہے۔ اللہ کی قسم! میں اب اسے زندگی بھر نہیں پیوں گا اور نہ کبھی اس سے اپنی بیماری کا علاج کروں گا“۔ ابن کلبی بحوالہ عوانہ روایت کرتے ہیں کہ عبید بن ابی محجن عبدالملک بن مروان کے پاس آئے تو عبدالملک کہنے لگا: یہ تمہارے والد ہی کے اشعار ہیں:(6) ”جب میری وفات ہو جائے تو مجھے انگور کی بیل کے پاس دفن کرنا تا کہ موت کے بعد اس کی جڑیں مجھے سیراب کریں۔“ پھر ان کا واقعہ ذکر کیا۔ ابن الاثیر نے یہ واقعہ ان الفاظ میں نقل کیا ہے کہ بقول بعض: ابومحجن کا بیٹا امیر معاویہ کے پاس آیا۔ امیر معاویہ نے اس سے کہا: تمہارے والد نے یہ اشعار کہے ہیں، پھر انہیں ذکر کیا اس کے بعد ہے:  ”مجھے کسی چٹیل میدان میں نہ دفن کرنا کیونکہ مجھے خدشہ ہے کہ میں مرنے کے بعد اسے نہ چکھ سکوں گا“۔ تو وہ بولا میں چاہوں تو آپ کو ان کے اس سے بہترین شعر سنا دوں۔ امیر معاویہ نے فرمایا: وہ کیا ہے؟ اس نے کہا: یہ شعر  ”لوگوں سے میرے مال اور اس کی کثرت کے بارے میں نہ پوچھ بلکہ میری ہمت اور میرے اخلاق کے متعلق دریافت کر۔ قوم خوب جانتی ہے کہ میں ان کے سرداروں میں سے ایک ہوں۔ جب گھبرایا ہوا کانپتا ہاتھ گھومتا ہے میں اس وقت لڑائی میں گھس جاتا ہوں جب وہ اپنے زوروں پر ہوتی ہے اور راز کو چھپاتا ہوں، جو گردن اڑانا ہے میں جنگ کے روز نیزے کو اس کا حصہ دیتا ہوں اور نیزہ باز کو خون کے لوتھڑوں سے سیراب کر دیتا ہوں۔ جو چیز مجھے ملنے والی نہیں میں اس کے حصول سے باز رہتا ہوں اور اگر مجھ پر ظلم ہو تو میرا کینہ اور دشمنی بڑھ جاتی ہے۔ آدمی کی حالت بعض دفعہ ایسی ہوتی ہے کہ غنی ہونے کے باوجود وہ تنگ دست ہو جاتا ہے اور کبھی لاچار بے وقوف جیسا سودا کر بیٹھتا ہے۔ عنقریب ایک دن کمی کے بعد مال زیادہ ہو جائے گا اور جو شاخ پتوں کے جھڑنے سے صاف ہوگئی تھی ایک دن پھر سبز لباس اوڑھ لے گی“۔  امیر معاویہ رضی اللہ عنہ فرمانے لگے: ہم لوگ اگر چہ غلط کہتے تھے لیکن برتاؤ اچھا کریں گے۔ پھر انہیں انعام سے نوازا۔ ادھر ابن فتحون نے ابو عمر پر اعتراض کیا کہ انہوں نے ابو محجن کی شراب نوشی کا واقعہ ایسے کیوں ذکر کیا ہے کہ وہ شراب کے رسیا اور دلدادہ تھے، ان کا کہنا ہے کہ بس ان کی سزا کا ذکر کافی تھا۔ اس سلسلہ میں سکوت بہتر ہے بلکہ زیادہ مناسب وہ روایت ہے جو سیف نے فتوح میں نقل کی ہے کہ سیدنا سعد کی اہلیہ نے ان سے پوچھا کہ آپ کو کس وجہ سے قید کیا گیا ہے؟ وہ کہنے لگے: اللہ کی قسم! نہ میں نے کوئی حرام کھایا ہے اور نہ پیا ہے دور جاہلیت میں میں نے نوش تھا جس کی وجہ سے میری زبان سے اس کی بہت زیادہ تعریف نکل گئی، اس کی بنا پر انہوں نے مجھے قید کر رکھا ہے۔ انہوں نے سیدنا سعد کو بتایا، آپ نے فرمایا: تم جا سکتے ہو، میں جب تک تمہیں کوئی کام کرتے نہیں دیکھ لیتا تمہارا مواخذہ نہیں کر سکتا۔ میں کہتا ہوں: سیف ضعیف ہے، اور جو روایات ہم نے ذکر کی ہیں وہ زیادہ مضبوط اور مشہور ہیں۔ ابن فتحون نے اس بات کو غلط قرار دیا ہے کہ سیدنا سعد رضی اللہ عنہ نے حد کو ختم کر دیا تھا۔ سیدنا سعد رضی اللہ عنہ کے متعلق ایسا گمان رکھنا مناسب نہیں۔ پھر فرماتے ہیں: اس کی ایک بہترین توجیہ ہے جو انہوں نے ذکر نہیں کی، شاید ان کی مراد یہ ہے کہ سیدنا سعد رضی اللہ عنہ کے کہنے کا مقصد ہے کہ وہ شراب کی وجہ سے انہیں حد نہیں لگائیں گے یہ تھا کہ اس شرط کے ساتھ اگر میں نے اس کا ثبوت دیکھا تو پھر، لیکن اللہ تعالیٰ نے انہیں پچی توبہ کی توفیق عطا کر دی۔ اور پھر کبھی اس کا رُخ نہیں کیا۔ جیسا کہ باقی واقعہ ہے، فرماتے ہیں، بقول بعض: ابومحجن آذربائیجان میں بقول بعض جرجان میں فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۶۲۲۱) استیعاب (۳۲۰۳) تجرید (۲۰۰/۲)\n(2) جامع المسانید (۴۶۶/۱۴) اسد الغابہ (۸۹/۵)\n(3) اسد الغابہ (۹۰/۵)\n(4) کسی کے ذہن میں یہ نہ آئے کہ سیدنا سعد رضی اللہ عنہ نے حدود اللہ کی پروا نہ کی، ہرگز ایسا نہیں بلکہ سیدنا سعد رضی اللہ عنہ کا مقصد یہ ہے کہ آئندہ جب تک میں اپنی آنکھوں سے نہیں دیکھ لیتا تب تک تمہیں حد نہیں لگاؤں گا۔ [عامر تقی ندوی]\n(5) یعنی دور جاہلیت میں۔\n(6) الشعر والشعراء (۴۲۴/۱)"}],[9109,"§۱۰۴۹۹ ۔ ابومحذورہ مؤذن(1)\nنام اوس، بقول بعض: سمرہ بن مغیر تھا یہی مشہور ہے۔ ابن عبدالبر کا بیان ہے کسی نے یہ (مغیر) نام معین لکھا ہے۔ ابن ربیعہ بن مغیر بن عُریح بن سعد بن نجح۔ بقول بلاذری: زیادہ مضبوط روایت یہ ہے کہ نام اوس ہے۔ ابن حزم نے کتاب النسب میں یقین سے لکھا ہے کہ سمرہ ان کا بھائی ہے۔ ابو القطان نے اس کی مخالفت کرتے ہوئے لکھا ہے کہ اوس بن مغیرہ بدر میں کافر مارا گیا تھا، جبکہ ابومحذورہ کا نام سلمان بن سمرہ ہے یا سلمہ بن مغیر ہے۔ ایک قول ہے کہ ابومحذورہ کا نام معیر بن محیریز ہے طبری نے نقل کیا ہے ان کا وہ بھائی جو بدر میں قتل ہوا اس کا نام انہیس تھا۔ ابوعمر لکھتے ہیں: زبیر، ان کے چچا، ابن اسحاق اور مسیحی کا اس پہ اتفاق ہے کہ ابو محذورہ کا نام اوس ہے اور یہ لوگ کے قریش کے نسب کا سب سے زیادہ علم رکھتے ہیں۔ جس نے ان کا نام سلمہ بتایا ہے اس کی غلطی ہے۔ ابو محذورہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی ہے کہ آپ نے انہیں اذان سکھائی تھی ان کا یہ واقعہ صحیح مسلم وغیرہ میں موجود ہے۔ ہمام کی ابن جریج سے مروی روایت میں ہے کہ آپ کی انہیں اذان دہی کی تعلیم جعرانہ میں ہوئی تھی۔ ابن کلبی کا قول ہے: ابومحذورہ نے ہجرت نہیں کی بلکہ مکہ مکرمہ ہی مقیم رہے اور سمرہ بن جندب رضی اللہ عنہ کی وفات کے بعد فوت ہوئے۔ کسی اور کا قول ہے: ۵۹ھ یا ۷۹ھ(2) علما میں فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۶۲۲۲) استیعاب (۳۲۰۴) تجرید (۲۰۰/۲)\n(2) جامع المسانید (۴۶۷/۱۴)"}],[9110,"§۱۰۵۰۰ ۔ ابو محصن اشعری\nوہی عکاشہ بن محصن، ناموں میں تذکرہ ہو چکا ہے۔"],[9111,"§۱۰۵۰۱ ۔ ابو محمد انصاری(1)\nامام مالک رحمہ اللہ نے موطا میں ان کا ذکر کیا اور بطریق عبداللہ بن محیریز بواسطہ مدجی روایت کی ہے کہ شام میں ایک شخص ابومحمد کنیت والے تھے، جنہیں شرف صحابیت حاصل تھا، انہوں نے فرمایا: وتر واجب ہیں۔ سیدنا عبادہ بن الصامت کے ساتھ پیش آمدہ ان کا واقعہ ذکر کیا، یہ روایت ابوداؤد وغیرہ نے بطریق امام مالک نقل کی ہے، بقول بعض: ان کا نام مسعود بن اوس بن زید بن اصرم ہے۔ بعض نے مسعود بن زید بن سمیع کہا ہے۔ ایک قول کے مطابق ان کا نام قیس بن عامر بن عبد الحارث خولانی ہے، اوس میں سے بنی حارثہ کے حلیف ہیں۔ بقول بعض: مسعود بن یزید نام ہے۔ اہل شام میں شمار ہوتے ہیں، داریا میں رہتے تھے۔ کسی نے ان کا نام سعد بن اوس/ قیس بن عبایہ بھی بتایا ہے۔ ابن یونس لکھتے ہیں: فتح مصر میں شریک ہوئے۔ ابن سعد کا قول ہے: خلافت فاروقی میں فوت ہوئے۔ ابن کلبی کا گمان ہے: بدر میں شریک ہوئے، پھر جنگ صفین میں امیر المومنین علی بن ابی طالب رضی اللہ عنہ کا ساتھ دیا۔ محمد بن نصر کی کتاب ”قیام اللیل“ میں بطریق عبداللہ بن محیریز بحوالہ ابو رفیع مروی ہے کہ ہم لوگ وتر کے بارے میں باہمی بحث کر رہے تھے تو انصار میں سے ابومحمد نامی ایک صحابی فرمانے لگے۔","",{"fn":"(1) اسد الغابہ (۶۲۲۴) تجرید (۲۰۰/۲)"}],[9112,"§۱۰۵۰۲ ۔ ابو محمد\nطلحہ بن عبیداللہ تمیمی، عبدالرحمن بن عوف زہری، جبیر بن مطعم، عبداللہ بن ثعلبہ بن عبدربہ اذان والے، عبداللہ بن زید بن عاصم حدیث وضو کے راوی۔ عبداللہ بن بحینہ ازدی، حاطب بن ابی بلتعہ، ثابت بن قیس بن شماس انصاری، کعب بن عجرہ بلوی، حمزہ بن عمرو اسلمی، فضالہ بن عبید انصاری، حویطب بن عبد العزی قرشی، عبداللہ بن ابی حدرد اسلمی، عبدالرحمن بن یزید بن حارثہ، عبد اللہ بن مخرمہ عامری، اشعث بن قیس کندی محمود بن ربیع انصاری اور ایک قول کے مطابق عبد اللہ بن عمرو بن عاص، سب کا تذکرہ ناموں میں ہو چکا ہے۔"],[9113,"§۱۰۵۰۳ ۔ ابومحرّث\nنام خالد تھا، پہلے تذکرہ ہوا ہے۔"],[9114,"§۱۰۵۰۴ ۔ ابومخارق\nقابوس کے والد، قابوس میں ذکر ہوا ہے۔"],[9115,"§۱۰۵۰۵ ۔ ابومخشی طائی(1)\nبنی اسد کے حلیف۔ مہاجرین اولین سے اور شرکاء بدر سے تعلق رکھتے ہیں۔ نام سوید بن بخشی تھا۔ ابن سعد نے بحوالہ ابو جبیبہ ان کا ذکر کیا ہے کہ بقول بعض: ابن عدی اور ابو معشر کے حوالہ سے لکھا ہے کہ بقول بعض: زید بن مخفی / ابن حمیر۔","",{"fn":"(1) اسد الغابہ (۶۲۲۶) استیعاب (۳۲۰۷) تجرید (۲۰۰/۲)"}],[9116,"§۱۰۵۰۶ ۔ ابومخشی (دوسرے)\nعبد اللہ بن محمد نے ان میں اور سابقہ میں فرق کیا ہے۔ پہلے کے متعلق لکھا ہے: ان کا نام زید بن حمیر ہے، بلاشک و شبہ بدر میں شریک ہوئے اور دوسرے کے بارے میں لکھتے ہیں: ان کا نام سوید بن بخشی ہے، اُحد میں شریک ہوئے، بدر سے محروم رہے۔ ابن سعد نے اس کا ذکر کیا ہے اور یقین سے لکھا ہے کہ زید بن عمیر کی کنیت ابو مخشی ہے، پہلے تذکرہ ہو چکا ہے۔"],[9117,"§۱۰۵۰۷ ۔ ابو مدینہ دارمی\nعبداللہ بن حصن، ناموں میں ذکر ہوا ہے۔"],[9118,"§۱۰۵۰۸ ۔ ابو مذکر راقی\nان کی ایک ضعیف حدیث ہے جسے حکیم ترمذی نے نوادر الاصول میں اصل تیراسی(۸۳) میں بطریق عرزمی جو ایک ضعیف راوی ہے۔ ابوزبیر سے بحوالہ جابر روایت کی ہے کہ مدینہ میں ابو مذکر کنیت والے ایک شخص تھے جو بچھو کے کاٹے کا دم اور جھاڑ پھونک کیا کرتے تھے۔ جس سے اللہ تعالیٰ لوگوں کو فائدہ پہنچاتے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: تمہارا یہ دم کیا ہے؟ وہ ذرا مجھے سناؤ۔ انہوں نے پڑھا: شجنة قرنية ملحة بحر قفطًا۔ آپ علیہ السلام نے فرمایا: اس میں کوئی حرج نہیں یہ وہ مضبوط کلمات ہیں جو سلیمان بن داؤد علیہ السلام حشرات الارض پر پڑھا کرتے تھے۔ حکیم فرماتے ہیں: ہم سے بیان کیا گیا کہ یہ کلمات تعمیری زبان میں تھے۔ پھر بطریق مغیرہ، ابراہیم سے بحوالہ اسود وہ کلمات میری زبان میں نقل کیے۔"],[9119,"§۱۰۵۰۹ ۔ ابومذکور انصاری(1)\nبیع المدبر (وہ غلام جسے آقا کہے کہ میرے مرنے کے بعد تم آزاد ہو) کے حکم میں ان کا ذکر آتا ہے۔ مسلم(2) نے بطریق ایوب، ابوزبیر سے بحوالہ جابر ان کی روایت نقل کی ہے۔ باقی روایات میں نام کے بغیر ان کا ذکر ہے۔","",{"fn":"(1) اسد الغابہ (۶۲۲۸) تجرید (۲۰۰/۱)\n(2) مسلم کتاب الزکاۃ باب الابتداء فی النفقۃ بالنفس ثم اھلہ (۲۳۱۰)"}],[9120,"§۱۰۵۱۰ ۔ ابوالمرازم\nیعلی بن مرہ ثقفی، پہلے ذکر ہوا ہے۔"],[9121,"§۱۰۵۱۱ ۔ ابو مرازم\nدوسرے ہیں، دولابی نے کنیتوں میں ان کا ذکر کیا ہے اور نام نہیں لکھا۔"],[9122,"§۱۰۵۱۲ ۔ ابومراوح اللیثی(1)\nبقول ابوداؤد: صحابی ہیں، ابن مندہ نے ابوداؤد کے حوالہ سے ان کا ذکر کیا ہے کہ ان کا نام واقد بن ابی واقد ہے۔ ابومراوح الغفاری کے علاوہ ہیں جس سے المزی کی تردید ہو جاتی ہے کہ انہوں نے الغفاری کے حالات میں لکھا ہے اللیثی۔ یوں انہیں ایک شخص قرار دیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۲۲۹) تجرید (۲۰۱/۲)"}],[9123,"§۱۰۵۱۳ ۔ ابومرثد الغنوی(1)\nکناز بن الحصین/حصین بن کناز، کسی نے ان کا نام ایمن بتایا ہے۔ بغوی فرماتے ہیں: کناز بن الحصین ابوحصن، مشہور پہلا نام ہے۔ ابن ابی خیثمہ بواسطہ اپنے والد بحوالہ امام احمد بن حنبل دوسرا نام ذکر کرتے ہیں۔ بغوی لکھتے ہیں: ابن اسحاق کی کتاب میں کناز بن حصن بن مربوع بن عمرو بن خرشہ بن سعد بن طریق بن جلان بن غنم بن غنی بن یعصر بن سعد بن قیس بن غیلان بن مضر ابومرثد الغنوی لکھا ہے۔ شام کے رہائشی تھے۔ نبی کریم صلی اللہ علیہ وسلم سے ایک حدیث روایت کی ہے۔(2) موسیٰ بن عقبہ اور ابن اسحاق نے شرکاء بدر میں ان کا ذکر کیا ہے۔ زہری کا قول ہے کہ ابو مرثد اور ان کا بیٹا مرثد دونوں سیدنا حمزہ کے حلیف تھے۔ مسلم اور بغوی وغیرہ میں ان کی حدیث ہے، فرماتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”قبروں پر نہ بیٹھو اور نہ ان کی طرف رُخ کر کے نماز پڑھو۔“(3) یہ حدیث بطریق بشر بن عبید اللہ، وائلہ بن اسقع سے انہوں نے قبرستان میں بیان کی کہ میں نے صحابی رسول ابو مرثد غنوی رضی اللہ عنہ کو فرماتے سنا، پھر یہ حدیث ذکر کی۔","",{"fn":"(1) اسد الغابہ (۶۲۳۰) استیعاب (۳۲۱۰) تجرید (۲۰۱/۲)\n(2) السیرۃ النبویۃ (۲۴۱/۲)\n(3) مسند ابی یعلی (۱۵۱۴/۳)"}],[9124,"§۱۰۵۱۴ ۔ ابومرحب\nسوید بن قیس، اور ابو مرحب محمد بن صفوان دونوں کا تذکرہ ہو چکا ہے۔"],[9125,"§۱۰۵۱۵ ۔ ابومرحب\nدوسرے ہیں، مرحب میں ذکر ہوا ہے۔"],[9126,"§۱۰۵۱۶ ۔ ابومرہ طائفی(1)\nمطین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، نبی صلی اللہ علیہ وسلم سے ان کی ایک روایت ہے ان سے مکحول روایت کرتے ہیں۔ بقول بغوی: طائف کے رہائشی تھے۔ پھر وہ، امام احمد اور نسائی بطریق سعید بن عبدالعزیز بواسطہ مکحول بحوالہ ابومرہ طائفی روایت کرتے ہیں، فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا، اللہ تعالیٰ نے فرمایا: ”کیا ابن آدم سے اتنا بھی نہیں ہوتا کہ وہ دن کی ابتداء میں چار رکعتیں پڑھ لے اور میں آخری حصے تک اس کی کفایت کر دوں؟“ بغوی فرماتے ہیں: یہ حدیث مجھے صرف بروایت سعید بن عبدالعزیز بحوالہ مکحول معلوم ہے۔ میں کہتا ہوں: یہ یحیی بن اسحاق کی سعید سے مکحول، کثیر بن مرہ، بحوالہ نعیم بن ہمام کی روایت ہے، یہی محفوظ ہے جسے نسائی نے نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۲۳۴) تجرید (۲۰۱/۲)"}],[9127,"§۱۰۵۱۷ ۔ ابومرہ بن عروہ بن مسعود ثقفی(1)\nبقول ابو عمر: یہ اور ان کے والد صحابی ہیں، عہد نبوی صلی اللہ علیہ وسلم میں پیدا ہوئے تھے۔ واقدی فرماتے ہیں: ابومرہ اور ابوالملیح صاحبزادگانِ عروہ بن مسعود نبی صلی اللہ علیہ وسلم کے پاس آئے، آپ کو ان دونوں نے اپنے والد کے قتل کے بارے میں بتایا اور پھر دونوں اسلام لے آئے۔ ابومرہ کی لیلیٰ نامی ایک بیٹی تھی جس سے سیدنا حسن بن علی نے شادی کی تھی اس کی والدہ میمونہ بنت ابی سفیان بن حرب تھی جس کے متعلق حارث بن خالد مخزومی کہتا ہے:(2) ”کیا دن کا سورج ہمارے ارد گرد گھوما ہے بھلا کسی نے شام کے سورج کو گھومتے دیکھا ہے؟ اس کا نانا پورے قریش میں سے ذمہ داری نبھانے والا ہے اور اس کے چچاؤں کا پوچھتے ہو تو وہ ثقیف والے ہیں۔“","",{"fn":"(1) مسند احمد (۲۸۷/۵)\n(2) اسد الغابہ (۶۲۳۵) استیعاب (۳۲۱۲) تجرید (۲۰۱/۲)"}],[9128,"§۱۰۵۱۸ ۔ ابومرہ (بے نسبت)\nدولابی نے کنیتوں میں ان کا ذکر کیا ہے کہ بطریق ابوحمزہ جابر یعنی ابن یزید جعفی سے، جو ایک ضعیف راوی ہے، بواسطہ یزید بن مرہ وہ بحوالہ اپنے دادا روایت کرتے ہیں، فرمایا: جب رسول اللہ صلی اللہ علیہ وسلم چھینکتے تو منہ پر ہاتھ رکھ لیتے تھے۔"],[9129,"§۱۰۵۱۹ ۔ ابومرہ مولا عباس\nابو حلوہ میں ذکر ہو چکا ہے۔"],[9130,"§۱۰۵۲۰ ۔ ابومروان اسلمی(1)\nنام معتب بن عمرو / سعد / عبدالرحمن بن مصعب ہے۔ سیدنا عمر، علی، ابوذر، ابو معیب بن عمرو، اور کعب احبار وغیرہ سے روایت کرتے ہیں۔ بقول بعض: صحابی ہیں۔ طبری نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور ان کا نام معتب بن عمرو بتایا ہے، جیسا کہ حرف میم میں بیان ہوا ہے۔ ان کا سیدنا عمر رضی اللہ عنہ کے ساتھ ایک واقعہ بھی پیش آیا۔ ابن ابی شیبہ، وکیع عیسی بن حفص، عطاء بن ابی مروان وہ بحوالہ اپنے والد روایت کرتے ہیں کہ ہم سیدنا عمر رضی اللہ عنہ کے ساتھ پانی کی تلاش میں نکلے۔ پھر اس کا کچھ حصہ ذکر کیا۔","",{"fn":"(1) تجرید (۲۰۱/۲)"}],[9131,"§۱۰۵۲۱ ۔ ابومریم الجہنی\nعمرو بن مرہ۔"],[9132,"§۱۰۵۲۲ ۔ ابومریم الجہنی(1)\nدوسرے ہیں، یہ بھی احتمال ہے کہ پہلے والے ہوں۔ زبیر بن بکار نے اخبار مدینہ میں بطریق خارجہ بن رافع جہنی ان کا ذکر کیا ہے، فرمایا نبی صلی اللہ علیہ وسلم بنی ربعہ میں جہینہ کے ایک شخص کی عیادت کرنے آئے جو آپ کا صحابی تھا۔ انہیں ابو مریم کہا جاتا تھا۔ آپ نے بنی قیس عطار کی فرودگاہ جہاں پیلو کے درخت تھے کے درمیان اور انصار کے گھروں کے درمیان ایک مقام پر ان کی عیادت کی اس جگہ آپ نے نماز پڑھی۔ تو جہینہ کے چند لوگوں نے ابو مریم سے کہا: آگے بڑھ کر اگر رسول اللہ صلی اللہ علیہ وسلم سے عرض کرو کہ ہمارے لیے مسجد کا نقشہ کھینچ دیں، چنانچہ آپ کے ساتھ ساتھ چلنے لگے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ابومریم کیا بات ہے؟ عرض کی: اگر آپ میری قوم کے لیے مسجد کا نقشہ کھینچ دیں تو ہمارے لیے بڑی مسرت ہوگی۔ چنانچہ آپ صلی اللہ علیہ وسلم آئے اور بنی جہینہ میں مسجد کا نقشہ کھینچا۔","",{"fn":"(1) اسد الغابہ (۶۲۳۶) تجرید (۲۰۱/۲)"}],[9133,"§۱۰۵۲۳ ۔ ابومریم السلولی(1)\nمالک بن ربیعہ، پہلے ناموں میں ذکر ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۶۲۳۹) استیعاب (۳۲۱۳) تجرید (۲۰۲/۲)"}],[9134,"§۱۰۵۲۴ ۔ ابومریم الکندی(1)\nبغوی نے ان کی حدیث ذکر کیے بغیر ان کا تذکرہ کیا ہے۔ ابن السکن صحابہ رضی اللہ عنہم میں ان کا ذکر کرتے ہیں۔ الحاکم کا قول ہے: صحابی ہیں، اہل شام سے ان کی حدیث مروی ہے، یہ غسانی ہیں۔ پھر بحوالہ ابو مریم الکندی روایت کی ہے، نبی صلی اللہ علیہ وسلم کے پاس ایک گوہ لائی گئی اس وقت آپ سفر کر رہے تھے آپ نے اسے پالان کی چوڑی لکڑی پر رکھا، آپ کے پاس ایک شاخ تھی اس کے قریب کی تو گوہ نے اسے اپنے ہاتھ میں پکڑ لیا، نبی اللہ صلی اللہ علیہ وسلم نے فرمایا: ”سنو! یہ اور ان جیسی دوسری چیزیں ایک گروہ تھیں، جنہوں نے اللہ کی نافرمانی کی اللہ تعالیٰ نے انہیں زمین کے حشرات میں تبدیل کر دیا“۔(2) اس کی سند ضعیف ہے۔","",{"fn":"(1) اسد الغابہ (۶۲۴۱)\n(2) المعجم الکبیر (۸۳۶/۲۲) الآحاد والمثانی (۳۹۸/۴) مجمع الزوائد (۳۸/۴) جامع المسانید (۴۷۸/۱۴)"}],[9135,"§۱۰۵۲۵ ۔ ابومریم غسانی(1)\nابوبکر بن ابی مریم کے دادا۔ ابن السکونی کا قول ہے: ابو مریم ازدی، پھر انہوں نے ابن مندہ اور ابواحمد الحاکم نے بطریق بقیہ ابوبکر بن ابی مریم انہوں نے اپنے والد سے بحوالہ اپنے دادا روایت کی ہے، فرمایا: میں نبی صلی اللہ علیہ وسلم کے پاس آیا، عرض کی: اللہ کے رسول! رات میرے ہاں لڑکی پیدا ہوئی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: رات مجھ پر سورۃ مریم نازل ہوئی ہے، تم اس کا نام مریم رکھ دو، چنانچہ انہوں نے اپنی کنیت ابو مریم رکھ لی۔","",{"fn":"(1) اسد الغابہ (۶۲۴۰) (۲۰۲/۲) المعجم الکبیر (۸۳۴/۲۲) مجمع الزوائد (۵۵/۸) جامع المسانید (۴۷۷/۱۴)"}],[9136,"§۱۰۵۲۶ ۔ ابومریم فلسطینی ازدی\nطبری نے ان کا ذکر کیا ہے اور بطریق ولید بن مسلم بحوالہ ابو مریم فلسطینی جو صحابی رسول ہیں، روایت کی ہے۔ بغوی لکھتے ہیں: ابومریم فلسطین کے رہائشی تھے۔ نبی کریم صلی اللہ علیہ وسلم کے پاس آئے انہیں عمرو بن مرہ جھنی کہا جاتا ہے۔ ابو داؤد نے سنن میں کتاب الخراج میں اور ترمذی نے بطریق یحیی بن حمزہ، یزید سے اسی سند کے ذریعہ روایت کی ہے، وہ دونوں فرماتے ہیں: ابو مریم ازدی سے مروی ہے، فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”جو شخص مسلمانوں کے کسی کام کا ذمہ دار بنا پھر ان کی حاجت و ضرورت پوری کرنے سے چھپ گیا تو اللہ تعالیٰ بھی اس کی حاجت اور ضرورت اور اس کا فاقہ دور کرنے سے باز رہے گا۔ فرماتے ہیں: پھر امیر معاویہ نے لوگوں کی ضروریات کے لیے ایک آدمی مقرر کر دیا۔ یہی روایت بغوی نے ولید بن مسلم کے طریق سے اور ابن ابی عاصم، حمید اور طبرانی نے مسند شامیین میں بطریق صدقہ بن خالد، بواسطہ یزید بحوالہ ابومریم نامی ایک فلسطینی شخص سے نقل کی ہے۔ طبرانی کی روایت میں ہے: بنی ازد کے ایک شخص سے مروی ہے۔ ابن ابی عاصم نے ان کا عنوانِ حالات ابو مریم سکونی لکھا ہے۔ میرے خیال میں ان کا سکونی کہنا وہم ہے۔ ترمذی امام بخاری رحمہ اللہ سے روایت کرتے ہیں کہ اس حدیث کے راوی عمرو بن مرہ جھنی ہیں۔ امام ترمذی رحمہ اللہ نے بطریق علی بن الحکم بواسطہ حسن روایت کی ہے کہ عمرو بن قرہ نے امیر معاویہ سے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: ”جس نے اپنا دروازہ بند رکھا (اور لوگوں کو سوال و شکایت کرنے کا موقعہ نہ ملا) پھر اس مفہوم کی حدیث نقل کی۔ فرماتے ہیں: غریب ہے، کسی اور سند سے بحوالہ عمرو بن مرہ مروی ہے۔ امام بخاری رحمہ اللہ کا بیان ہے کہ وہ عمرو بن مرہ جھنی ہیں لگتا ہے اس سلسلے میں وہ بغوی کے سلف (پیشرو) ہیں۔ جبکہ اس میں تامل ہے۔ اس واسطے کہ دونوں حدیثیں مختلف ہیں اور یہی صورت حال متن کی ہے۔ ادھر کئی حضرات نے یقین سے لکھا ہے کہ یہ اور ہیں۔ حافظ ابن عساکر رحمہ اللہ فرماتے ہیں: ابو مریم ازدی صحابی ہیں، دمشق میں امیر معاویہ کے پاس آئے۔ ایک حدیث کی روایت کرتے ہیں، پھر بطریق محمد بن شعیب بن سابور، بواسطہ ابوالمعتقل مولا بنی کلاب جنہوں نے امیر معاویہ کا دور پایا ہے روایت کیا ہے کہ امیر معاویہ کے پاس محاذ میں ایک صحابی آئے جنہیں ابو مریم کہا جاتا تھا۔ پھر امیر معاویہ کے ساتھ ان کا پیش آمدہ واقعہ نقل کیا جس میں یہ اضافہ ہے: امیر معاویہ نے فرمایا: سعد کو یعنی جو ان کا دربان تھا، بلاؤ! پھر فرمایا: اے اللہ! میں اس ذمہ داری کو اپنی گردن سے اتار کر سعد کی گردن میں ڈالتا ہوں جو میرے پاس اجازت لینے آئے اسے اجازت دے دو۔ اللہ تعالیٰ میری زبان سے جو فیصلہ صادر فرمائے اس کی مرضی۔ یہی روایت ابو معطل کے حالات میں بطریق طبرانی اوسط میں ابراہیم بن دحیم سے بواسط ان کے والد بحوالہ محمد بن شعیب نقل کی ہے۔ اس کے آخر میں فرماتے ہیں: ابو معطل ثقہ راوی ہیں۔ حافظ ابن عساکر رحمہ اللہ فرماتے ہیں: ابن سمیع نے ان ابومریم اور عمرو بن مرہ میں فرق کیا ہے۔ رہا ابن ابی عاصم کا یہ قول کہ ”یہ سکونی ہیں تو اس کا ثبوت نہیں۔ ابو مریم سکونی اور ہیں مشہور تابعی ہیں۔ ثوبان سے روایت کرتے اور ان سے عبادہ بن نسیم روایت لیتے ہیں۔ امام بخاری رحمہ اللہ وغیرہ نے ان کا ذکر کیا ہے۔ جبکہ ان کی نبی صلی اللہ علیہ وسلم سے سماع کی صراحت کی ہے۔"],[9137,"§۱۰۵۲۷ ۔ ابوالمساکین\nیہ جعفر بن ابی طالب ہیں۔ مساکین کی خبر گیری کی وجہ سے نبی صلی اللہ علیہ وسلم نے انہیں یہ کنیت عطا کی۔"],[9138,"§۱۰۵۲۸ ۔ ابو مسعود بدری\nعقبہ بن عمرو، نام و کنیت سے مشہور ہیں، پہلے تذکرہ ہو چکا ہے۔"],[9139,"§۱۰۵۲۹ ۔ ابو مسعود بن مسعود غفاری\nنام عبداللہ عروہ ہے جبکہ روایات میں بغیر نام کے ان کا ذکر ہوا ہے۔ ابن مسعود میں مہمات کے دوران تذکرہ ہوتا ہے۔"],[9140,"§۱۰۵۳۰ ۔ ابو مسلم ایمان بن صیفی غفاری"],[9141,"§۱۰۵۳۱ ۔ ابو مسلم ایاس بن سلمہ اسلمی\nدونوں کا تذکرہ ناموں میں ہو چکا ہے۔"],[9142,"§۱۰۵۳۲ ۔ ابومسلم الجلیلی\nبقول بعض: الجلولی قسم ثالث میں ذکر ہوتا ہے۔"],[9143,"§۱۰۵۳۳ ۔ ابو مسلم خزاعی\nدولابی نے کنیتوں میں ان کا ذکر کیا ہے کہ صحابی ہیں۔"],[9144,"§۱۰۵۳۴ ۔ ابو مسلم المرادی(1)\nمصر کے رہائشی۔ ابن یونس نے تاریخ مصر میں لکھا ہے انہیں شرف صحابیت حاصل ہے اور عمرو بن عاص رضی اللہ عنہ کی طرف سے پولیس کے سربراہ تھے۔ بغوی اور ابن السکن لکھتے ہیں: صحابی ہیں، پھر دونوں نے بطریق سوید بن ابی حاتم بحوالہ ابو مسلم صحابی رسول روایت کی ہے کہ ایک شخص نبی صلی اللہ علیہ وسلم کے پاس آکر عرض کرنے لگا: اللہ کے رسول! مجھے کوئی ایسا عمل بتائیں جو جنت تک پہنچا دے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”کیا تمہاری والدہ زندہ ہے؟ اگر ہے تو اس سے نیک سلوک کرو!“ اس نے عرض کی: میری والدہ زندہ نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”تو پھر کھانا کھلایا کرو اور نرمی سے بات کیا کرو“۔(2) بغوی فرماتے ہیں: یہ روایت ثابت نہیں۔","",{"fn":"(1) اسد الغابہ (۶۲۴۸) تجرید (۲۰۳/۲)\n(2) جامع المسانید والسنن (۵۲۰/۱۴) تاریخ بغداد (۵۵/۴) العلل لابی حاتم الرازی (۹۳۶) اسد الغابہ (۹۹/۵)"}],[9145,"§۱۰۵۳۵ ۔ ابو مصبح الہرمی\nمولا صفوان بن المعطل، نو اور میں بقول ابوعلی الہجری: صحابی ہیں۔"],[9146,"§۱۰۵۳۶ ۔ ابومصرف\nطلحہ بن مصرف نے بواسطہ اپنے والد بحوالہ اپنے دادا روایت کی ہے۔ ان کے دادا کے نام میں اختلاف ہے، کسی نے کعب تو کسی نے عمر لکھا ہے۔ بغوی نے کنیتوں میں ان کا ذکر کیا ہے۔"],[9147,"§۱۰۵۳۷ ۔ ابو مصعب اسلمی\nمصعب میں تذکرہ ہو چکا ہے۔"],[9148,"§۱۰۵۳۸ ۔ ابو مطرف\nسلیمان بن صرد الخزاعی، تذکرہ ہوا ہے۔"],[9149,"§۱۰۵۳۹ ۔ ابومعاذ\nرفاعہ بن رافع انصاری، ذکر ہوا ہے۔"],[9150,"§۱۰۵۴۰ ۔ ابومعاویہ دنلی\nنوفل بن معاویہ، ان کا ذکر بھی ہو چکا ہے۔"],[9151,"§۱۰۵۴۱ ۔ ابو معبد بن حزن بن ابی وہب(1) المخزومی\nسعید بن المسیب کے چچا۔ انہیں اور ان کے بھائی مسیب کو شرف صحابیت حاصل ہے۔ زبیر بن بکار نے کتاب النسب میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۲۵۴) تجرید (۲۰۳/۲)"}],[9152,"§۱۰۵۴۲ ۔ ابو معبد خزاعی(1)\nام معبد کے شوہر۔ ابن الاثیر(2) نے ان کا ذکر کیا ہے کہ جیش میں آئے تھے۔ جیش میں آنے والے کے بارے میں بتایا جاتا ہے وہ ام معبد کے بھائی تھے۔ رہے ان کے خاوند تو ان کا نام کسی نے نہیں لیا۔ ابن مندہ نے معبد بن ابی معبد کے حالات کا عنوان قائم کیا ہے، لیکن ان کے والد کا نام نہیں ذکر کیا۔ اور ام معبد والا واقعہ انہی کی روایت سے نقل کیا ہے۔ امام بخاری رحمہ اللہ نے تاریخ میں ابن خزیمہ نے اپنی صحیح میں اور بغوی نے ام معبد کا واقعہ بطریق حربن صباح شخصی بحوالہ ابو معبد خزاعی نقل کیا ہے۔ فرمایا: جب رسول اللہ صلی اللہ علیہ وسلم، ابوبکر، عامر بن فہیرہ مولا ابی بکر مکہ سے ہجرت کر کے مدینہ کے لیے روانہ ہوئے تو ان کا گزر ام معبد(3) کے خیمہ پر سے ہوا، ان لوگوں کا رہبر (گائیڈ) عبد اللہ بن اریقط لیثی تھا۔ بغوی کے ہاں اس کے آخر میں ہے، عبدالملک نے کہا: مجھے معلوم ہوا ہے کہ ام معبد نے ہجرت کی اور اسلام لائیں۔ امام بخاری رحمہ اللہ کا قول ہے: یہ مرسل روایت ہے۔ ابو معبد کا انتقال نبی صلی اللہ علیہ وسلم سے پہلے ہو گیا تھا۔","",{"fn":"(1) اسد الغابہ (۶۲۵۵) استیعاب (۳۲/۹)\n(2) اسد الغابہ (۱۰۱/۵)\n(3) المستدرک (۹/۳) دلائل النبوۃ (۲۷۶/۱) (۲۸۰/۱) المعجم الکبیر (۳۶۰۵/۴)"}],[9153,"§۱۰۵۴۳ ۔ ابو معتب بن عمرو اسلمی(1)\nعنقریب مروان کا ذکر ہوا ہے، ان کے والد۔ ابن مندہ نے ان کا ذکر کیا ہے کہ ابو حاتم نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ لیکن ثابت نہیں، پھر بطریق ابن اسحاق بحوالہ ابو معتب یہ روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جب بلندی سے خیبر کو دیکھا تو اپنے صحابہ رضی اللہ عنہم سے فرمایا: ”ٹھہرو! ہم اللہ تعالیٰ سے دعا کر لیں۔ اے اللہ! سات آسمانوں اور جن چیزوں پر ان کا سایہ ان کے رب اور اے زمینوں اور جو کچھ انہوں نے اٹھا رکھا ہے ان کے رب! اے شیطانوں اور جنہیں شیطانوں نے گمراہ کیا ہے ان کے رب! ..... (حدیث) واقدی نے ”الردۃ“ میں بحوالہ ابو معتب روایت کی ہے، فرمایا: میں ان لوگوں میں تھا جنہوں نے اہل بحرین سے صلح کی تھی۔ اشعث نے زیاد بن لبید سے اس بات پر صلح کی کہ ان کے ستر مردوں کو امن دے گا۔ اس نام کے لکھنے میں اختلاف ہے، بقول بعض: ”معتب“ جس پر ابن عبدالبر نے واقدی کی پیروی میں اعتماد کیا ہے۔(2) بقول بعض: ”مغیث“ جس پر ابن ماکولا نے طبری کی پیروی میں بھروسا کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۲۵۶)\n(2) الاکمال (۲۱۷/۷)"}],[9154,"§۱۰۵۴۴ ۔ ابومعدان\nخالد بن معدان کے دادا۔ دولابی نے کنیتوں میں ان کا ذکر کیا ہے، اوروں نے مہمات میں ان کا ذکر کیا ہے۔"],[9155,"§۱۰۵۴۵ ۔ ابو معقل الاسدی(1)\nبقول بعض: انصاری نام ہیشم ہے جیسا کہ حرف ہاء میں اس کے متعلق تنبیہ ہو چکی ہے۔ ایک قول کے مطابق انصاری اور بنی اسد کے حلیف ہیں اور ایک قول کے مطابق اسدی ہیں۔ انصار کے حلیف تھے، نسب یوں ہے ہیشم بن نہیک بن اساف بن عدی بن زید بن جشم بن حارثہ۔ بقول بعض اُحد میں شریک ہوئے۔ ایک قول ہے: حجۃ الوداع کے موقعہ پر فوت ہوئے۔ ابن مندہ فرماتے ہیں: صحابی ہیں۔ ان کی حدیث اعمش، عمارہ بن عمیر اور جامع بن شداد سے بواسطہ ابوبکر بن عبدالرحمن بن حارث بحوالہ ان سے نقل کی ہے کہ یہ نبی صلی اللہ علیہ وسلم کے پاس آئے۔ اور عرض کی: ام معقل نے حج کی نذر مانی تھی۔ (حدیث) یہ نسائی کی روایت ہے، جسے ابو داؤد نے بطریق اعمش نقل کیا ہے۔ محمد بن عبداللہ بن زکریا بن حیوہ جو نسائی سے سنن کے راویوں میں سے ایک ہیں۔ یہ اضافہ نقل کیا ہے کہ ابو معقل کا نام ہیشم ہے۔ یہی روایت ابن مندہ نے بطریق ابوعوانہ، ابراہیم بن مہاجر سے، بواسطہ ابو بکر بن عبدالرحمن نقل کی ہے کہ مجھے مروان کے قاصد نے بتایا جسے اس نے ام معقل کے پاس بھیجا تھا۔ اس نے ان سے کہا کہ ابومعقل رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حج کرنے کے لیے تیار ہیں۔ انہوں نے فرمایا: مجھے معلوم ہے مجھ پر حج لازم ہے۔ ابو معقل کے پاس ایک اونٹ ہے، جس پر ابو معقل کہنے لگے: اس نے سچ کہا، لیکن میں نے اسے اللہ کی راہ میں وقف کر دیا ہے۔ آپ نے فرمایا: وہ اسی پر حج کر لے۔ کیونکہ وہ اللہ کی راہ میں ہے۔ چنانچہ انہوں نے وہ اونٹ انہیں دے دیا، ام معقل رسول اللہ صلی اللہ علیہ وسلم سے عرض کرنے لگیں: اللہ کے رسول صلی اللہ علیہ وسلم میں عمر رسیدہ اور بیمار ہوگئی ہوں کوئی ایسا عمل نہیں جو میرے حج کے برابر ہو؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”رمضان کا عمرہ حج کے برابر ہے“۔(2) ابن مندہ نے یہ روایت عالی سند سے بروایت محاضر بن موزّع بحوالہ اعمش نقل کی ہے اس میں فرماتے ہیں: معقل یا ابو معقل آئے۔ نسائی نے اسے بطریق زہری بحوالہ بنی اسد کی ایک خاتون جنہیں ام معقل کہا جاتا تھا انہی الفاظ میں نقل کی ہے۔ ادھر ترمذی نے حدیث ”رمضان کا عمرہ حج کے برابر ہے“ بطریق اسرائیل ابو اسحاق، اسود سے بواسطہ ابو معقل بحوالہ ام معقل نقل کی ہے اور ابن ماجہ نے بطریق ابو شیبہ، ابو اسحاق سے، اسود سے بحوالہ ابو معقل روایت کی ہے۔ ابوشیبہ ضعیف راوی ہے لیکن شریک نے ابو اسحاق سے نقل کرنے میں ان کی متابعت کی ہے۔ ابن السکن نے انہی کے طریق سے روایت کی ہے اور ابونعیم نے بطریق مطین بواسطہ ان کے شیخ، شریک سے نقل کی۔ ابن مندہ فرماتے ہیں: اسرائیل کی روایت، ابو اسحاق سے انہوں نے اسود سے بواسطہ ابو معقل بحوالہ ام معقل ہے۔ جبکہ اوروں نے ابو اسحاق عن عیسی بن معقل عن یوسف بن عبداللہ بن سلام بحوالہ ان کی دادی ام معقل نقل کی اور موسیٰ بن عقبہ عن عیسی بن معقل عن جدتہ اس میں یوسف کا ذکر نہیں۔ مسلم بن خالد نے جعفر بن محمد سے بواسطہ اپنے والد بحوالہ ام معقل روایت کی۔ اور ابراہیم بن محمد عن محمد بن اسحاق عن یحیی بن عباد عن حارث بن عبدالرحمن بن حارث عن ابیہ عن معقل نقل کیا۔ اس کا ایک اور طریق بھی ہے جو بروایت ابوسلمہ بن عبد الرحمن، معقل سے بحوالہ ان کی والدہ مروی ہے۔ مردوں کے ناموں میں معقل بن ام معقل کے حالات میں ان کا ذکر ہوا ہے(۸۱۴۰)۔","",{"fn":"(1) اسد الغابہ (۶۲۵۷) تجرید (۲۰۴/۲)\n(2) السنن الکبری تحفۃ الاشراف (۲۸۹/۹) ابن ماجہ کتاب المناسک باب العمرۃ فی رمضان (۲۹۹۳) المعجم الکبیر (۳۶۸/۲۵) الاحاد والمثانی (۳۲۴۰/۶) جامع المسانید (۵۲۹/۱۴)"}],[9156,"§۱۰۵۴۶ ۔ ابو معقل(1) (بے نسبت)\nابراہیم بن عبد اللہ خزاعی نے الکنی میں ان کا ذکر کیا ہے یہ وہی ہیں جو دونوں قبلوں کی جانب (قضائے حاجت کے وقت) منہ کرنے کی ممانعت والی حدیث روایت کرتے ہیں۔ ابواحمد الحاکم نے یہ بات نقل کی ہے۔ مذکورہ حدیث ابوداؤد وغیرہ میں حدیث معقل بن ابی معقل سے مروی ہے۔ ناموں میں اس کی وضاحت ہو چکی ہے۔ آیا یہ ابو معقل کے بیٹے ہیں جن کا پہلے ذکر ہوا یا کوئی اور ہیں؟","",{"fn":"(1) اسد الغابہ (۶۲۵۸) تجرید (۲۰۴/۲)"}],[9157,"§۱۰۵۴۷ ۔ ابو معقل بن نہیک(1)\nبن اساف انصاری۔ ان کا تذکرہ ان کے بیٹے عبداللہ بن ابی معقل کے حالات میں ہو چکا ہے۔ بقول ابو عمر: انہیں ابومعقل اسدی بھی کہا جاتا ہے، جو حدیث ”عمرۃ فی رمضان“ کے راوی ہیں۔ یعنی جن کا نام ہیشم ہے، جبکہ اوروں نے دونوں میں فرق کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۲۵۹) استیعاب (۳۲۲۱)"}],[9158,"§۱۰۵۴۸ ۔ ابو معلق انصاری(1)\nابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے اور بطریق ابن کلبی، حسن سے بحوالہ ابی بن کعب روایت کی ہے کہ ابو معلق کنیت والے ایک انصاری صاحب کسی سفر پر روانہ ہوئے۔ پھر ان کا چور کے ساتھ وہ والا واقعہ ذکر کیا جس میں چور نے انہیں قتل کرنا چاہا۔ ابو موسیٰ لکھتے ہیں: پورا واقعہ میں نے کتاب الوظائف میں درج کیا ہے۔ میں کہتا ہوں: ہم نے ”مجاب الدعوۃ“ لابن ابی الدنیا میں بحوالہ سیدنا انس بن مالک روایت کی ہے کہ ایک صحابی رسول ابو معلق کنیت والے تھے جو اپنا یا کسی اور کا مال تجارت کے لیے لے جاتے تھے۔ وہ بڑے عبادت گزار و پرہیز گار تھے۔ ایک بار وہ جا رہے تھے کہ ایک چور اسلحہ سے لیس ان کے پاس آدھمکا، تلوار سونت کر بولا، اپنا سامان رکھ دو ورنہ میں تمہیں قتل کر دوں گا۔ انہوں نے فرمایا: مال لے لو، مجھے کیا کہتے ہو۔ اس نے کہا: میں تمہارے خون کا پیاسا ہوں۔ یہ بولے تو پھر مجھے نماز پڑھ لینے دو، اس نے کہا: جتنی مرضی پڑھ لو۔ چنانچہ یہ وضو کر کے نماز پڑھنے لگے: ان کی دُعا میں یہ الفاظ تھے: يا وَدُودُ يا ذا العرش المجيد يا فَعَّال لِمَا يُرِيدُ اسألك بعزتك التي لا ترام و ملكك الذى لا يضام و بنورك الذى ملأ اركان عرشك ان تكفيني شر هذا اللص يا مغيث اغثني. تین بار یہ کلمات کہے، اچانک ایک گھوڑ سوار گھوڑے کے سر پر سے نیزہ اٹھائے ظاہر ہوا اور چور کو مار کر قتل کر دیا۔ پھر وہ تاجر کی طرف متوجہ ہوا۔ تاجر نے پوچھا: تو کون ہے جس کے ذریعے اللہ تعالیٰ نے میری مدد کی؟ اس نے بتایا: میں چوتھے آسمان کا فرشتہ ہوں، جب تم دعا مانگ رہے تھے تو میں نے آسمانی دروازوں میں کھڑ کھڑاہٹ کی آواز سنی، جب تم نے دوسری بار دعا کی تو آسمان والے شور کرنے لگے، جب تم نے تیسری بار دعا کی تو کسی نے کہا: کسی مصیبت زدہ کی پکار ہے، میں نے اللہ تعالیٰ سے عرض کی کہ مجھے اس کی خدمت کے لیے بھیجا جائے، پھر اس فرشتے نے کہا: مبارک ہو جو بھی وضو کر کے چار رکعت پڑھ کر یہ دعا مانگے گا اس کی دعا قبول ہوگی خواہ مصیبت زدہ ہو یا نہ ہو۔","",{"fn":"(1) اسد الغابہ (۶۲۶۰)"}],[9159,"§۱۰۵۴۹ ۔ ابوالمعلی بن لوذان انصاری(1)\nنبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں اور ان سے روایت ہے۔ نبی کریم صلی اللہ علیہ وسلم نے ایک دن خطبہ دیا اور فرمایا: ایک بندے کو اللہ تعالیٰ نے اختیار دیا ہے ... (حدیث)(2) یہی روایت ترمذی، امام احمد، ابو یعلی اور بغوی، ابوعوانہ سے بواسطہ عبدالملک بن عمیر بحوالہ ابن ابی المعلی انصاری روایت کرتے ہیں۔ بقول ابوعمر: اکثر علماء کے ہاں ان کا نام مشہور نہیں۔ بقول بعض: ان کا نام زید بن المعلی ہے۔ بغوی فرماتے ہیں: کوفہ کے رہائشی ہیں۔ امام احمد اور ابو یعلی نے مسند ابی یعلی میں یہ روایت نقل کی ہے۔ ابن عساکر کا بیان ہے: یہ غلط ہے۔ میں کہتا ہوں: اس میں عبدالملک سے آگے اختلاف ہے، چنانچہ عبد اللہ بن عمرو نے ان سے، انہوں نے ابوالمعلی سے انہوں نے اپنے والد سے روایت کی ہے۔ یہ ابوعوانہ کی روایت کے برعکس ہے جسے طبرانی نے نقل کیا ہے، ان دونوں کے علاوہ کا کہنا ہے: عبدالملک، ابن المعلی سے وہ اپنے والد سے روایت کرتے ہیں، یہ ابو عوانہ کی روایت جیسی ہے لیکن اس میں سے کنیت کا لفظ رہ گیا ہے۔ واللہ اعلم!","",{"fn":"(1) اسد الغابہ (۶۲۶۱) تجرید (۲۰۴/۲)\n(2) ترمذی کتاب المناقب باب مناقب ابوبکر الصدیق (۳۷۳۹)"}],[9160,"§۱۰۵۵۰ ۔ ابوالمعلی السلمی(1)\nبقول بعض: ابوالاسد سلمی کے دادا قربانی کے بارے میں ان کی ایک حدیث ہے، ابوموسیٰ نے بحوالہ حسن بن احمد سمرقندی ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۲۶۲) تجرید (۲۰۴/۲)"}],[9161,"§۱۰۵۵۱ ۔ ابو معمر(1) (بے نسبت)\nابن مندہ نے ان کا ذکر کیا ہے اور بطریق معلی واسطی بحوالہ ابو معمر روایت کی ہے، فرمایا: ہم لوگ آلِ محمد کے پاس واقعات دہراتے تھے۔ فرماتے ہیں: اس کی سند مجہول ہے۔ میں کہتا ہوں: اس میں ان کے صحابی ہونے کی کوئی دلیل نہیں۔","",{"fn":"(1) اسد الغابہ (۶۲۶۳) تجرید (۲۰۴/۲)"}],[9162,"§۱۰۵۵۲ ۔ ابومعن\nیزید بن الاخنس سلمی، پہلے تذکرہ ہو چکا ہے۔"],[9163,"§۱۰۵۵۳ ۔ ابومعن(1)\nدوسرے ہیں۔ بقول امام مسلم: صحابی ہیں۔ مطین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور بطریق ابوحمزہ سکری، عاصم بن کلیب سے بواسطہ سہیل بن ذراع ان کی روایت کی ہے کہ انہوں نے ابومعن کو فرماتے سنا کہ ہمارے ایک شخص نے انتہائی اچھے انداز میں گفتگو کی تو نبی صلی اللہ علیہ وسلم نے فرمایا: بعضی باتیں جادو کا (سا) اثر رکھتی ہیں۔(2) محمد ابن شاہین کی روایت میں ہے کہ سہیل بن ذراع نے کہا: میں نے ابو معن یزید بن معن یا معن بن یزید کو فرماتے سنا... پھر اس حدیث کا ذکر کیا۔","",{"fn":"(1) اسد الغابہ (۶۲۶۴) استیعاب (۳۲۲۵) تجرید (۲۰۴/۲)\n(2) مسند احمد (۴۷۰/۳) جامع المسانید (۵۳۴/۱۴)"}],[9164,"§۱۰۵۵۴ ۔ ابو مغیث جہنی(1)\nابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے کہ ابن ابی شیبہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ پھر بحوالہ مغیث جہنی انہوں نے اپنے والد سے روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اچھا سلوک عمر میں اضافے کا باعث ہے۔(2)","",{"fn":"(1) اسد الغابہ (۶۲۶۶)\n(2) ابوداؤد کتاب الادب باب فی حق المملوک (۱۵۶۲) مسند احمد (۵۰۲/۳) المصنف لعبد الرزاق (۲۰۱۱۸/۱۱) مجمع الزوائد (۱۱۰/۳) (۲۲/۸) جامع المسانید (۵۳۶/۱۴)"}],[9165,"§۱۰۵۵۵ ۔ ابو مغیث اسلمی\nپہلے ذکر ہو چکا ہے۔"],[9166,"§۱۰۵۵۶ ۔ ابومکرم الاسلمی(1)\nنیار ابن مکرم۔ ابو موسیٰ نے ان کا ذکر کیا ہے۔ شاید روایت میں ابن مکرم تھا تحریف ہو کر ابو مکرم بن گیا۔","",{"fn":"(1) اسد الغابہ (۶۲۶۷) تجرید (۲۰۵/۲)"}],[9167,"§۱۰۵۵۷ ۔ ابومُکعت(1) الاسدی الفقعسی\nحضرمی بن عامر کے ساتھ ان کا ذکر ہوا ہے کہ ان کا نام عرفطہ بن نضلہ۔ بقول بعض: حارث بن عمرو بن الاشتر بن ثعلبہ بن مجھوان بن فقعس ہے یہ ابن ماکولا کا بیان ہے۔ اور خود ابن ماکولا نے دار قطنی کی پیروی میں یہ نام میم کے زبر کاف کے سکون پھر عین اور تا سے ”ملعت“ لکھا ہے۔ ابو احمد عسکری نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور ابن مندہ نے بطریق مفضل ضمی بواسطہ اپنی دادی جو بنی اسد کی ایک خاتون ہیں بحوالہ ابو مکعت اسدی روایت کی ہے کہ میں نبی صلی اللہ علیہ وسلم کے پاس آیا اور آپ کو یہ اشعار سنائے:(2) ”ابو مکعت سچ کہتے ہوئے عرض کرتا ہے ابو القاسم محمد (صلی اللہ علیہ وسلم) آپ پر سلام ہو، اللہ اور اس کے ریحان، نمازیوں کی راحت اور روزہ داروں کی فرحت کا سلام ہو“۔(3) تو نبی صلی اللہ علیہ وسلم نے فرمایا: ابو مکعت ”علیک السلام“ کہنا مردوں کا سلام ہے۔ ابن قانع کی روایت میں ہے: جب ابومکعت آپ کے سامنے کھڑے ہوئے، پھر یہ اشعار ذکر کیے، لیکن انہوں نے کہا، نبی صلی اللہ علیہ وسلم نے فرمایا: وعلیک السلام۔ ابو نعیم نے اسی سند سے نقل کیا ہے کہ ابو مصعب نے کہا، پھر فرمایا: اس میں دوسرے یعنی ابن مندہ سے لفظی غلطی ہوئی ہے۔ فرمایا: ابو مکعت۔ میں کہتا ہوں: ابونعیم عموماً ابن مندہ کی غلطیاں نکالتے ہیں جس میں بعض دفعہ وہ درست موقف پر ہوتے ہیں اور کبھی ان کی اپنی غلطی ہوتی ہے۔ یہ اگر ان پر اعتراض سے باز رہیں تو اکثر جن باتوں میں یہ ان کا تعاقب کرتے ہیں وہ درست ہوں، کوئی دوسرا اس بارے میں ان سے اتفاق نہیں کرتا۔","",{"fn":"(1) اسد الغابہ (۶۲۶۸) تجرید (۲۰۵/۲)\n(2) الاکمال (۲۲۱/۷)\n(3) اسد الغابہ (۲۰۵/۵) الاکمال (۲۲۱/۷)"}],[9168,"§۱۰۵۵۸ ۔ ابو مکنف\nنام عبد رضا، پہلے ذکر ہو چکا ہے کہ فتح مصر میں شریک تھے۔"],[9169,"§۱۰۵۵۹ ۔ ابوملقام\nتلب العنبری، پہلے ذکر ہوا ہے۔"],[9170,"§۱۰۵۶۰ ۔ ابوالملیح بن عروہ(1)\nعروہ بن مسعود بن معتب ثقفی۔ بقول ابن حبان: صحابی ہیں۔ ابن اسحاق(2) کا بیان ہے کہ یہ اپنے والد کے قتل ہونے کے بعد نبی صلی اللہ علیہ وسلم کے پاس آئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: جس سے چاہو دوستی کر لو۔ انہوں نے عرض کی میں تو اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی طرف دوستی کا ہاتھ بڑھاتا ہوں۔ (حدیث) اس کا کچھ تذکرہ ناموں میں حرف قاف کے تحت قارب کے حالات میں ذکر ہو چکا ہے اور ملیح تصغیر ہے۔","",{"fn":"(1) اسد الغابہ (۶۲۷۰) تجرید (۲۰۵/۲)\n(2) السیرۃ النبویۃ (۱۰۶/۵)"}],[9171,"§۱۰۵۶۱ ۔ ابوالملیح الہَدَادی(1) (تشدید کے بغیر ہے)\nابن مندہ نے ان کا ذکر کیا ہے اور بطریق ولید بن یزید ہدادی بواسطہ ابوعبدالدائم بحوالہ ابوالملیح الہدادی روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے نعل مبارک کا تسمہ ٹوٹ گیا تو آپ کیا یہ تم ایک نعل میں چلے تھے۔(2) یہی روایت ابو مسلم کجی اور الحاکم نے بطریق ولید بن یزید نقل کی ہے، لیکن اس میں ہدادی نہیں لکھا ہے۔ ممکن ہے ہدادی لفظی غلطی ہو۔ یہ ہدلی ہے اور ابوالملیح وہ اسامہ ہدلی کے بیٹے ہیں۔ تابعی ہیں ان کے والد صحابی ہیں۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۶۲۷۱) تجرید (۲۰۵/۲)\n(2) جامع المسانید (۵۳۹/۱۴) اسد الغابہ (۱۰۶/۵)"}],[9172,"§۱۰۵۶۲ ۔ ابوالملیح الہذلی(1)\nان کا ذکر ان دو عورتوں کے واقعے میں آتا ہے جن میں سے ایک نے دوسرے کو کھونٹا مار کر اس کا حمل ضائع کر دیا تھا۔ (حدیث) وہ دونوں عورتیں حمل بن نابغہ ہذلی کی بیویاں تھیں۔ ابن مندہ نے یہ روایت بطریق حسن بن عمارہ بواسطہ حکم بن عیینہ بن ابی الملیح ہذلی نقل کی ہے کہ مغیرہ بن شعبہ سے اس عورت کے بارے میں جس نے حمل ساقط کر دیا تھا تو ابوالملیح نے کہا: ہماری ایک عورت نے دوسری عورت کے کھونٹا مارا پھر اس کا وارث نبی صلی اللہ علیہ وسلم کے پاس آیا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”اس میں ایک غلام ہے۔“(2) (حدیث) یہ ابوالملیح واقعہ میں شریک تھے اور یہ وہ ابوالملیح بن اسامہ نہیں ہیں جو مشہور تابعی ہیں۔ ابن الاثیر(3) دونوں کو ایک سمجھ بیٹھے ہیں اور پھر ان کے حالات میں حدیث شعبہ عن یزید الرشک عن ابی الملیح عن النبی صلی اللہ علیہ وسلم وغیرہ کی درج کی ہے۔ ترمذی(4) نے ایسا ہی نقل کیا ہے جو شعبہ کے طریق سے مروی ہے۔ پھر فرمایا: ان سے بواسطہ ابوالملیح بحوالہ ان کے والد اس سے زیادہ صحیح سند سے منقول ہے۔ ابن الاثیر(5) نے اسے مختصر ذکر کیا ہے۔ وہ کہتے ہیں: ان سے حکم نے روایت کی ہے۔ جبکہ درست ”ان سے بواسطہ ان کے والد ہے“ اور ابوالملیح تابعی ہیں۔ میں کہتا ہوں: صحیح یہی ہے کہ دونوں علیحدہ ہیں۔","",{"fn":"(1) اسد الغابہ (۶۲۷۲) تجرید (۲۰۵/۲)\n(2) جامع المسانید (۵۴۰/۱۴)\n(3) اسد الغابہ (۱۰۶/۵)\n(4) ترمذی کتاب اللباس باب ما جاء فی النہی عن جلود السباع (۱۷۷۰)\n(5) اسد الغابہ (۱۰۶/۵)"}],[9173,"§۱۰۵۶۳ ۔ ابوملیکہ ذماری(1)\nبقول ابوعمر: صحابی ہیں۔ امام بخاری رحمہ اللہ نے ”کنی“ میں ان کا ذکر کیا ہے اور بطریق راشد بن سعد بحوالہ ان کے بحوالہ نبی صلی اللہ علیہ وسلم روایت کی ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: آدمی کا ایمان اس وقت تک مکمل نہیں ہوتا جب تک (نیکی کے کام) جو وہ اپنے لیے پسند کرتا ہے اپنے بھائی کے لیے پسند نہ کرے۔(2) اسے حاکم نے کنی میں نقل کیا ہے کہ ان سے ان کا بیٹا بھی روایت کرتا ہے۔","",{"fn":"(1) اسد الغابہ (۶۲۷۳) تجرید (۲۰۵/۲)\n(2) جامع المسانید (۵۴۱/۱۴) کنز العمال (۱۰۶) التاریخ الکبیر (۷۴/۸)"}],[9174,"§۱۰۵۶۴ ۔ ابوملیکہ\nزبیر بن عبداللہ بن جدعان تیمی، ناموں میں ذکر ہو چکا ہے۔"],[9175,"§۱۰۵۶۵ ۔ ابوملیکہ الکندی(1)\nبقول بعض: البہلوی۔ ابن مندہ نے ان کا ذکر کیا ہے اور بحوالہ ابوسعید بن یونس نقل کیا ہے کہ صحابی ہیں۔ اہل مصر ان سے دو یا تین حدیثیں روایت کرتے ہیں۔ یہی قول ابوعبداللہ بن الربیع بن الحبیری کا ”الصحابۃ الذین نزلوا مصر“ میں ہے، ان میں سے ایک وہ روایت ہے جو انہوں نے بطریق علی بن رباح بحوالہ ان کے نقل کی ہے کہ انہوں نے ابو راشد سے کہا جو فلسطین میں رہتے تھے۔ ابو راشد اس وقت تمہارا کیا حال ہو گا جب تمہارے حکمران ایسے ہوں گے کہ اگر تم ان کی نافرمانی کرو گے تو جہنم میں جاؤ گے اور اگر ان کی فرمانبرداری کرو گے تو پھر بھی جہنم میں جاؤ گے۔(2)","",{"fn":"(1) اسد الغابہ (۶۲۷۵)\n(2) اسد الغابہ (۱۰۷/۵)"}],[9176,"§۱۰۵۶۶ ۔ ابوملیکہ(1)\nعبداللہ انصاری خزرجی۔ ابیرق کی اولاد کے واقعہ میں اللہ تعالیٰ کے اس ارشاد: ”جس نے کوئی غلطی یا گناہ کیا اور پھر اس کا الزام کسی بری پر دھر دیا تو اس نے بہت بڑا طوفان اٹھایا۔“(2) کے نازل ہونے میں ان کا ذکر آتا ہے۔ مستغفری نے یہ روایت بطریق ابن جریج نقل کی ہے پھر واقعہ ذکر کیا اس میں ہے اس نے ابوملیکہ خزرجی کے گھر میں زرہ پھینک دی۔","",{"fn":"(1) اسد الغابہ (۶۲۷۸)\n(2) سورۃ النساء (۱۱۱)"}],[9177,"§۱۰۵۶۷ ۔ ابوملیک، سلیک بن الاغر(1)\nصحابہ رضی اللہ عنہم میں ان کا ذکر آتا ہے۔ ابن عبدالبر نے بھی ان کا مختصر ذکر کیا ہے مجھے خدشہ ہے یہ بعد والے نہ ہوں۔ اس میں لفظی غلطی اور تحریف ہوئی ہے۔ ابن فتحون نے اس بات کا جواز پیش کیا ہے کہ یہ بعد والے ہیں۔","",{"fn":"(1) اسد الغابہ (۶۲۷۷) استیعاب (۳۳۳) تجرید (۲۰۶/۲)"}],[9178,"§۱۰۵۶۸ ۔ ابومُلَیل بن الازعر(1)\nبن زید بن عطاف بن ضبیب بن زید انصاری۔ ابن اسحاق(2) وغیرہ نے شرکاء بدر میں ان کا ذکر کیا ہے۔ ابن کلبی کا گمان ہے یہ ان لوگوں میں سے ایک ہیں جنہوں نے خندق کے روز (منافقوں کے ساتھ مل کر) کہا: ہمارے گھر کھلے پڑے ہیں۔ ابوعمر نے بھی ان کا ذکر کیا ہے۔ ابن فتحون کا قول ہے: دونوں ایک ہیں۔","",{"fn":"(1) اسد الغابہ (۶۲۷۶) استیعاب (۳۲۲۹)\n(2) السیرۃ النبویۃ (۲۴۹/۲)"}],[9179,"§۱۰۵۶۹ ۔ ابوالمنتفق(1)\nعبداللہ بن المنتفق العامری، ذکر ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۶۲۷۹) تجرید (۲۰۶/۲)"}],[9180,"§۱۰۵۷۰ ۔ ابوالمنتفق\nبقول بعض: ابن المنتفق۔ طبرانی بطریق عبداللہ بن عون بواسطہ محمد بن حجاجہ، وہ اپنے ایک دوست سے وہ بحوالہ اپنے والد جن کی کنیت ابوالمنتفق تھی روایت کرتے ہیں۔ فرمایا: میں مکہ آیا، رسول اللہ صلی اللہ علیہ وسلم کے بارے میں پوچھا، لوگوں نے بتایا: آپ عرفہ میں ہیں۔ میں آپ کے پاس پہنچا آپ کے قریب ہو کر پوچھنے لگا: مجھے کوئی عمل بتائیں جو اللہ تعالیٰ کے عذاب سے دور کر دے اور جنت میں پہنچا دے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ کی عبادت کرتے رہو، اس کے ساتھ کسی بھی چیز کو شریک نہ ٹھہراؤ“۔ (حدیث) اسی میں ہے: ”دیکھو! جو تمہیں لوگوں کا برتاؤ اپنے بارے میں اچھا لگے وہی ان سے کرو“۔(1) طبرانی فرماتے ہیں: اس کی سند میں ابن عون کو اضطراب ہوا ہے۔ انہوں نے اسے محمد بن مجادہ سے یاد نہیں کیا۔ بلکہ مجادہ نے اسے یاد رکھا ہے۔ پھر بطریق ہشام بن محمد بن مجادہ سے بواسطہ مغیرہ بن عبداللہ یشکری بحوالہ اپنے والد روایت کی ہے، فرمایا: میں کوفہ آیا، مسجد پہنچا، وہاں قیس کا ایک شخص تھا جسے ابن المنتفق کہا جاتا تھا۔ میں نے اسے کہتے سنا: مجھ سے رسول اللہ صلی اللہ علیہ وسلم کا حال بتایا گیا، چنانچہ میں مکہ میں آپ کو تلاش کرنے لگا لوگوں نے بتایا وہ منیٰ میں ہیں۔ (حدیث)۔۔۔","",{"fn":"(1) مسند احمد (۳۸۳/۶) مجمع الزوائد (۴۲/۱) المعجم الکبیر (۴۷۴، ۴۷۳/۱۹)"}],[9181,"§۱۰۵۷۱ ۔ ابوالمنذر\nیزید بن عامر بن حدیدہ انصاری ثم اسلمی، ناموں میں ذکر ہوا ہے۔"],[9182,"§۱۰۵۷۲ ۔ ابوالمنذر الجہنی\nابن مندہ نے ان کا ذکر کیا ہے اور بطریق عبدالرحمن بن محمد عرزی بحوالہ ابوالمندر جہنی روایت کی ہے۔ میں نے عرض کی: اللہ کے نبی! مجھے سب سے افضل کلمات سکھا دیجئے! آپ نے فرمایا: کہو! لا الہ الا اللہ وحدہ لا شریک لہ لہ الملک ولہ الحمد یحیی و یمیت بیدہ الخیر والیہ المصیر وھو علی کل شیء قدیر۔ روزانہ سو بار کہہ لیا کرو تم سے افضل عمل والا کوئی نہیں ہوگا۔ (حدیث) اسی میں ہے: اپنی دعا میں استغفار کو ہرگز نہ بھولنا کیونکہ یہ گناہوں کو مٹانے والا ہے۔"],[9183,"§۱۰۵۷۳ ۔ ابوالمنذر(1) (بے نسبت)\nمطین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور یہ روایت نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ان کی قبر پر تین مٹھی مٹی ڈالی تھی۔ طبرانی کی طویل روایت ہے کہ ہشام بن سعد کا قول ہے: ایک شخص نبی صلی اللہ علیہ وسلم کے پاس آ کر عرض کرنے لگا: اللہ کے رسول! فلاں شخص فوت ہو گیا ہے اس کا جنازہ پڑھا دیں۔ سیدنا عمر رضی اللہ عنہ بولے: وہ تو برے کاموں کی طرف میلان رکھتا تھا لہذا آپ اس کا جنازہ نہ پڑھائیں۔ تو اس شخص نے (جو اطلاع دینے آیا تھا) کہا: یا رسول اللہ! آپ کو یاد ہو گا گزشتہ رات یہ شخص پہرے میں تھا، تو رسول اللہ صلی اللہ علیہ وسلم اٹھ کھڑے ہوئے، میں آپ کے پیچھے چلنے لگا۔ جب آپ اس کی قبر کے پاس پہنچے تو بیٹھ گئے تدفین سے فراغت ہوئی تو آپ نے اس پر تین مٹھی مٹی ڈال کر فرمایا: لوگ اسے برا کہتے ہیں، لیکن میں اسے اچھا کہتا ہوں۔ سیدنا عمر رضی اللہ عنہ حیران ہو کر پوچھنے لگے: یا رسول اللہ صلی اللہ علیہ وسلم! وہ کیسے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”عمر! بس کرو! جس نے اللہ تعالیٰ کی راہ میں جہاد کیا اس کے لیے جنت واجب ہے۔“(2) ”ذیل“ میں ابو موسیٰ لکھتے ہیں: یہ متن حدیث ابو عطیہ سے بیان ہو چکا ہے۔ میں کہتا ہوں: حدیث ابو المنذر ابو داؤد نے ”مراسیل“ میں احمد بن منیع سے بواسطہ حماد بن خالد ابن نافع کی روایت کی طرح نقل کی ہے۔ اور ابو احمد نے الکنی میں نہیں نقل کی۔ رہی حدیث ابو عطیہ تو وہ واقعی جیسا کہ ابو موسیٰ کا قول ہے ان کے حالات میں بیان ہو چکی ہے۔ ابو احمد الحاکم نے ان کا ذکر کیا ہے کہ اس سے یہ مناسب لگتا ہے کہ صحابی ہیں، لیکن دو حدیثوں کا مخرج مختلف ہے اگرچہ متن کا سیاق قریب قریب ہے۔","",{"fn":"(1) اسد الغابہ (۶۲۸۲) تجرید (۲۰۶/۲)\n(2) ابوداؤد کتاب المراسیل (۵۴) المعجم الکبیر (۸۴۶/۲۲) مجمع الزوائد (۲۷۶/۵) جامع المسانید (۵۴۳)"}],[9184,"§۱۰۵۷۴ ۔ ابومنصور فارسی(1)\nدولابی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، اور حسن بن سفیان نے اپنی مسند میں بطریق لیث بواسطہ دوید بن نافع ان کا ذکر کیا ہے۔ فرماتے ہیں: میں نے ابومنصور سے کہا: ابومنصور! کاش آپ میں یہ پیش سختی نہ ہوتی؟ وہ فرمانے لگے: ”مجھے اپنی سختی اور غضب وغصہ فلاں فلاں چیز سے زیادہ پسند ہے۔ جبکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: سختی میری امت کے بہترین لوگوں میں ہو گی“۔(2) یہی روایت حسن بن سفیان نے ابو رجاء زہرائی، عبدالرحمن بن ابان، لیث، دوید سے بحوالہ ابو منصور، جنہیں شرف صحابیت حاصل ہے، نقل کی ہے۔ ایسا ہی بغوی نے زیاد بن ایوب سے بواسطہ عبدالرحمن نقل کیا ہے۔ فرماتے ہیں: مجھے ابومنصور کی اس کے علاوہ کوئی روایت معلوم نہیں۔ اور یہ مصر کے رہائشی تھے۔ امام بخاری رحمہ اللہ کا قول ہے: ان کی حدیث مرسل ہے۔ ابوعمر فرماتے ہیں، بقول بعض: ان کی حدیث مرسل ہے اور یہ صحابی نہیں۔(3) یہ روایت یونس بن محمد بن علی بن غراب اور کئی لوگوں نے لیث سے نقل کی ہے کسی نے سوائے عبدالرحمن بن ابان کے انہیں صحابی نہیں کہا۔ میں کہتا ہوں: حرف یاء میں یزید بن ابی منصور کے حالات(۹۳۱۸) میں ان کا ذکر ہو گا۔","",{"fn":"(1) اسد الغابہ (۶۲۸۳) تجرید (۲۰۶/۲)\n(2) کشف الخفاء (۴۲۳/۱)\n(3) تین الفاظ کے ہمراہ پائیں ہے۔"}],[9185,"§۱۰۵۷۵ ۔ ابومنظور(1) (بے نسبت)\nایک بے اصل روایت میں جسے ابو موسیٰ نے بطریق ابو حذیفہ عبد اللہ بن حبیب بن بدلی بحوالہ ابو منظور رکھا ہے ان کا ذکر آتا ہے۔ فرمایا: جب اللہ تعالیٰ نے اپنے رسول صلی اللہ علیہ وسلم کو وحی دی میرے خیال میں خیبر پر مال غنیمت میں ایک سیاہ گدھا ملا، آپ صلی اللہ علیہ وسلم نے اس سے گفتگو فرمائی۔ اس سے پوچھا: تمہارا کیا نام ہے؟ اس نے کہا: یزید بن شہاب، پھر بھی حدیث ذکر کی۔ آپ صلی اللہ علیہ وسلم نے اس کا نام یعفور رکھا۔ ابو موسیٰ اس حدیث کی تخریج کے بعد فرماتے ہیں: یہ حدیث انتہائی منکر ہے۔ اسناد اور متن بھی منکر ہے میں کسی کو اپنی طرف سے اس کی روایت کی اجازت نہیں دیتا۔ ہاں جس نے روایت کرنی ہے وہ اس پر میرا کلام و اعتراض بھی روایت کرے۔ یہ روایت ابو طاہر المخلص کی کتاب ”برکات النبی صلی اللہ علیہ وسلم“ میں ہے۔","",{"fn":"(1) اسد الغابہ (۶۲۸۴) تجرید (۲۰۶/۲)"}],[9186,"§۱۰۵۷۶ ۔ ابومنفعہ(1) الحنفی (فاسے)\nکلیب نامی حضرات کے حالات میں ان کا ذکر ہوا ہے۔ بغوی فرماتے ہیں: ابو منفعہ کا تعلق بنی حنیفہ سے ہے، بصری کے رہائشی ہیں۔ پھر بطریق حارث بن مرہ بواسطہ کلیب بن منفعہ ان کی حدیث نقل کی ہے۔ فرمایا: میرے دادا نبی صلی اللہ علیہ وسلم کے پاس آئے اور ان کی روایت میں حارث سے بواسطہ کلیب بحوالہ ان کے دادا ہے میں نے عرض کی: اللہ کے رسول! میں کس سے حسن سلوک کروں؟... (حدیث)(2)","",{"fn":"(1) اسد الغابہ (۶۲۸۵) تجرید (۲۰۶/۲)\n(2) ابوداؤد کتاب الادب باب بر الوالدین (۵۱۴۰)"}],[9187,"§۱۰۵۷۷ ۔ ابومنفعہ(1) (قاف سے) الانماری\nاحمد بن محمد بن عیسیٰ بغدادی نے ”الصحابۃ الذین نزلوا حمص“ نامی کتاب میں ان کا ذکر کیا ہے کہ اصحاب محمد صلی اللہ علیہ وسلم سے یہاں فروش ہونے والوں میں ابو منفعہ الانماری ہیں۔ ابوعمر لکھتے ہیں: ان کا نام نصر بن حارث ہے، حالانکہ ابن عیسیٰ کا قول ہے: ان کا نام بکر ہے یہی دار قطنی وغیرہ کا قول ہے۔ باب میں تذکرہ ہوا(۷۲۳) ہے۔ ابن الاثیر(2) کا گمان ہے یہ پہلے والے ہیں حالانکہ ایسا نہیں۔","",{"fn":"(1) اسد الغابہ (۶۲۸۶)\n(2) اسد الغابہ (۱۰۹/۵)"}],[9188,"§۱۰۵۷۸ ۔ ابوالمنہال (بے نسبت)\nابو بشر دولابی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور ان کی کوئی حدیث نہیں نقل کی۔"],[9189,"§۱۰۵۷۹ ۔ ابوالمنیب الکلبی(1)\nامام بخاری رحمہ اللہ نے ”الکنی“ میں ان کا ذکر کیا ہے اور بطریق بقیہ بن ولید بواسطہ مسلم بن زیاد روایت کی ہے، فرمایا: میں نے چار صحابہ نبی صلی اللہ علیہ وسلم کو دیکھے ان میں روح بن یسار، اور ابو فیض کلبی تھے یہ لوگ عمامے باندھتے تھے اور ان کے شملے پیچھے گراتے تھے۔ گھٹنوں تک ان کے لباس ہوتے۔ یہی روایت ابن مندہ نے بطریق بقیہ نقل کی ہے۔ انہوں نے فرمایا: مجھ سے مسلم بن زیاد نے بیان کیا۔","",{"fn":"(1) اسد الغابہ (۶۲۸۷) استیعاب (۳۲۳۶) تجرید (۲۰۶/۲)"}],[9190,"§۱۰۵۸۰ ۔ ابوالمهاجر (بے نسبت)\nدولابی نے ”الکنی“ میں ان کا ذکر کیا ہے اور عیینہ بن سعید کے طریق سے بواسطہ مہاجر بن غیب بحوالہ اپنے والد روایت کی ہے کہ ایک شخص رسول اللہ صلی اللہ علیہ وسلم کے پاس آ کر عرض کرنے لگا: میں جب نماز شروع کرتا ہوں مجھے یاد نہیں رہتا دو پڑھی ہیں یا ایک پڑھی ہے۔"],[9191,"§۱۰۵۸۱ ۔ ابوموسیٰ اشعری\nعبداللہ بن قیس۔ نام وکنیت دونوں سے مشہور ہیں۔ لیکن کنیت زیادہ مشہور ہے، پہلے ذکر ہوا ہے۔"],[9192,"§۱۰۵۸۲ ۔ ابوموسیٰ انصاری(1)\nابن مندہ نے ان کا ذکر کیا ہے اور بطریق داری بواسطہ نافع بن سہیل بن مالک بحوالہ ابوموسیٰ انصاری صحابی رسول صلی اللہ علیہ وسلم روایت کی ہے۔ وہ رسول اللہ صلی اللہ علیہ وسلم کے صحابہ رضی اللہ عنہم میں سے بہترین آدمی تھے۔ فرماتے ہیں: ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھے تھے، آپ نے فرمایا: ایمان کی چکی گھوم رہی ہے لہذا تم قرآن کی چکی کے ساتھ گھومو، جہاں بھی وہ گھومے۔ (حدیث)(2) عبداللہ بن واصل جو اس کے داری سے راوی ہیں فرماتے ہیں: میں نے محمد بن اسماعیل بخاری سے اس کا ذکر کیا تو انہوں نے اس کا انکار کیا۔ انہیں ابو موسیٰ انصاری اور حاتم بن ربیعہ کے بارے میں کچھ معلوم نہیں۔ میں کہتا ہوں: یہی روایت ابو نعیم نے دوسری سند سے بواسطہ محمد بن یزید نقل کی ہے لیکن انہوں نے کہا: جابر بن ربیعہ سے بواسطہ ابو انس اور نافع بن سہیل کے بجائے محمد بن نافع بن حارث کہا۔ واللہ اعلم! ابن مندہ کا بیان ہے کہ محمد بن اسماعیل جعفری نے یہ روایت محمد بن جعفر، مالک سے انہوں نے اپنے چچا ابو سہیل کہ ہم سے انس بن مالک نے بیان کیا۔ فرماتے ہیں: اس سے احتمال ہے کہ کسی راوی نے سیدنا انس بن مالک کی کنیت ان کے بیٹے موسیٰ کی وجہ سے ابو موسیٰ کہہ دی ہو۔ میں کہتا ہوں: ابو نعیم کی روایت سے اس احتمال کی تردید ہوتی ہے اور سند مالک تک غیر معتبر راوی ہیں۔","",{"fn":"(1) اسد الغابہ (۶۲۹۰) تجرید (۲۰۷/۲)\n(2) اسد الغابہ (۱۱۱/۵)"}],[9193,"§۱۰۵۸۳ ۔ ابوموسیٰ الحکمی(1)\nبغوی نے ان کا ذکر کیا ہے، لیکن ان کی کوئی روایت نہیں ذکر کی۔ ابو نعیم نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ امام بخاری رحمہ اللہ نے الکنی میں ان کا ذکر کیا ہے کہ مجھے ان کا صحابی ہونا معلوم نہیں۔ ابن مندہ بطریق حسن بن حبیب، مدب، حجاج بن فرافصہ، بواسطہ عطیہ بن ابی سفیان روایت کرتے ہیں کہ ہم مروان کے پاس تھے اتنے میں ان کے پاس ابو موسیٰ آگئے، مروان نے ان سے کہا: کیا نبی صلی اللہ علیہ وسلم کے عہد میں قدر (تقدیر) کا ذکر تھا؟ انہوں نے فرمایا: نبی صلی اللہ علیہ وسلم نے فرمایا ہے: یہ امت اس وقت تک مضبوط رہے گی جب تک تقدیر کو جھٹلانا نہیں کہے گی۔(2) ابو نعیم کے طرز سے معلوم ہوتا ہے کہ یہ ان کے نزدیک تابعی ہیں۔ کیونکہ انہوں نے ان کا ذکر ان تابعین کے بعد کیا ہے جن کا نام مشہور نہیں۔","",{"fn":"(1) اسد الغابہ (۶۲۹۱) تجرید (۲۰۷/۲)\n(2) التاریخ الکبیر (۶۹/۸) اسد الغابہ (۱۱۱/۵)"}],[9194,"§۱۰۵۸۴ ۔ ابوموسیٰ الغافقی(1)\nمالک بن عبادہ بقول بعض: مالک بن عبداللہ۔ ابن ابی عاصم وغیرہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، پھر سب نے بطریق عمرو بن حارث، یحییٰ بن میمون سے انہوں نے ان سے بیان کیا وہ حمیری نے ان سے بیان کیا کہ وہ مالک بن عبادہ غافقی کے پاس تھے اور عقبہ بن عامر واقعہ بیان کر رہے تھے تو مالک بن عبادہ نے فرمایا: تمہارا یہ ساتھی غافل ہے یہ ہلاک ہونے والا ہے کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے حجۃ الوداع کے موقع پر ہمیں وصیت کی تھی: ”تم لوگ قرآن نہ چھوڑنا (ادھر ادھر کے واقعات کے بجائے قرآن بیان کرنا) اور جس نے میرے متعلق جھوٹ بولا اس کا ٹھکانہ جہنم ہے۔“(2) یہ سیاق حاکم ابو احمد کا ہے، امام احمد نے بطریق لیث، عمرو سے بواسطہ یحییٰ بن میمون نقل کیا ہے کہ ابو موسیٰ غافقی نے عقبہ بن عامر کو منبر پر چند احادیث بیان کرتے ہوئے سنا تو فرمایا: ابو موسیٰ غافقی سے مروی ہے تمہارا یہ ساتھی اور رکھنے والا ہے یا ہلاک ہونے والا ہے، پھر وہ حدیث ذکر کی۔ محمد بن ربیع حمیری مصر فروش ہونے والے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ مالک بن عبداللہ معافری(۱۸۵۰) کے حالات میں ان کی حدیث بیان ہو چکی ہے۔","",{"fn":"(1) اسد الغابہ (۶۲۹۲) تجرید (۲۰۷/۲)\n(2) مسند احمد (۳۳۴/۴)"}],[9195,"§۱۰۵۸۵ ۔ ابومومل\nسفاقسی جو ابن التین کے نام سے مشہور اور شارح بخاری ہیں۔ انہوں نے کتاب المکاتبہ میں ان کا ذکر کیا۔ فرماتے ہیں، بقول بعض: اسلام میں سب سے پہلے جس سے عقد کتابت کیا گیا وہ ابو مومل ہیں، نبی صلی اللہ علیہ وسلم نے فرمایا تھا: ابو مومل کی امداد کرو، ان کی مدد کی گئی تو انہوں نے مالی کتابت ادا کر دیا جس میں سے ان کے پاس کچھ رقم بچ بھی گئی۔ نبی صلی اللہ علیہ وسلم نے ان سے فرمایا: ”اسے اللہ کی راہ میں صرف کر دو“۔"],[9196,"§۱۰۵۸۶ ۔ ابومویہبہ(1)\nبقول بعض: ابو موہبہ اور ابو موہوب، یہ واقدی کا قول ہے: مولا رسول اللہ صلی اللہ علیہ وسلم بقول بلاذری: مزینہ کے پروردہ تھے۔ غزوہ مریسیع میں شریک ہوئے اور سیدہ عائشہ رضی اللہ عنہا کے کوچوان تھے ان سے عبداللہ بن عمرو بن عاص نے جو ان کے ہم عمر روایت کی ہے امام احمد نے یعقوب بن ابراہیم بن سعد سے بحوالہ ان کے والد، داری اور خلیفہ بن خیاط نے سلیمان سے دونوں نے محمد بن اسحاق(2) سے وہ فرماتے ہیں: مجھے عبداللہ بن عمرو بن ربیعہ نے حدیث سنائی۔ داری کی روایت میں ہے ہم سے عبداللہ بن عمرو بن علی بن عدی نے عبید بن حنین کے حوالہ سے بیان کیا ہے اور اسی طرح داری کی روایت میں ہے: عبید مولا ابو الحکم بن العاصی سے بواسطہ عبداللہ بن عمرو بن العاص بحوالہ ابو مویہبہ جو مولا رسول اللہ صلی اللہ علیہ وسلم ہیں مروی ہے۔ فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مجھے بیدار کر کے فرمایا: ابو مویہبہ! مجھے حکم ملا ہے کہ میں اہل بقیع کے لیے استغفار کروں۔ پھر میں نکلا۔۔۔ اس کے بعد بھی حدیث ذکر کی۔ اسی میں ہے حج کے وقت آپ کی اسی بیماری کے آثار شروع ہو گئے جس میں آپ صلی اللہ علیہ وسلم نے وفات پائی تھی۔ یہی روایت حاکم نے دوسری سند کے ذریعہ ابراہیم بن سعد سے بواسطہ محمد بن اسحاق نقل کی ہے کہ عبداللہ بن عمر بن حفص سے بواسطہ عبید بن حنین انہی الفاظ میں منقول ہے۔ ان کا ابن عمر بن حفص کہنا وہم ہے۔ ابو نعیم لکھتے ہیں: ابن اسحاق کے اکثر تلامذہ نے اسی طرح روایت کی ہے جبکہ محمد بن سلمہ نے ان کے خلاف روایت کی ہے۔ وہ فرماتے ہیں: ابو اسحاق عن ابی مالک بن ثعلبہ عن عمرو بن الحکم بن ثوبان عن عبداللہ بن عمرو، وہ لگتا ہے اس روایت میں ابن اسحاق کے دوشخ (استاد) ہیں اگر یہ بات کتابوں میں محفوظ ہے۔ تو حاکم نے اسے مستدرک میں بروایت یونس بن بکیر نقل کیا ہے۔ وہ فرماتے ہیں: محمد بن اسحاق عن عبداللہ بن ربیعہ، شاید انہیں ان کے جد امجد کی طرف منسوب کیا ہے۔ عن عبید بن ابی الحکم، مستدرک میں ایسا ہی ہے جبکہ درست یوں ہے: عن عبید مولا ابی الحکم جیسا کہ پہلے بیان ہوا ہے اسی طرح امام احمد نے بطریق ابو یعلی بن عطاء، عن عبید بن حنین عن مویہبہ روایت کی ہے، دونوں میں عبداللہ بن عمرو کا واسطہ نہیں۔ ہم نے حدیث میں بطریق تمیم بن یہ بواسطہ ان کے کسی شیخ بحوالہ محمد بن سلمہ سنا ہے۔ میں کہتا ہوں: عقیلی عقیلیات کی طرف منسوب ہے جو بنی عبد شمس کا بطن ہے۔ بغوی لکھتے ہیں: اس سند میں کسی کی روایت میں لکھا ہے: عن عبید بن حنین (حاء اور دو نونوں سے) اسی پر ابن عبدالبر نے اعتماد کیا ہے جو لفظی غلطی ہے۔ حالانکہ یہ نام عبید بن حبیر ہے۔ جس سے ابن فتحون نے خبردار کیا ہے اور یہی عقیلی اور عبد شمس ہیں۔","",{"fn":"(1) اسد الغابہ (۶۲۹۳) تجرید (۲۰۷/۲)\n(2) السیرۃ النبویۃ (۶۱۸/۴، ۲۱۹)"}],[9197,"§۱۰۵۸۷ ۔ ابومحمد\nعبداللہ بن ظلیبہ، عبداللہ بن عامر بن ربیعہ، عبداللہ بن نوفل بن حارث بن ہشام، عبدالرحمن بن عبد القاری، عبید اللہ بن عباس بن عبدالمطلب۔ سب کا ناموں میں ذکر ہو چکا ہے۔"],[9198,"§۱۰۵۸۸ ۔ ابومراوح الغفاری(1)\nمولا ہیں۔ بقول بعض: نام سعد ہے۔ ابو احمد الحاکم نے ان کا ذکر کیا ہے کہ عہد رسالت میں پیدا ہوئے تھے۔ میں کہتا ہوں: سیدنا ابوذر، ابو الدرداء، لیث اور حمزہ بن عمرو اسلمی سے روایت کرتے ہیں۔ ان سے عروہ، زید بن اسلم اور عمران بن ابی انس نے روایت کی ہے۔ بعض نے دونوں کے درمیان سلیمان بن یسار کو داخل کیا ہے، عجلی کا قول ہے: یہ مدنی اور ثقہ تابعی ہیں۔ قسم اول میں ابو مراوح لیثی کے متعلق بیان ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۶۲۲۹) استیعاب (۳۲۰۹) تجرید (۲۰۱/۲)"}],[9199,"§۱۰۵۸۹ ۔ ابومحرز البکری(1)\nامام بخاری رحمہ اللہ نے(2) ”مفارید الکنی“ میں ان کا ذکر کیا ہے کہ وہ جاہلیت پایا ہے۔ ان سے ان کا بیٹا عبداللہ روایت کرتا ہے۔","",{"fn":"(1) اسد الغابہ (۶۲۲۳) تجرید (۲۰۱/۲)\n(2) التاریخ الکبیر (۷۴/۸)"}],[9200,"§۱۰۵۹۰ ۔ ابومحمد قعقسی الراجز\nزہیر بن بکار نے ان کے اشعار نقل کیے ہیں جو انہوں نے اس موقع پر کہے تھے جب خالد بن ولید رضی اللہ عنہ نے بطاح میں بنی اسد کو طلیحہ بن خویلد کو فتنہ ارتداد میں شکست دی تھی۔ وہ کہتے ہیں:  ”جس دن خالد سے بیعت کی گئی تو ہم اس قبیلے کی طرف بڑھے، اور مقام بطاح کے کنارے خون سے لبالب بھرے تھے۔ ہم نے نیزوں کی نوکوں سے اس کے کنویں اور کنارے کھود ڈالے اور پانی بدبودار ہو گیا تھا“۔"],[9201,"§۱۰۵۹۱ ۔ ابومخشی نمیری\nابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے کہ وثیر نے کتاب الردۃ میں جو روایت نقل کی ہے اس سے معلوم ہوتا ہے انہیں دور نبوی نصیب ہوا ہے پھر بطریق مضارب بن عبداللہ روایت کی ہے کہ ابو مخشی نمیری ابو عبیدہ بن الجراح کے ساتھ شام میں تھے کچھ ایام ان کے احباب نے انہیں نہ پایا ان کے بارے پوچھ گچھ کرنے لگے لیکن کوئی اتا پتا نہ ملا، وہ بڑے بہادر تھے ایک دفعہ یہ لوگ بیٹھے ان کے فضل و کمال کا تذکرہ کر رہے تھے اور ان کے بارے میں نا امید ہو چکے تھے ان لوگوں کا خیال تھا وہ دھوکے سے شہید کر دیے گئے ہیں کہ وہ اچانک لوگوں کے سامنے آ گئے، ان کے پاس دو پتے تھے ان جیسے لوگوں نے نہیں دیکھے تھے۔ نہ ان سے طویل اور نہ عریض اور ان سے بڑھ کر خوشبودار، جن کا رنگ انتہائی سبز اور جو بہت عمدہ تھے۔ لوگوں نے ان سے پوچھا تو وہ بتانے لگے کہ وہ ایک کنویں میں گر گئے تھے وہ کنواں اتنا بڑا تھا کہ یہ اس میں چلتے گئے ایک باغ ملا اس سے اچھا انہوں نے نہیں دیکھا ہو گا۔ جس میں وہ کئی دن مقیم رہے پھر ان کے پاس کوئی شخص آیا جس نے انہیں وہاں سے نکال لیا۔ فرماتے ہیں: یہ دو پتے اس بیری کے ہیں جس کے نیچے میں بیٹھا تھا۔ سیدنا ابو عبیدہ نے سیدنا عمر رضی اللہ عنہ کی طرف یہاں یہ پیام بھیجا کہ کعب سے پوچھیں، انہوں نے فرمایا کہ ہم سابقہ کتاب میں یہ بات دیکھتے ہیں کہ اس امت کا ایک شخص دنیا میں ہوتے ہوئے فتح روم کے بعد جنت میں داخل ہو گا۔ ابن فتحون فرماتے ہیں: وثیر کے علاوہ متعدد لوگوں نے یہ واقعہ نقل کیا ہے کسی نے ابو مخشی نہیں کہا۔"],[9202,"§۱۰۵۹۲ ۔ ابومرشد خولانی\nدور نبوی پایا ہے۔ ابو اسماعیل ازدی نے صعب بن زہیر، مہاجر بن صیفی بواسطہ راشد بن عبدالرحمن بحوالہ ان کے ذکر کیا ہے کہ انہوں نے یرموک میں مسلمانوں کی خوشخبری کا خواب دیکھا تھا۔"],[9203,"§۱۰۵۹۳ ۔ ابومریم\nزبر بن جیش اسدی، ناموں میں تذکرہ ہوا ہے۔"],[9204,"§۱۰۵۹۴ ۔ ابومریم حنفی یمامی\nدولابی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے کہ ان کا نام ایاس بن صبیح ہے، مسیلمہ کذاب کے رفیق تھے پھر اسلام لے آئے اس کے بعد بصرہ کے قاضی مقرر ہوئے۔ عمر بن شبہ لکھتے ہیں: رامہر مز کی فتح ان کے ہاتھ ہوئی ہے ناموں میں تذکرہ ہو چکا ہے۔"],[9205,"§۱۰۵۹۵ ۔ ابومریم الخصی(1)\nدور نبوی پایا ہے۔ ابن مندہ نے ان کا ذکر کیا ہے اور بطریق اوزاعی، سلیمان بن موسیٰ سے روایت کی ہے، فرمایا: میں نے طاؤس سے کہا کہ ابو مریم خصی نے مجھے بتایا کہ جنہوں نے دور نبوی پایا ہے۔ وہ بولے: مجھے کسی غیر خصی کا حوالہ دو۔(2)","",{"fn":"(1) اسد الغابہ (۶۲۳۷) تجرید (۲۰۲/۲)\n(2) جامع المسانید (۴۷۵/۱۴) اسد الغابہ (۹۵/۵)"}],[9206,"§۱۰۵۹۶ ۔ ابومریم کندی(1)\nنام عبید تھا، دور نبوی نصیب ہوا ہے۔ اور سیدنا عمر رضی اللہ عنہ کے ساتھ بیت المقدس میں نماز پڑھی ہے۔ ابن مندہ نے بطریق عثمان بن عطا خراسانی بواسطہ زیاد بن ابی سودہ بحوالہ ابو مریم روایت کی ہے، فرمایا: میں سیدنا عمر کے ساتھ داؤد علیہ السلام والی محراب میں داخل ہوا، آپ نے سورہ ص پڑھی، سجدہ کیا، یہی روایت سیف نے فتوح میں ربیع بن نعمان سے بحوالہ ابو مریم مولا سلامہ نقل کی ہے۔ فرمایا: میں سیدنا عمر رضی اللہ عنہ کے ساتھ ایلیا (بیت المقدس) میں داخل ہوا آپ چلتے چلتے مسجد میں پہنچے اور داؤد علیہ السلام کی محراب تک جا کے ٹھہر گئے، پھر سورہ ص پڑھ کر سجدہ کیا تو ہم نے بھی آپ کے ساتھ سجدہ کیا۔ امام بخاری رحمہ اللہ فرماتے ہیں: ابو مریم سیدنا عمر رضی اللہ عنہ سے روایت کرتے ہیں۔ جبکہ ان سے زیاد بن ابی سودہ روایت کرتے ہیں، اہل شام سے ان کی حدیث مروی ہے۔","",{"fn":"(1) اسد الغابہ (۶۲۴۱) استیعاب (۳۲/۵) تجرید (۲۰۲/۲)"}],[9207,"§۱۰۵۹۷ ۔ ابومسافع (بے نسبت)\nدور جاہلیت پایا ہے اور خلافت فاروقی کے کسی غزوہ میں شرکت کی۔ ابو احمد الحاکم نے ان کا تذکرہ کیا ہے اور بطریق ابو اسحاق، بواسطہ ابو الصلت اور ابو مسافع روایت کی ہے، دونوں فرماتے ہیں: سیدنا عمر بن خطاب رضی اللہ عنہ نے ہماری طرف پیام بھیجا اس وقت ہم لوگ نہاوند میں تھے: ”نماز بروقت ادا کرو اور جب دشمن سے مقابلہ ہو تو نہ بھاگنا اور جب مال غنیمت حاصل کر لو اس میں خیانت نہ کرو“۔"],[9208,"§۱۰۵۹۸ ۔ ابومسلم خولانی\nعبداللہ ابن ثوب۔ ابن السکن نے ان کے والد کا نام مسلم بتایا ہے، پہلے تذکرہ ہوا ہے۔"],[9209,"§۱۰۵۹۹ ۔ ابومسلم الجلیلی(1)\nبقول بعض الجبلی۔ ابن عساکر کی تحقیق کے مطابق پہلا نام زیادہ صحیح ہے۔ دور نبوی پایا تھا لیکن اس میں اسلام نہیں لائے بلکہ عہد معاویہ(2) میں اسلام قبول کیا۔ کسی نے عہد صدیقی اور عہد فاروقی بھی لکھا ہے۔ بقول امام بخاری: کعب الاحبار کی طرح تھے، کنیت ابو مسلم تھی عہد صدیقی میں مسلمان ہوئے تو آپ نے ان کی کنیت ابو مسلم رکھ دی۔ امام بخاری رحمہ اللہ فرماتے ہیں: ادرع خولانی سے مروی ہے کہ یہ صدیق اکبر کے بعد مسلمان ہوئے۔ بغوی کی روایت ہے کہ ابو مسلم الجلیلی امیر معاویہ کے دور میں مسلمان ہوئے تو ابو مسلم خولانی نے ان سے فرمایا: عہد نبوی میں اور عہد صدیقی اور فاروقی میں تم نے اسلام کیوں نہیں قبول کیا؟ ابن مندہ نے اسی کے ساتھ ان کا ذکر کیا ہے کہ عہد معاویہ میں اسلام لائے۔ عبد بن حمید نے اپنی تفسیر میں اور تمام نے اپنے فوائد میں بطریق صالح المری، ابو عبداللہ الشامی سے بواسطہ حکول بحوالہ ابو مسلم خولانی روایت کی ہے کہ ان کی ملاقات ابو مسلم الجبلی سے ہوئی وہ راہب تھے، اپنے عبادت خانے سے عہد فاروقی میں نیچے اترے اور اسلام قبول کیا۔ آپ نے ان سے فرمایا: تمہیں اپنے عبادت خانے سے کس چیز نے اتارا؟ عہد نبوی اور عہد صدیقی میں تم نے اسلام نہیں قبول کیا؟ اب کس بنا پر اسلام لائے ہو؟ وہ کہنے لگے: ابو مسلم! میں نے اللہ کی کتاب میں پڑھا ہے کہ قیامت کے روز یہ امت تین حصوں میں تقسیم ہو گی، ایک حصہ بغیر حساب جنت میں جائے گا، ایک حصہ سے اللہ تعالیٰ بلا حساب لے گا اور ایک حصہ سے اللہ تعالیٰ جیسا چاہے گا حساب لے گا، پھر انہیں معاف کر دے گا۔ جس سے میں نے اندازہ لگایا کہ پہلی قسم تو گزر گئی، میں امید کرتا ہوں کہ میں دوسری قسم میں شامل ہوں گا۔ اور تیسری مجھ سے نہ چھونے اس لئے میں مسلمان ہو گیا۔ صالح ضعیف راوی ہے۔ یہی روایت ابن عساکر نے دوسری سند کے ذریعہ سعید الجریری سے بحوالہ عقبہ بن وشاح نقل کی ہے کہ ابو مسلم خولانی کا ایک یہودی پڑوسی تھا جس کی کنیت ابو مسلم تھی، خولانی اس سے فرماتے: اسلام لے آؤ کامیاب ہو جاؤ گے، تو وہ آگے سے کہتا: میں ایک دین پر ہوں۔ پھر ایک دفعہ ان کا گزر ہوا تو اسے نماز پڑھتے دیکھا، اس سے پوچھا تو اس نے بتایا میں نے تورات میں پڑھا ہے جس میں تحریف و تبدیل نہیں ہوئی کہ یہ امت تین گروہوں میں منقسم ہو گی پھر اس کا مفہوم نقل کیا۔ اور تیسری قسم کے بارے میں کہا: ان کے بوجھ ان کی پیٹھوں پر لدے ہوں گے، فرشتے کہیں گے: اللہ! یہ تیرے بندے تیری توحید کے قائل تھے۔ اللہ تعالیٰ فرمائیں گے: ان کے بوجھ اتار کر مشرکین پر دھر دو، پھر وہ جنت میں چلے جائیں گے۔ (یہ روایت ﴿وَلَا تَزِرُ وَازِرَۃٌ وِزْرَ اُخْرٰی﴾ کے نہیں، کیونکہ وہاں اپنا بوجھ دوسرے کو دینے کی نفی ہے اور یہاں انہوں نے اپنے بوجھ خود اٹھائے تھے، اور انہوں نے خود کسی سے نہیں کہا، بلکہ اللہ کا حکم ہوا تو مشرکین پر لاد دیا گیا۔ واللہ اعلم! [عامر تقی ندوی]) ابن السکن فرماتے ہیں: دور جاہلیت پایا ہے۔ بقول بعض: صحابی ہیں۔ پھر بطریق معاویہ بن یحییٰ صدی، یحییٰ بن جابر، خالد بن معدان، جبیر بن نفیر ان کے سلسلہ سند سے بحوالہ ابو مسلم جلیلی روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: مشرکین کے بچے رحمن کے عرش تلے ہوں گے، ان کے نام تیرہ(۱۳) سے زیادہ نہ ہوں گے۔ میں کہتا ہوں: یہ مرسل روایت ہے، اس واسطے کہ جن لوگوں نے ان کے نبی صلی اللہ علیہ وسلم کے بعد مسلمان ہونے کی وضاحت کی ہے وہ زیادہ مضبوط اور زیادہ حافظے والے ہیں اور اس میں ان کے سماع کی صراحت نہیں۔ ابن سمیع کا قول ہے: انہوں نے کعب کو نبی صلی اللہ علیہ وسلم کے پاس بھیجا تھا لیکن ان کی ملاقات نہ ہو سکی۔ بقول عجلی: شامی ثقہ تابعی ہیں۔","",{"fn":"(1) اسد الغابہ (۶۲۴۶) تجرید (۲۰۲/۲)\n(2) جامع المسانید (۹۱۵/۱۴) اسد الغابہ (۹۸/۵)"}],[9210,"§۱۰۶۰۰ ۔ ابومشجعہ بن ربعی الجہنی\nدور نبوی پایا ہے اور جابیہ میں خطبہ فاروقی میں شریک تھے، اور اس کے راوی ہیں جسے طویل نقل کیا ہے۔ ابن عساکر نے اسے درج کیا ہے، ابو زرعہ دمشقی نے یوں نقل کیا ہے: ہم سیدنا عثمان رضی اللہ عنہ کے ساتھ ایک بیمار کی عیادت کے لیے گئے، پھر ایک حدیث ذکر کی۔ انہیں ابو درداء اور سلمان فارسی رضی اللہ عنہ سے روایت حاصل ہے، ان کی حدیث کا راوی سوائے ان کے بیٹے کے مجھے معلوم نہیں اور ان سے روایت کرنے والا سلیمان ضعیف ہے۔"],[9211,"§۱۰۶۰۱ ۔ ابومعبد الجہنی\nعبداللہ بن حکیم، ناموں میں تذکرہ ہوا ہے۔"],[9212,"§۱۰۶۰۲ ۔ ابومغفر تمیمی\nدور نبوی پایا ہے۔ سیف بن عمر نے فتوح میں سیدنا ابوذر رضی اللہ عنہ کی وفات کے واقعہ میں ان کا ذکر کیا ہے، واقعہ کے آخر میں ہے: ابن مسعود کے ساتھ سیدنا ابوذر رضی اللہ عنہ کی وفات میں حاضر ہونے والوں کی تعداد تیرہ(۱۳) تھی، ان میں ابو مغفر تمیمی بھی تھے۔ سیف ہی نے ان کا ذکر ان لوگوں میں کیا ہے جنہوں نے دور فاروقی میں شراب پی لی تھی اور انہیں حد لگائی گئی۔ جس کے متعلق ابو مغفر نے کہا:  ”ہم نے صبر کیا اور وہ صبر ہماری ہی عادت تھا، جن راتوں میں ہم مہمان نوازی اور مشروبات حاصل کرنے میں کامیاب ہوئے۔ وہاں کسی حلال چیز میں مقابلہ نہ تھا جیسے شام میں دس ماہ کی گابھن اونٹنیوں کی بڑی تعداد میں مقابلہ تھا“ (دوسرے نسخے میں الفاظ کی تھوڑی تبدیلی ہے)۔"],[9213,"§۱۰۶۰۳ ۔ ابوالمقشعر"],[9214,"§۱۰۶۰۴ ۔ ابوالمهلب الجرمی\nابو قلابہ کے چچا۔ دور نبوی پایا ہے۔ ابن سعد نے اہل بصرہ کے تابعین میں سے پہلے طبقہ میں ان کا ذکر کیا ہے کہ معتجز اور کم حدیث بیان کرنے والے ہیں۔ سیدنا عمر رضی اللہ عنہ سے روایت حاصل ہے۔ ان کے نام میں اختلاف ہے، بعض: عمرو بن معاویہ بن زید لکھا ہے۔ جس پر ابن حبان نے ”ثقات“ میں اعتماد کیا ہے۔ بقول بعض: معاویہ بن عمرو بن زید جسے ابن عبدالبر نے صحیح قرار دیا ہے۔ ایک قول ہے: عبدالرحمن بن عمرو ابن معاویہ انضر۔ ابی بن کعب، عثمان رضی اللہ عنہ وغیرہ سے بھی روایت لیتے ہیں۔ ان سے محمد بن سیرین وغیرہ نے روایت کی ہے۔"],[9215,"§۱۰۶۰۵ ۔ ابومَیسّرہ\nعمرو بن شرجیل، ناموں میں ذکر ہوا ہے۔"],[9216,"§۱۰۶۰۶ ۔ ابومالک غفاری(1)\nغزوان نامی مشہور تابعی ہیں۔ ایک مرسل حدیث بیان کی ہے جس کی وجہ سے عسکری نے صحابہ رضی اللہ عنہم میں ان کا ذکر کر دیا ہے۔ پھر یہ روایت کی ہے کہ نبی صلی اللہ علیہ وسلم نے سیدنا حمزہ رضی اللہ عنہ کا جنازہ پڑھایا، ان کے ساتھ سات نفسیں لائی جاتیں اور آخر تک آپ نے سب کی نماز جنازہ پڑھا دی (دوسروں کی میتیں لائی جاتیں اور جنازے کے بعد اٹھا لی جاتیں جبکہ امیر حمزہ رضی اللہ عنہ کی میت وہیں رکھی رہی)۔ ابن الاثیر(2) نے اپنے سے پہلے لوگوں کی کتابوں پر اپنے استدراک میں ان کا ذکر کیا ہے لیکن اس کی علت انہیں بھی نہ سمجھ آئی، رہے ذہبی(3) تو وہ لکھتے ہیں: شاید یہ تابعی ہیں۔","",{"fn":"(1) اسد الغابہ (۶۲۱۲) تجرید (۱۹۹/۲)\n(2) اسد الغابہ (۸۷/۵)\n(3) التجرید (۱۶۹)"}],[9217,"§۱۰۶۰۷ ۔ ابومالک دمشقی(1)\nحاکم فرماتے ہیں: بقول امام بخاری رحمہ اللہ ان کی حدیث مرسل ہے، یہی عسکری نے کہا ہے، جبکہ ابن مندہ لکھتے ہیں: ان کا صحابہ میں ذکر ملتا ہے حالانکہ ثابت نہیں۔ معاویہ بن صالح بواسطہ عبداللہ بن دینار بحوالہ ان کے روایت کرتے ہیں۔ ابو عمر انہیں نفی لکھتے ہیں کہ تابعی ہیں جو مرسل روایت کرتے ہیں، ایک قول کے مطابق: صحابی ہیں۔ صحیح یہی ہے کہ ان کی حدیث مرسل ہے اور یہ صحابی نہیں، معاویہ بن صالح بواسطہ عبداللہ بن دینار بحوالہ ان کے والدین کو ناراض کرنے والے کے بارے میں نبی صلی اللہ علیہ وسلم کا ارشاد نقل کرتے ہیں اور اس کے بارے میں جو بروقت کی جماعت کی امامت کرے اور جو بالغ عورت بغیر اوڑھنی کے نماز پڑھے ان لوگوں کی نماز قبول نہیں۔ میں کہتا ہوں: قسم اول میں ابو مالک نخعی(۱۰۴۹۰) کا تذکرہ ہوا ہے۔ اور ابن السکن نے ان کا ذکر کیا ہے اور ان کی حدیث بھی نقل کی ہے اور نبی صلی اللہ علیہ وسلم سے ان کے سماع کی صراحت بھی کی ہے۔ جس سے ابو عمر نادانستہ طور پر نابلد رہے۔ اور صرف ان کے ذکر پر اکتفا کیا یا دونوں کو ایک سمجھ لیا ہے جو بعید ہے۔ لیکن ظاہر یہی ہے کہ یہ اور ہیں۔ واللہ سبحانہ وتعالیٰ اعلم!","",{"fn":"(1) اسد الغابہ (۶۲۱۸) تجرید (۱۹۹/۲)"}],[9218,"§۱۰۶۰۸ ۔ ابومبتذر\nبعد والی شخصیت میں ان کا تذکرہ ہوتا ہے۔"],[9219,"§۱۰۶۰۹ ۔ ابوالمبتذل(1)\nیحییٰ بن عبدالوہاب بن ابی عبداللہ بن مندہ نے اپنے دادا کی کتاب پر اپنے استدراک میں ان کا ذکر کیا ہے۔ ابو موسیٰ نے بھی ان کا اتباع کیا اور بطریق احمد بن سلیمان بحوالہ ابوالمبتذل صاحب رسول اللہ صلی اللہ علیہ وسلم روایت کی ہے وہ افریقہ میں ہوا کرتے تھے، پھر یہ حدیث ذکر کی ہے جس میں صبح کے وقت یہ کہنے کی فضیلت ہے ”رضیت باللہ رباً“۔(2) ابو موسیٰ فرماتے ہیں: اسے احمد بن الطیب نے رشیدین سے نقل کیا تو کہا: ابوالمبتذل یا ابوالمبتذل۔ یحییٰ بن غیلان المبتذل یا المبتذل سے روایت کرتے ہیں اور ابو عبداللہ بن مندہ نے ناموں میں ان کا ذکر کیا ہے۔ میں کہتا ہوں: بات یہی ہے، احمد بن سلیمان والی روایت میں لفظی غلطی ہے۔ میں نے یہی نام حافظ ابراہیم صریفینی کے قلم سے المبتذل لکھا دیکھا ہے، رہی احمد بن طیب والی روایت المبتذل یا المبتذل اور یحییٰ کی روایت طیب کی پہلی روایت کی طرح یا نون اور تصغیر سے ہے ان سب میں درست بات یہ ہے کہ ان کا نام کنیت کے حرف (ابو) کے بغیر ہے اور یہ نام تصغیر میں ہے جیسا کہ حرف نون کے ناموں کے آخر میں بیان ہوا ہے(۸۲۷۴)۔","",{"fn":"(1) اسد الغابہ (۶۲۱۲)\n(2) اتحاف السادۃ المتقین (۱۹/۵) کنز العمال (۳۵۶۷)"}],[9220,"§۱۰۶۱۰ ۔ ابوالمتوکل\nصحابی ہیں جن کا ایک واقعہ ہے جسے ابو جعفر نحاس اور ان کی پیروی میں مہدوی وغیرہ نے ذکر کیا ہے، قرطبی اپنی تفسیر میں سورہ حشر کی تفسیر میں لکھتے ہیں: مہدوی نے بحوالہ سیدنا ابو ہریرہ رضی اللہ عنہ روایت کی ہے کہ اللہ تعالیٰ کا یہ ارشاد: ﴿ھو اور وہ اپنے مقام میں دوسروں کو ترجیح دیتے ہیں اگرچہ انہیں فاقہ ہی کیوں نہ ہو۔(1)“ انصار میں سے ثابت بن قیس کے بارے میں نازل ہوا۔ انہیں ابو المتوکل کہا جاتا تھا، ثابت ان کے ہاں مہمان ہوئے، ابو المتوکل کے پاس صرف اپنا اور اپنے بچوں کا کھانا تھا، انہوں نے اپنی اہلیہ سے کہا: ”چراغ بجھا کر بچوں کو سلا دو اور جو کچھ ہے مہمان کے سامنے لے آؤ“۔ فرماتے ہیں: نحاس نے بحوالہ سیدنا ابو ہریرہ رضی اللہ عنہ روایت کی ہے ابو المتوکل ثابت بن قیس ایک انصاری کے ہاں کوئی شخص مہمان ہوا ان کے پاس کچھ بھی نہ تھا، پھر اس کا مفہوم ذکر کیا۔ ذیل میں ابن عساکر التعریف للسہیلی میں لکھتے ہیں، بقول بعض: یہ آیت ابو المتوکل ناجی کے بارے میں نازل ہوئی۔ وہ ثابت بن قیس کے ہاں مہمان ہوئے اسے مہدوی نے نقل کیا ہے۔ لکھتے ہیں، بقول بعض: یہ ایثار کرنے والے ثابت بن قیس تھے۔ اسے یحییٰ بن سلام نے نقل کیا ہے۔ یہ سارا خطبہ ہے جس سے رجال کی معرفت کے بارے میں ان لوگوں کی کمزوری کا پتہ چلتا ہے۔ حالانکہ ابو المتوکل ناجی درمیانے درجے کے تابعی ہیں۔ ابو سعید سے ان کی حدیث اسی مفہوم میں منقول ہے جو صحاح ستہ میں درج ہے، انہوں نے اکابر صحابہ رضی اللہ عنہم کا دور نہیں پایا ہے چہ جائیکہ یہ صحابی ہوں۔ قصہ کے راوی نہ مہمان ہیں اور نہ میزبان وہ دونوں (مہمان و میزبان) صحابی ہیں۔ جس کی واضح روایت عبداللہ بن المبارک نے ”البر و الصلۃ“ اور ”کتاب الزہد“ میں نقل کی ہے اور ابن ابی الدنیا نے ان کے طریق سے ”قری الضیف“ نامی کتاب میں نقل کی ہے کہ اسمعیل بن مسلم سے بحوالہ ابو المتوکل ناجی مروی ہے کہ ایک مسلمان نبی صلی اللہ علیہ وسلم کے ہاں فروش ہوا، تین دن تک اس نے کچھ نہیں کھایا، ثابت بن قیس ان کی حالت بھانپ گئے، پھر وہ واقعہ ذکر کیا۔ جس سے معلوم ہوا ابو المتوکل حدیث کے راوی ہیں جسے انہوں نے مرسل نقل کیا ہے اور مہمان کا نام معلوم نہیں اور میزبان ثابت بن قیس تھے، جن کی کنیت ابو محمد ہے نہ کہ ابو المتوکل۔ واللہ المستعان!","",{"fn":"(1) سورۃ الحشر آیت (۹)"}],[9221,"§۱۰۶۱۱ ۔ ابومحرز بن زاہر\nابو عمر نے ان کا مختصر ذکر کیا ہے کہ مجھے ان کی کوئی حدیث معلوم نہیں اور نہ کسی اثر (قول صحابی) کا علم ہے۔ میں کہتا ہوں: یہ لفظی غلطی کا شکار ہے یہ تو ابو محرز آہ زاہر ہیں جو اسلمی ہیں۔ دولابی نے ان کا یہی عنوان قائم کیا ہے: ”ابو محرز آہ زاہر اسلمی“۔ ابن عبدالبر نے اسے غلط ہی لکھ دیا اور ان کے حال کے بارے میں انہیں کچھ معلوم نہ ہو سکا اس واسطے انہوں نے کہا سو کہا۔"],[9222,"§۱۰۶۱۲ ۔ ابومحمد\nنبی صلی اللہ علیہ وسلم سے ایک مرسل حدیث کی روایت کرتے ہیں، ان سے شعیب نے روایت کی ہے۔ ابو احمد الحاکم کا قول ہے: امام بخاری رحمہ اللہ نے کنیتوں میں ان کا ذکر کیا ہے۔"],[9223,"§۱۰۶۱۳ ۔ ابومخارق(1)\nنبی صلی اللہ علیہ وسلم سے اور ان سے اعمش روایت کرتے ہیں، صحابہ رضی اللہ عنہم میں ان کا ذکر آتا ہے جو صحیح نہیں۔ امام بخاری رحمہ اللہ نے ان کا ذکر کرتے ہوئے لکھتے ہیں: ان کی حدیث مرسل ہے۔ میں کہتا ہوں: شاید یہ قابوس کے والد ہیں۔","",{"fn":"(1) اسد الغابہ (۶۲۲۵) تجرید (۲۰۰/۲)"}],[9224,"§۱۰۶۱۴ ۔ ابومرحب(1)\nنا معلوم، ذہبی نے کنیتوں میں ایسا ہی ذکر کیا ہے کہ دو میں سے ایک ہیں۔","",{"fn":"(1) اسد الغابہ (۶۲۲۲) تجرید (۲۰۱/۲)"}],[9225,"§۱۰۶۱۵ ۔ ابومسعود بن عمرو(1)\nبن ثعلبہ، ابو بکر بن علی اور ان کی پیروی میں ابو موسیٰ نے ذیل میں ان کا ذکر کیا ہے۔ اپنے استدراک میں ان کا ذکر کر کے انہیں وہم ہوا ہے یہ تو ابو مسعود بدری ہیں جن کا ذکر پہلے ہو چکا ہے۔ ان کا نام عقبہ بن عمرو ہے۔","",{"fn":"(1) اسد الغابہ (۶۲۴۲) تجرید (۲۰۲/۲)"}],[9226,"§۱۰۶۱۶ ۔ ابومسلم اشعری(1)\nابن مندہ نے ان کا ذکر کیا ہے اور بطریق عثمان بن ابی العاتکہ، جو ایک ضعیف راوی ہے۔ بحوالہ ابو مسلم اشعری، بحوالہ نبی صلی اللہ علیہ وسلم روایت کی ہے کہ ”عنقریب ایک قوم ہو گی جو شراب کا دوسرا نام رکھ کر اسے حلال سمجھے گی“۔ (حدیث)(2) جبکہ اوروں نے یہ روایت عبدالرحمن بن حاتم سے بحوالہ ابو مالک اشعری نقل کی ہے۔ میں کہتا ہوں: یہی درست ہے، عثمان سے اس میں غلطی ہوئی ہے۔ ابو نعیم نے اسے درست بیان کیا ہے جو بطریق معاویہ بن صالح بحوالہ ابو مالک اشعری ہے جس سے ظاہر ہوتا ہے کہ عثمان سے اس کی سند میں بھی خط ہوا ہے۔ اور ان کا یہ ”معاویہ بن حاتم“ غلط ہے۔ حالانکہ یہ معاویہ بن حاتم ہے اور معاویہ ابن حریث ہیں۔ واللہ اعلم!","",{"fn":"(1) اسد الغابہ (۶۲۴۵) تجرید (۲۰۲/۲)\n(2) مسند احمد (۲۴۷/۵) جامع المسانید (۵۱۹/۱۴)"}],[9227,"§۱۰۶۱۷ ۔ ابومصعب اسدی(1)\nابو مکعت میں تذکرہ ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۶۲۴۹) تجرید (۲۰۲/۲)"}],[9228,"§۱۰۶۱۸ ۔ ابومصعب انصاری(1)\nدوسرے ہیں۔ تابعی ہیں جو ایک مرسل حدیث بیان کرتے ہیں۔ ابو نعیم نے انہیں صحابہ رضی اللہ عنہم میں ذکر کر دیا اور لکھ دیا ان کے صحابی ہونے میں اختلاف ہے۔ پھر بطریق عبدالحمید بن جعفر روایت کی ہے کہ میں نے ابو مصعب کو فرماتے سنا: ”اچھے چہروں کے ہاں سے بھلائی طلب کیا کرو“۔","",{"fn":"(1) اسد الغابہ (۶۲۵۰) تجرید (۲۰۲/۲)"}],[9229,"§۱۰۶۱۹ ۔ ابومعن(1)\nاسکندریہ والے۔ تابعی ہیں، مرسل حدیث روایت کرتے ہیں جس کی وجہ سے مستغفری نے صحابہ رضی اللہ عنہم میں ان کا ذکر کر دیا ہے اور ابو موسیٰ بھی ان کے پیرو ہیں۔ وہ روایت بطریق سعید بن الخلا بحوالہ ابو معن صاحب اسکندریہ ہے، فرمایا: رسول اللہ صلی اللہ علیہ وسلم کا ارشاد ہے: ”جہاد فی سبیل اللہ کے ساتھ باقی اعمال کی حیثیت ایسے ہے جیسے جو تھیلے سمندر میں تھوک“۔(2) اسی سند سے یہ روایت ہے: ”ہر نعمت کے بارے میں سوال ہو گا ماسوائے اس نعمت کے جو اللہ کی راہ میں ہو“۔ مستغفری فرماتے ہیں: میں اللہ تعالیٰ کے حضور اس استاد سے براءت کا اظہار کرتا ہوں اور اس شخص کا نام عبد الواحد بن ابی موٹی ہے۔ ابن یونس نے تاریخ مصر میں اس کا ذکر کیا ہے کہ اس نے عمر بن عبدالعزیز کا دور پایا ہے اس سے لیث بن سعد وغیرہ روایت کرتے ہیں۔ حاکم نے ”الکنی“ میں اس کا ذکر کیا ہے کہ عبداللہ بن عمر رضی اللہ عنہما سے روایت کی۔","",{"fn":"(1) اسد الغابہ (۶۲۶۵) تجرید (۲۰۵/۲)\n(2) جامع المسانید (۵۳۶/۱۴)"}],[9230,"§۱۰۶۲۰ ۔ ابومعشر الاشج(1)\nتجرید(2) میں ان کا ذکر ہے کہ یہ صحابی ہیں، جو بہتان ہے۔ میں کہتا ہوں: ابو المدنیا کی حدیث کے کسی طریق میں یہ بات ہے کہ اشج۔","",{"fn":"(1) تجرید (۲۰۴/۲)\n(2) ایضاً"}],[9231,"§۱۰۶۲۱ ۔ ابوملجہ\nفراء بغوی نے ان کا ذکر کیا ہے اور مصاحب میں بحوالہ نبی صلی اللہ علیہ وسلم روایت کی ہے کہ ”اسلام کی ابتداء اجنبیت میں ہوئی اور یہ اجنبی ہو جائے گا“۔ (حدیث) اسے زید بن ملجہ نے اپنے والد سے بحوالہ اپنے دادا روایت کیا ہے، شرح السنت میں لکھتے ہیں: زید بن ملجہ سے بواسطہ ان کے والد بحوالہ ان کے دادا نبی صلی اللہ علیہ وسلم کی حدیث روایت کی جاتی ہے پھر اسے ذکر کیا۔ یہ غلطی سند میں سے سقط (رہ جانے) کی وجہ سے پیدا ہوئی جس کی طرف ان کا دھیان نہیں گیا کیونکہ یہی حدیث ترمذی میں بطریق اسمعیل بن ابی اویس، کثیر بن عبداللہ بن عمرو بن عوف بن زید بن ملجہ کے بواسطہ ان کے والد بحوالہ ان کے دادا مروی ہے۔ لگتا ہے بغوی کے پاس جو ترمذی والا نسخہ ہے اس میں یوں ہے: کثیر بن عبداللہ بن عمرو بن عوف عن زید بن ملجہ عن ابیہ عن جدہ جو لفظی غلطی ہے، حالانکہ وہ ابن زید ہیں۔ زید عوف کے والد ہیں اور عوف عمرو کے اور عمرو کثیر کے دادا ہیں۔ اس حدیث کے صحابی عمرو بن عوف ہیں جو صحابہ میں مشہور ہیں۔ اور کثیر بن عبداللہ بن عمرو بن عوف کے حالات سنن ابی داؤد اور جامع الترمذی وغیرہ میں ہیں۔ مذکورہ ملجہ کو یہ لفظ فقیر سے بھی لکھا جاتا ہے۔ وہ ابن عمرو بن بکر بن اشک بن عثمان بن عمرو بن اوس بن طاہر ہیں۔ امام بخاری رحمہ اللہ نے تاریخ میں اسماعیل بن ابی اویس سے اسی سند کے ذریعہ ایک حدیث نقل کی ہے اور اس میں وضاحت کی ہے کہ صحابی وہ عمرو بن عوف ہیں، فرمایا: کثیر بن عبداللہ بن عمرو بن عوف عن ابیہ ابن عمرو جدہ عمرو بن عوف، ہم نبی صلی اللہ علیہ وسلم کے پاس تھے پھر ایک حدیث ذکر کی۔"],[9232,"§۱۰۶۲۲ ۔ ابوالمنذر\nپہلے تذکرہ ہوا ہے۔"],[9233,"§۱۰۶۲۳ ۔ ابوالمهلب(1)\nمطین وغیرہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے جو تحریف کا نتیجہ ہے، حالانکہ یہ ابو المطلب ہیں، چنانچہ ابو نعیم ان کے طریق سے بحوالہ عبداللہ بن حطب سیدنا ابو بکر و عمر رضی اللہ عنہما کے بارے نبی صلی اللہ علیہ وسلم کا یہ قول نقل کیا ہے کہ یہ دونوں آنکھ اور کان کی حیثیت رکھتے ہیں۔ فرماتے ہیں: میری کتاب میں ایسا ہی لکھا ہے جبکہ درست عبدالعزیز بن المطلب ہے شاید ان کی کنیت ابو المهلب ہو جو تحریف لفظی غلطی ہے۔ دوسری بات قابل اعتماد ہے، یہی حدیث عبداللہ بن حطب کے حالات میں بیان ہوئی ہے۔ وہاں میں نے اس کی سند عبداللہ کے صحابی ہونے اور عبدالعزیز کے نسب میں اختلاف کا ذکر کیا ہے اور یہ پہلے بیان ہو چکا ہے۔ یہ المطلب بن عبداللہ بن المطلب بن حطب ہیں اور صحابی ان کے جد امجد ہیں۔","",{"fn":"(1) اسد الغابہ (۶۸۹۴) تجرید (۲۰۷/۲)"}],[9234,"§۱۰۶۲۴ ۔ ابومَیسّرہ(1)\nمولا عباس بن عبدالمطلب۔ مستغفری نے صحابہ رضی اللہ عنہم میں اور ابو موسیٰ نے ان کے اتباع میں ان کا ذکر کیا ہے اور بطریق محمد بن احمد بن سعید ابو الراز طوی المعروف بابی کسا بحوالہ ابو میسرہ مولا عباس بن عبدالمطلب روایت کی ہے، فرمایا: میں نے نبی کریم صلی اللہ علیہ وسلم کے ہاں رات گزاری آپ نے فرمایا: عباس دیکھو! آسمان میں کوئی چیز نظر آ رہی ہے؟ میں نے عرض کی: ہاں جی! مجھے کہکشاں نظر آ رہی ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”تمہاری اولاد میں ان کی مقدار اس امت کے حاکم ہوں گے“۔ میں کہتا ہوں: یہ حدیث عبید بن ابی قرہ کے حوالے سے مشہور ہے۔ لیث سے اس کی روایت میں منفرد ہے، سند میں سے عباس بن عبدالمطلب کا نام رہ گیا اور بظاہر یوں ہوا کہ صحابی ابو میسرہ ہیں حالانکہ ایسا نہیں یہی روایت امام احمد رحمہ اللہ نے اپنی مسند میں عبید بن ابی قرہ سے نقل کی ہے۔ اسی طرح ابو حاتم رازی نے احمد بن محمد بن یحییٰ بن سعید قطان سے جو ابو اسحاق کے شیخ ہیں۔ بحوالہ عبید روایت کی ہے۔ امام بخاری رحمہ اللہ نے الکنی میں عبدالحمید انحسی سے اور حاکم نے بطریق ابراہیم بن سعید جوهری اور مستدرک میں بطریق احمد بن ابراہیم دورقی اور ابن ابی داؤد نے بطریق حجاج شاعر سب نے عبید سے نقل کی ہے۔ ابن ابی حاتم بحوالہ اپنے والد روایت کرتے ہیں کہ لیث یہ حدیث صرف عبید بن قرہ سے نقل کی ہے اور امام احمد رحمہ اللہ اس میں مغل کیا کرتے تھے۔ فرماتے ہیں: میرے والد اس حدیث کو اچھا سمجھتے تھے اور اس پر خوش ہوتے تھے کہ یہی قطان سے مل گئی ہے۔ ابن ابی داؤد کا قول ہے: احمد بن ابی صالح نے یہ حدیث میرے والد سے بواسطہ حجاج سنی ہے، ان تمام طرق میں اتنا اتفاق ہے کہ یہ اس سند بواسطہ ابو میسرہ بحوالہ عباس بن عبدالمطلب ہے جس سے ظاہر ہوتا ہے کہ درست اسے ثابت رکھنا ہے میں نے لسان المیزان میں عبید بن ابی قرہ کا حال ذکر کیا ہے۔ امام احمد بن حنبل رحمہ اللہ نے علل میں ایک حدیث بطریق زکریا بن ابی زائدہ، ابو اسحاق سے بواسطہ ابو میسرہ نقل کی ہے جس سے کسی نے سمجھ لیا ہے کہ یہی ”صاحب ترجمہ“ (جن کے حالات بیان ہو رہے) ہیں۔ حالانکہ ایسا نہیں وہ تو عمرو بن شرحبیل ہیں۔ جن کا تذکرہ قسم ثالث میں ہوا ہے یہ روایت بھی مرسل ہے۔ واللہ اعلم!","",{"fn":"(1) اسد الغابہ (۶۲۹۶) تجرید (۲۰۷/۲)"}],[9235,"§۱۰۶۲۵ ۔ ابونافع\nنام کسان بن عبداللہ بن طارق ہے۔"],[9236,"§۱۰۶۲۶ ۔ ابونافع\nان کا نام طارق بن علقمہ ہے، دونوں کا تذکرہ ہو چکا ہے۔"],[9237,"§۱۰۶۲۷ ۔ ابونائلہ انصاری(1)\nنام سلکان بن سلامہ بن وقش بن زغبہ بن زعوراء، بن عبدالاشہل انصاری اوسی اشہلی ہے۔ سلمہ ابن سلامہ بن وقش کے بھائی ہیں۔ بقول بعض: ان کا نام سعد ہے کسی کا قول ہے سعد ان کے بھائی ہیں۔ ایک قول ہے: سلکان ان کا لقب ہے، نام سعد ہے، کنیت سے مشہور ہیں۔ صحیح میں کعب بن اشرف کے قتل کے واقعہ میں ان کا ذکر ثابت ہے۔ غزوہ اُحد وغیرہ میں شریک ہوئے، شام اور معروف تیر اندازوں میں شمار ہوتے تھے، سراج اپنی تاریخ میں بطریق عبدالمجید اپنے والد سے بحوالہ اپنے دادا روایت کرتے ہیں کہ کعب بن اشرف یہودی شہر کپتا تھا اور لوگوں کو نبی صلی اللہ علیہ وسلم کی مدد سے روکتا تھا اور زہیرہ لوگوں میں سے عرب کے قبائل غطفان میں پھیلاتا تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”مجھے ابن اشرف کے شر سے کون بچائے گا“ تو محمد بن مسلمہ حارثی پکار اٹھے یا رسول اللہ! کیا آپ پسند کریں گے کہ میں اسے قتل کر دوں؟ آپ خاموش رہے۔ پھر محمد بن سعد بن عبادہ نے گفتگو کی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ کی برکت سے روانہ ہو جاؤ اور اپنے ساتھ اپنے چچا زاد بھائی حارث بن اوس بن معاذ، ابو عبس بن جبر، عباد بن بشر ابو نائلہ بن وقش کو بھی لے جانا“۔ فرماتے ہیں: میں ان کے پاس پہنچا انہیں بتایا تو سوائے سلکان بن وقش کے سب تیار ہو گئے وہ کہنے لگا: میں جب تک رسول اللہ صلی اللہ علیہ وسلم سے مشورہ نہ کر لوں ایسا کرنا نہیں چاہتا۔ آپ صلی اللہ علیہ وسلم سے اس کا ذکر کیا، آپ نے فرمایا: ”اپنے ساتھیوں کے ساتھ روانہ ہو جاؤ“۔ فرماتے ہیں: ہم وہاں سے نکلے، پھر اس کے قتل کا واقعہ نقل کیا جس کے متعلق عباد بن بشر نے یہ اشعار کہے تھے: ظ ”میں نے اسے پکارا تو اس نے میری آواز کی طرف توجہ نہ دی اور بالا خانے سے جھانک کر دیکھا، میں نے پھر آواز دی تو اس نے کہا: کون آواز دے رہا ہے؟ میں نے کہا: تیرا بھائی عباد بن بشر ہوں۔ یہ ہماری زریں اپنے پاس رہن رکھ لو۔ جس کی ادائیگی میں مہینہ یا ڈیڑھ مہینہ لگے گا تو وہ ہماری طرف دوڑتا ہوا آیا کہنے لگا: شاید تم لوگ کسی کام سے آئے ہو؟ ابو عبس بن جبر نے اپنی تلوار سونت کر اس پر وار کیا اور اسے دو لخت کر دیا۔ ہم پانچ تھے، اللہ تعالیٰ ہمارے ساتھ چھٹے تھے پھر ہم بھر پور نعمت اور طلبہ سے واپس ہوئے۔ معجزہ جماعت اس کا سر لے کر آئی وہ بچے اور تکیر کا رکانی ہیں۔“ یہ روایت حاکم نے بواسطہ سراج بحوالہ محمد بن عبادہ، محمد بن طلحہ سے بحوالہ عبداللہ بن قتل کی ہے۔ فرماتے ہیں: اسے ابراہیم بن المندر نے محمد بن طلحہ سے نقل کیا تو فرمایا: عن عبدالمجید عن محمد بن ابی عبس عن ابیہ عن جدہ، فرماتے ہیں: پہلی سند صحیح ہے۔","",{"fn":"(1) اسد الغابہ (۶۲۹۸) استیعاب (۳۲۴۱) تجرید (۲۰۷/۲)"}],[9238,"§۱۰۶۲۸ ۔ ابونبقہ بن عبدالمطلب(1)\nابن عبد مناف المطلمی۔ فتح مکہ کے مسلمانوں میں سے ہیں۔ بقول ابو عمر: ”کسی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے جبکہ میرے نزدیک یہ نامعلوم ہیں“۔ طبری نے ان کا ذکر کیا ہے، ابن اسحاق کا بیان ہے کہ نبی صلی اللہ علیہ وسلم نے انہیں خیبر سے پچاس وسق کھجوریں کھانے کے لیے دی تھیں۔ یہی بات مستغفری نے ابن اسحاق تک کی سند سے نقل کی ہے ابو موسیٰ نے ذیل میں ان کا اتباع کیا ہے یہی بات نسب قریش کے سب سے بڑے عالم زبیر بن بکار نے کی ہے، وہ فرماتے ہیں: علقمہ بن المطلب کے ہاں ابو نبقہ پیدا ہوئے ان کا نام عبداللہ تھا والدہ کا نام ام عمرو فرزا عتیقہ تھا۔ ان کے بیٹے علامہ و ہندم دونوں یمامہ میں شہید ہوئے، دونوں کی نسل نہ رہی۔ ابو الولید فرضی کا قول ہے: محمد بن علامہ بن حسین بن ابی وقٹی کی امی کی اولاد سے ہیں۔ ابن الاثیر فرماتے ہیں:(2) اس سب سے معلوم ہوا کہ یہ اپنی ذات اور نسب میں مجہول و نامعلوم نہیں (جیسا کہ ابو عمر نے آغاز میں کہا تھا)۔","",{"fn":"(1) اسد الغابہ (۶۲۹۹) استیعاب (۳۲۴۲) تجرید (۲۰۷/۲)\n(2) اسد الغابہ (۱۱۴/۵)"}],[9239,"§۱۰۶۲۹ ۔ ابوالنجم(1) (بے نسبت)\nابو نعیم نے ان کا ذکر کیا ہے کہ حسین بن سفیان نے ان کا ذکر کیا ہے، ان کی حدیث ابن ابیہ نے کعب بن طلقہ سے انہوں نے ابو نجم کو فرماتے سنا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”بنی امیہ میں چوٹی ناک والا ایک شخص ہو گا“۔(2) ابو موسیٰ نے اسی کے ساتھ اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۳۰۰) تجرید (۲۰۸/۲)\n(2) جامع المسانید (۲۹۹/۱۴) اسد الغابہ (۱۱۵/۵)"}],[9240,"§۱۰۶۳۰ ۔ ابونجیج\nعمرو بن عبیدہ اسلمی، ناموں میں ذکر ہوا ہے۔"],[9241,"§۱۰۶۳۱ ۔ ابونجیج عبسی\nابن مندہ نے ان کا تذکرہ کیا ہے۔ میں کہتا ہوں: امام بخاری رحمہ اللہ نے الکنی المجرود میں ان کا ذکر کیا ہے اور انہیں عمرو بن عبسہ سے الگ ذکر کیا ہے، لیکن کہا: عبسی، فرماتے ہیں ربیعہ بن لقیط بواسطہ ایک شخص کے بحوالہ ان کے نبی صلی اللہ علیہ وسلم سے روایت کی ہے اسے الحاکم نے نقل کیا ہے اور اس بات کی طرف اشارہ کیا ہے کہ یہ عمرو بن عبسہ ہیں۔ قسم رابع میں میں اس کی وضاحت کروں گا۔"],[9242,"§۱۰۶۳۲ ۔ ابونجیج السلمی(1)\nابن جریج ان کی حدیث نقل کرتے ہیں، یہ ابو نعیم کا قول ہے پھر بطریق عبدالرزاق ابن جریج سے کہ مجھے ابو المخلص نے بیان کیا کہ ابو نجیج نے انہیں بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”مالدار ہوتے ہوئے جس نے نکاح نہ کیا میرا اس سے کوئی تعلق نہیں“۔(2) دوسری روایت ہے: ”وہ شخص انتہائی لاچار و مسکین ہے جس کے گھر بیوی نہ ہو“۔(3) ابن الاثیر(4) فرماتے ہیں: یہ عمرو بن عبسہ ہیں کیونکہ وہ سلمی ہیں اور نکاح کے بارے میں ان کی حدیث مشہور ہے۔ ذہبی(5) لکھتے ہیں: نہیں بلکہ یہ عرباض بن ساریہ ہیں۔ میں کہتا ہوں: اس پر ابو احمد الحاکم نے اعتماد کیا ہے اور بغوی نے یقین سے لکھا ہے یہ سلیمی نہیں، فرماتے ہیں: ان کے صحابی ہونے میں شک ہے۔","",{"fn":"(1) اسد الغابہ (۶۳۰۱) تجرید (۲۰۸/۲)\n(2) المصنف لعبدالرزاق (۱۰۳۷۶) المعجم الکبیر (۹۲۰/۲۲) معجم الزوائد (۲۵۲/۴) جامع المسانید (۷۰۰/۱۴) الکنی للدولابی (۵۸/۱)\n(3) جامع المسانید (۷۰۱/۱۴) اسد الغابہ (۱۱۲/۵)\n(4) اسد الغابہ (۱۱۵/۵)\n(5) تجرید (۱۷۱)"}],[9243,"§۱۰۶۳۳ ۔ ابونجیج\nالعرباض بن ساریہ سلمی۔ امام بخاری رحمہ اللہ نے شامی سند بحوالہ العرباض بن ساریہ روایت کی ہے، فرمایا: ”اگر یہ خدشہ نہ ہوتا کہ لوگ ابو نجیج کے کام سے علیحدہ ہو جائیں گے تو میں اپنا مال اس کے راستوں میں پہنچا دیتا“۔"],[9244,"§۱۰۶۳۴ ۔ ابونجیج\nعبداللہ کے والد، نام بیار ہے۔"],[9245,"§۱۰۶۳۵ ۔ ابونجید (تصغیر) عمران بن حصین\nدونوں کا ذکر ہوا ہے۔"],[9246,"§۱۰۶۳۶ ۔ ابوبجیلہ(1)\nدار قطنی وغیرہ کے ہاں ایسا ہی لکھا ہے، میں ابو احمد کے الکنی والے معتبر نسخے میں بجیلہ لکھا دیکھا ہے، عبدالغنی نے تصغیر اور حاء سے لکھا ہے حاء پر ابراہیم حربی نے اعتماد کیا ہے یہ اضافہ کیا ہے کہ یہ بجیلہ کے نیک آدمی تھے، اسے دار قطنی نے نقل کیا ہے اور علی بن مدینی سے مروی ہے کہ سفیان بن عیینہ کا قول ہے کہ ابو نخیلہ صحابی ہیں، یہ بجلی ہیں۔ دار قطنی وغیرہ نے ان کا ذکر کیا ہے۔ ابن المدینی، بخاری ابو احمد الحاکم کا قول ہے: صحابی ہیں، ان کی حدیث ثوری، منصور سے بواسطہ ابو وائل بحوالہ ابو نخیلہ جو اصحاب نبی صلی اللہ علیہ وسلم میں سے ایک ہیں روایت کرتے ہیں کہ ان کے تیر لگ گیا کسی نے کہا نکلوا لیں، انہوں نے فرمایا: اے اللہ! درد کم کر دے اور اجر کم نہ فرما، کسی نے کہا: اللہ تعالیٰ سے دعا کریں، انہوں نے کہا: اے اللہ! مجھے مقرّبین میں شامل فرما اور میری والدہ کو حور عین بنا دے۔(2) ابن مندہ کی کتاب میں ہمیں یہ روایت عالی سند سے پہنچی ہے لیکن انہوں نے اس کے آغاز میں فرمایا: وہ جہاد میں نکلے انہیں پتھر لگ گیا تو انہوں نے دعا کی: ”اے اللہ! درد کم فرما“۔ باقی الفاظ اسی طرح ہیں۔ ابو عمر بحوالہ ابن المدینی لکھتے ہیں: انہیں ابو نخیلہ بھی کہا جاتا ہے، جبکہ مشہور ابو بجیلہ ہے، انہیں جریر بجلی سے روایت حاصل ہے۔ میں کہتا ہوں: یہ روایت الادب المفرد للبخاری اور نسائی وغیرہ میں ہے۔ ابو حاتم رازی لکھتے ہیں: یہ صحابی نہیں ہیں۔","",{"fn":"(1) اسد الغابہ (۶۳۰۴)\n(2) المعجم الکبیر (۹۴۴/۲۲) مجمع الزوائد (۳۹۸/۹) جامع المسانید (۷۰۳/۱۴)"}],[9247,"§۱۰۶۳۷ ۔ ابونخیلہ اللہبی(1) (تصغیر)\nابن مندہ نے ان کا ذکر کیا ہے اور بطریق سلیمان بن داؤد کی از اہل تبالہ روایت کی ہے کہ عبداللہ بن عقیل بن یزید بن راشد بحوالہ اپنے والد روایت کرتے ہیں۔ ہم لوگ مسلم بن حذیفہ عامری کے پاس گئے، انہوں نے فرمایا کہ ابو رہیمہ سمعی اور ابو نخیلہ لہبی نے فرمایا: ہم عقیق کا ٹکڑا لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، آپ نے ہمارے لیے تحریر لکھوائی۔ اس میں ہے جسے کوئی چیز ملے وہ اس کی کانوں میں خمس (پانچواں حصہ) ہے اور ہر چالیس دینار میں ایک دینار زکوۃ ہے۔ سلیمان فرماتے ہیں: یعنی جسے معادن (کانوں) میں سے کچھ ملے اس میں زکوۃ نہیں یہاں تک کہ اس کی مقدار چالیس دینار تک پہنچ جائے۔(2) اس کے راویوں میں غیر معروف رجال ہیں۔ البتہ یہ بروایت ابو حاتم رازی عن سلیمان ہے لفظ اللھی میں نے صریفینی کی کتاب میں لام کے زیر اور ھاء کے سکون سے لکھا دیکھا ہے۔","",{"fn":"(1) اسد الغابہ (۶۳۰۵) تجرید (۲۰۸/۲)\n(2) جامع المسانید (۷۰۳/۱۴)"}],[9248,"§۱۰۶۳۸ ۔ ابونضرہ(1)\nبقول ابو عمر: فتح خیبر کے شرکاء میں سے ایک۔ ان کا وہاں ذکر آتا ہے۔ اسی سے میں انہیں جانتا ہوں۔ ابن الاثیر(2) فرماتے ہیں: جن لوگوں کو رسول اللہ صلی اللہ علیہ وسلم نے خیبر کی جاگیر دی ان میں ابن ہشام(3) نے ابو نضرہ کو بھی ذکر کیا ہے۔ میں نہیں جانتا آیا وہ یہی ہیں یا نہیں؟ ابن فتحون اوہام الاستیعاب میں لکھتے ہیں: میں انہیں وہی سمجھتا ہوں۔","",{"fn":"(1) اسد الغابہ (۷۳۰۶) تجرید (۲۰۸/۲)\n(2) اسد الغابہ (۱۱۶/۵)\n(3) السیرۃ النبویۃ (۲۷۲/۳)"}],[9249,"§۱۰۶۳۹ ۔ ابونضرہ\nسابقہ شخصیت کے حالات میں ذکر ہوا ہے۔"],[9250,"§۱۰۶۴۰ ۔ ابونضیرہ\nبقول بعض: یہ عبداللہ بن عمرو بن عاص کی کنیت ہے جسے حاکم نے نقل کیا ہے اور ابو عبدالرحمن الحمبلی تک صحیح سند کے حوالہ سے لکھا ہے، فرماتے ہیں: میں نے عبداللہ بن عمرو سے پوچھا، بقول بعض: ان سے کہا: ابو نضیر۔"],[9251,"§۱۰۶۴۱ ۔ ابونضیر(1)\nابن التیہان انصاری اوسی، ابو الہیثم کے بھائی۔ ابو عمر نے بحوالہ طبری انہیں شرکاء اُحد میں شریک کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۳۰۸) تجرید (۲۰۸/۲)"}],[9252,"§۱۰۶۴۲ ۔ ابونعمان\nبشیر بن سعد انصاری، ناموں میں ذکر ہوا ہے۔"],[9253,"§۱۰۶۴۳ ۔ ابوالنعمان الازدی(1)\nطبرانی کے دادا یہی ایوب بن نعمان کے دادا ہیں۔ بقول بعض: ایوب بن العلاء، حرف عین میں ان کا ذکر ہوا، جن لوگوں کی کنیت ابو العلاء ہے۔ ابو موسیٰ نے بحوالہ طبرانی ان کا ذکر کیا ہے میں نے ابو اسحاق میر فینی کے قلم سے بحوالہ ابو نعمان ازدی یہ روایت لکھی دیکھی کہ ایک شخص کی خاتون کو نکاح کا پیام بھیجا۔ نبی صلی اللہ علیہ وسلم نے فرمایا: اس کا مہر دینا، عرض کی میرے پاس تو کچھ نہیں، آپ نے فرمایا: کیا تم قرآن کی کوئی سورۃ اچھے انداز سے نہیں پڑھ سکتے؟ وہ سورۃ ہی اسے مہر دے دو جو تمہارے بعد کسی کے لیے مہر نہیں ہوگی۔ پھر میں نے ابن السکن کی کتاب میں دیکھا فرمایا: یہ اضافہ صرف اسی روایت میں محفوظ ہے۔","",{"fn":"(1) اسد الغابہ (۶۳۰۹) تجرید (۲۰۸/۲)"}],[9254,"§۱۰۶۴۴ ۔ ابوالنعمان(1)\nیہ اور ہیں، بے نسبت۔ مطین اور ابن ابی شیبہ نے انہیں صحابہ رضی اللہ عنہم میں ذکر کیا ہے اور ابو نعیم نے دونوں کے حوالہ سے اور ابو موسیٰ نے ان کے اتباع میں روایت کی ہے مسند یحییٰ بن عبدالحمید میں ان کی حدیث ہے کہ نبی صلی اللہ علیہ وسلم نے نفاس والی ایک عورت کا جنازہ پڑھایا جس کا بیٹا زنا سے تھا۔ ابن کلبی نے ان کا نسب انصاری بتایا ہے کہ انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ہے کہ آپ نے نفاس میں مرنے والی ایک خاتون کا جنازہ پڑھایا جس کے ساتھ اس کا بیٹا بھی تھا، فرماتے ہیں: اسے جابر بن یزید جعفی کے علاوہ کسی نے نہیں روایت کیا ہے اور یہ حدیث صحیح ثابت نہیں۔(2)","",{"fn":"(1) اسد الغابہ (۶۳۱۰) تجرید (۲۰۹/۲)\n(2) جامع المسانید (۷۰۴/۱۴) اسد الغابہ (۱۱۶/۵)"}],[9255,"§۱۰۶۴۵ ۔ ابوالنعمان بن ابی النعمان\nعبدالرحمن بن النعمان انصاری۔ بغوی نے کنیتوں میں ان کا ذکر کیا ہے اور ان کی وہ حدیث ذکر کی ہے جو معبد بن ھوزہ کے حالات میں بیان ہوگی اور اس سے خبر دار نہیں کیا کہ ان کا نام معبد ہے۔"],[9256,"§۱۰۶۴۶ ۔ ابونعیم\nمحمد بن الربیع انصاری۔ حاکم نے ان کا تذکرہ کیا ہے، پہلے ذکر ہوا ہے۔"],[9257,"§۱۰۶۴۷ ۔ ابونمر الکنانی(1)\nشریک بن عبداللہ بن ابی نمر کے دادا۔ ابن سعد نے مسلمانان فتح مکہ میں ان کا ذکر کیا ہے۔ ذہبی(2) نے اپنے استدراک میں ان کا ذکر کیا ہے۔ میں کہتا ہوں: ابن السکن نے انہیں صحابہ رضی اللہ عنہم میں ذکر کیا ہے۔ ابن عبدالبر اور ابن فتحون نے انہیں قلم انداز کیا ہے باوجود یکہ وہ دونوں ابن السکن کی کتاب سے بہت مدد لیتے ہیں۔ ابن السکن نے بطریق محمد بن طلحہ تیمی، بحوالہ ابو عمر روایت کی ہے، فرمایا: رسول اللہ صلی اللہ علیہ وسلم کسی غزوہ میں روانہ ہوئے۔ آپ کے ساتھ سیدہ عائشہ رضی اللہ عنہا تھیں عقیق سے گزر ہوا تو آپ نے فرمایا: ”عائشہ! یہ فرودگاہ تھی، اگر یہاں حشرات الارض کی کثرت نہ ہوتی“۔ ابن السکن فرماتے ہیں اس حدیث کے راوی عبدالحکم، شریک بن ابی نمر کے بھتیجے ہیں۔ میں نے عمر بن شبہ کی کتاب اخبار مدینہ میں پڑھا ہے کہ ابو نمر بن عریف کا تعلق بنی حارث بن عبد مناة بن کنانہ سے تھا وہ مدینہ آئے تو بنی لیث بن بکر کے ہاں ٹھہرے اور بنی اخرم بن لیث میں اپنی حویلی بنائی جو دار ابی نمر“ سے مشہور ہو گئی۔","",{"fn":"(1) تجرید (۲۰۸/۲)\n(2) تجرید (۱۷۲)"}],[9258,"§۱۰۶۴۸ ۔ ابونملہ انصاری(1)\nنام عمار بن معاذ بن زرارہ بن عمرو بن غنم۔۔۔۔ انصاری ظفری ہے۔ بدر میں اپنے والد کے ساتھ شریک ہوئے۔ اور بعد کے معرکوں میں شرکت کی۔ عبدالملک بن مروان کی خلافت میں فوت ہوئے۔ واقعہ حرہ کے روز ان کے دو بیٹے شہید ہوئے۔ عبداللہ اور محمد، ابن شہاب سے ان کی حدیث اہل کتاب کے بارے میں بروایت نملہ بن ابی نملہ بحوالہ ان کے والد مروی ہے۔ ابن عبدالبر نے ان کا اتنا ہی ذکر کیا ہے اور ابو علی بن السکن نے اس سے زیادہ بیان کرنے میں سبقت کی اور ابو احمد نے یہ اضافہ نقل کیا ہے۔ ان کا ابو زر کنیت کا ایک بھائی تھا دونوں کی والدہ ام زرارہ بنت حارث ہیں۔ ابو بشر دولابی کا قول ہے: وہ عمارہ بن معاذ ہیں۔ جبکہ ابن البرقی لکھتی ہیں: وہ معاذ بن زرارہ ہیں، ابن مندہ فرماتے ہیں: ابو نملہ انصاری صحابی ہیں: ابو نملہ انصاری صحابی ہیں پھر ان کی حدیث عالی سند سے بروایت معمر و یونس، زہری سے بواسطہ ابو نملہ بحوالہ ان کے والد نقل کی ہے کہ وہ لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھے تھے کہ ایک جنازہ گزرا، ایک یہودی آپ صلی اللہ علیہ وسلم سے کہنے لگا: محمد (صلی اللہ علیہ وسلم)! کیا یہ جنازہ بولتا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: مجھے معلوم نہیں۔ وہ یہودی کہنے لگا: بولتا ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: ”یہودی تم سے جو بات بیان کریں نہ اس کی تصدیق کرو اور نہ تکذیب کرو“۔ یہی روایت ابن السکن اور حارث بن ابی اسامہ نے بطریق یونس نقل کی ہے۔ جس میں یہ اضافہ ہے: تم لوگ یوں کہو! آمنا باللہ و کتبہ و رسلہ۔ اگر وہ سچی بات ہوئی تو تم نے اس کی تکذیب نہیں کی اور اگر جھوٹ ہوا تو تم نے اس کی تصدیق نہیں کی۔ ان کی حدیث ابو داؤد نے روایت کی ہے۔ بغوی لکھتے ہیں: ابو نملہ یہ مدینہ کے باسی تھے۔ پھر ان کی حدیث نقل کی، مجھے نملہ بن ابی نملہ کی بحوالہ ان کے والد اور حدیث مل گئی ہے جسے ابو سعد اور ابراہیم نے ”دلائل النبوۃ“ میں بطریق محمد بن صالح نقل کیا ہے۔ فرمایا: بنی قریظہ کے یہودی رسول اللہ صلی اللہ علیہ وسلم کا ذکر اپنی کتابوں میں پڑھتے اور بچوں کو آپ صلی اللہ علیہ وسلم کی نشانی سکھاتے۔ آپ صلی اللہ علیہ وسلم کا نام اور ہماری طرف آپ کی ہجرت کا بتاتے لیکن جب آپ صلی اللہ علیہ وسلم مبعوث ہوئے تو آپ سے حسد کر کے باغی ہو گئے، کہنے لگے: یہ وہ نہیں ہیں۔","",{"fn":"(1) اسد الغابہ (۶۳۱۱) تجرید (۲۰۹/۲)"}],[9259,"§۱۰۶۴۹ ۔ ابونملہ (دوسرے)\nدولابی نے ان کا ذکر کیا ہے کہ یہ انصاری کے علاوہ اور صاحب ہیں۔"],[9260,"§۱۰۶۵۰ ۔ ابونہیک انصاری اشہلی(1)\nابو عمر نے ان کا ذکر کیا ہے کہ مجھے ان کا کوئی حال اور روایت معلوم نہیں۔ اتنی بات ہے کہ سیدنا ابو بکر الصدیق نے انہیں سلمہ بن سلامہ بن وقش کے ساتھ خالد بن ولید کی طرف یہ پیام دے کر بھیجا تھا کہ بنی حنیفہ میں سے جس کی داڑھی مونچھ آ گئی ہے اسے قتل کر دو جب یہ دونوں پہنچے تو انہوں نے مجاہد بن مرارہ(2) سے صلح کر لی تھی۔","",{"fn":"(1) اسد الغابہ (۶۳۱۲) استیعاب (۳۲۴۸) تجرید (۲۰۹/۲)\n(2) اسد الغابہ (۱۱۷/۵)"}],[9261,"§۱۰۶۵۱ ۔ ابونیرز\nذہبی نے اپنے استدراک میں ان کا ذکر کیا ہے کہ بقول بعض: یہ نجاشی کے بیٹے ہیں آ کر اسلام قبول کیا اور نبی صلی اللہ علیہ وسلم کی مہمات میں آپ کے ساتھ تھے۔ میں کہتا ہوں: میں نے مبرد کی الکامل میں ان کا واقعہ پڑھا ہے کہ ابو نیزر کسی عجمی بادشاہ کے بیٹے تھے، بچپن میں اسلام کی محبت دل میں جاگزیں ہو گئی۔ نبی صلی اللہ علیہ وسلم کے پاس آ کر مسلمان ہو گئے مہمات میں آپ کے ساتھ رہتے۔ پھر سیدہ فاطمہ رضی اللہ عنہا کے ہاں پھر ان کے بیٹے کے ساتھ رہتے تھے۔ بقیع میں سیدنا علی رضی اللہ عنہ کی جو دو جائیدادیں تھیں ان کے نگران تھے۔ ان میں سے ایک کا نام بغیغہ اور دوسری کا عین ابی نیزر تھا، پھر ذکر کیا کہ سیدنا علی رضی اللہ عنہ ان کے ہاں آئے تو انہیں کدو کا سالن کھلایا جو انہوں نے پگھلی ہوئی چربی کے ساتھ ان کے لیے تیار کیا تھا۔ آپ نے وہ سالن کھایا اور پانی پیا۔ اس کے بعد ان کا واقعہ ذکر کیا۔ یہ کہ آپ نے دونوں زمینوں کو حبس کرنے کا حکم لکھا پھر ان کے شرائط ذکر کیں۔ ان میں سے ایک شرط یہ تھی آپ نے وہ جگہیں مدینہ کے فقراء اور مسافروں کے لیے وقف کر دی ہیں۔ البتہ اگر حسنین کو ان کی ضرورت پڑے تو ان دونوں کو اجازت ہے۔ اس واقعہ کے آخر میں ہے کہ سیدنا حسین رضی اللہ عنہ کو اپنے قرض کی ادائیگی کے لیے اس کی ضرورت پڑ گئی امیر معاویہ کو معلوم ہوا تو انہوں نے انہیں عین ابی نیزر کے عوض ایک لاکھ دینا چاہے تو آپ نے اسے بیچنے سے انکار کر دیا، اور اس کا وقف رہنا بدستور جاری رکھا۔"],[9262,"§۱۰۶۵۲ ۔ ابونجیج مکی\nعبداللہ بن ابی شیخ کے والد، ان کا نام یسار ہے، پہلے تذکرہ ہو چکا ہے۔"],[9263,"§۱۰۶۵۳ ۔ ابوالنعمان\nحجر بن عمرو۔"],[9264,"§۱۰۶۵۴ ۔ ابوالنعمان (بے نسبت)\nدور نبوی پایا ہے، ثور، بحوالہ خالد بن معدان روایت کرتے ہیں کہ ابو نعمان نے ان سے بیان کیا کہ میں نے خلافت فاروقی میں حج کیا پھر ایک واقعہ ذکر کیا۔ امام بخاری رحمہ اللہ اور ان کے اتباع میں حاکم نے ان کا ذکر کیا ہے۔"],[9265,"§۱۰۶۵۵ ۔ ابونخیلہ العکلی\nدور نبوی پایا ہے، الآمدی نے شعراء میں ان کا ذکر کیا ہے اور ان کے وہ اشعار نقل کیے ہیں جن میں حجاج مدعیہ نبوت کی ہجو برائی ہے۔ پھر مسیلمہ کذاب نے اسے دھوکے سے بلا لیا اور اس نے اپنا سب کچھ اس کے حوالے کر دیا تھا۔"],[9266,"§۱۰۶۵۶ ۔ ابونمر بن عویف\nابو عمر جو شریک بن عبداللہ بن ابی نمر کے دادا ہیں ان کے حالات میں ذکر ہوا ہے۔"],[9267,"§۱۰۶۵۷ ۔ ابونجیج العبسی(1)\nابو عمر نے ان کا ذکر کیا ہے کہ نکاح کے بارے میں ان کی ایک حدیث ہے۔ امام بخاری رحمہ اللہ ”الکنی المجرودۃ“ میں ان کا ذکر کیا ہے، یہ محمد بن ثمین کے نزدیک عمرو بن عبسہ ہیں۔ میں کہتا ہوں: انہوں نے حاکم کی بات سے ان کا مختصر ذکر کیا ہے جس میں ”ان کی ایک حدیث“ کا ذکر نہیں۔ ان کے الفاظ یہ ہیں: ابو نجیج عبسی نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں، ربیعہ بن لقیط بواسطہ ایک شخص ابو نجیج کے حوالہ سے روایت کرتے ہیں۔ پھر امام بخاری رحمہ اللہ کی سند سے لکھتے ہیں کہ انہوں نے کنیتوں میں ایسا ہی ذکر کیا ہے۔ ابو احمد حاکم فرماتے ہیں: یہ عمرو بن عبسہ کی کنیت ہے۔ جیسا کہ یہ روایت یزید بن ابی حبیب تک کی سند سے نقل کی ہے۔ ادھر انہوں نے عمرو بن عبسہ کے حالات میں بطریق ابن لہیعہ، یزید بن ابی حبیب، ربیعہ بن لقیط ان کے سلسلہ سند سے بحوالہ قیس کے ایک شخص جنہیں ابو نجیج کہا جاتا تھا، روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کیا تمہیں سب سے بہترین قبیلہ نہ بتاؤں؟ ہم نے عرض کی: اللہ کے رسول صلی اللہ علیہ وسلم ضرور! آپ صلی اللہ علیہ وسلم نے فرمایا: ”سکون جس کا تعلق کندہ سے ہے“۔ (حدیث) ابن لہیعہ فرماتے ہیں: میں نے یہ حدیث ثور بن یزید سے بیان کی تو انہوں نے کہا: ابو نجیج عمرو بن عبسہ صحابی رسول اللہ صلی اللہ علیہ وسلم ہیں، اسی پر ابو احمد الحاکم کا اعتماد ہے جس کا احتمال ہے یہ بھی احتمال ہے کہ کوئی اور ہوں کیونکہ اس روایت کا یزید بن ابی حبیب سے ہونے کی وجہ سے یہ لازم نہیں آتا کہ وہ ابو نجیج عبسی عمرو بن عبسہ ہی ہوں۔ کیونکہ حدیث میں اس بات کی صراحت ہے کہ وہ قیس کے شخص تھے، اور ابن مندہ نے بھی ان کا یہی عنوان قائم کیا ہے۔ لکھتے ہیں: ابو نجیج قیسی کی حدیث ربیعہ بن لقیط نے بواسطہ ایک شخص بحوالہ ان کے روایت کی ہے جو ثابت نہیں۔ ابو عمر پر اعتراض ہوتا ہے جو انہوں نے کہا کہ ”ان کی نکاح کے بارے میں ایک حدیث ہے“۔ جو روایت یزید بحوالہ ربیعہ ہے اس لیے کہ جو حدیث نکاح کے بارے میں ابو نجیج سے مروی ہے وہ روایت یزید بن عمن ربیعہ نہیں جیسا کہ میں قسم اول میں بیان کر چکا ہوں۔ اور یہ بھی بیان ہوا ہے کہ حاکم کا قول ہے: ”عرباض بن ساریہ“۔ لہذا احتمال ہے جیسے یہاں احتمال ہے کہ یہ عمرو بن عبسہ کے علاوہ کوئی صاحب ہوں۔ لیکن ثور کی گواہی اس بات کا تقاضا کرتی ہے: یہ وہی ہیں“ کہ انبی کی طرف رجوع کیا ہے۔ ادھر ابن الاثیر نے ان کے ”عبسی“ کہنے پر اشکال(2) کیا ہے، کیونکہ عمرو بن عبسہ سلمی ہیں اور ابن مندہ کے قول ”قیسی ہیں“ کو درست قرار دیا ہے، کیونکہ سلیم کا تعلق قیس سے ہے۔ بات یہی ہے۔ لیکن احتمال ہے کہ راوی نے انہیں ان کے والد عبسہ کی جانب منسوب کر دیا ہو اور یوں۔۔۔۔ اصل کتاب میں بیاض ہے۔(3)","",{"fn":"(1) اسد الغابہ (۶۳۰۲) تجرید (۲۰۸/۲)\n(2) اسد الغابہ (۱۱۵/۵)\n(3) نسخہ میں بیاض ہے۔"}],[9268,"§۱۰۶۵۸ ۔ ابونصر ہلالی\nکسی حدیث کی مرسل روایت کی ہے۔ نسائی میں قتادہ کی ان سے روایت موجود ہے کہ انہوں نے مرسل روایت کی ہے جس کی وجہ سے کسی نے انہیں صحابہ رضی اللہ عنہم میں ذکر کر دیا ہے۔ ابن مندہ فرماتے ہیں: ان کا نام مشہور نہیں۔ میں کہتا ہوں: میرے خیال میں یہ حمید بن ہلال ہیں۔"],[9269,"§۱۰۶۵۹ ۔ ابونصر سلمی(1)\nمعافی بن عمران ظہری نے مالک بن انس سے ان کی حدیث نقل کی ہے ان کی حدیث میں ہے ”دمن ابی نضر“ جبکہ درست ابن النضر ہے۔ سموطا میں بھی ایسا ہی لکھا ہے۔ ابن مندہ نے اور ابو نعیم نے ان کی پیروی میں ان کا ایسا ہی تذکرہ کیا ہے۔ ابن الاثیر(2) لکھتے ہیں: یہی روایت ابن ابی عاصم نے عن یعقوب بن حمید عن عبداللہ بن نافع عن مالک عن عبداللہ بن ابی بکر بن ابی النضر، ان لوگوں کے بارے میں نقل کی ہے جن کے تین بچے فوت ہو گئے ہوں۔ یعنی معافی نضر وئیں اور یہ ابو النضر(3) وہی ہیں۔","",{"fn":"(1) اسد الغابہ (۶۳۰۷) تجرید (۲۰۸/۲)\n(2) اسد الغابہ (۱۱۶/۵)\n(3) نسخہ میں بیاض ہے۔"}],[9270,"§۱۰۶۶۰ ۔ ابوہارون(1)\nکلاب بن امری لیشی، ناموں میں ذکر ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۶۳۱۳) تجرید (۲۰۹/۲)"}],[9271,"§۱۰۶۶۱ ۔ ابوہاشم بن عقبہ\nبن عقبہ بن ربیعہ بن عبد شمس قرشی۔ ابو سفیان عتبی کنیت تھی۔ ابو حذیفہ بن عقبہ کے باپ شریک اور مصعب بن عمیر عبدری کے ماں شریک بھائی ہیں۔ دونوں کی والدہ خناس بنت مالک عامریہ ہیں جن کا تعلق قریش سے ہے۔ نام میں اختلاف ہے۔ بقول بعض: ہاشم، ایک قول ہے: ”خالد“۔ اسی پر نسائی نے اعتماد کیا ہے۔ یہ بھی کہا جاتا ہے ان کی کنیت ہی ان کا نام ہے جس پر ابن ابی شیبہ نے بھروسا کیا ہے۔ کسی نے ہشیم/ہشام/شیبہ بھی کہا ہے۔ ابن السکن فرماتے ہیں: فتح مکہ کے روز اسلام لائے اور شام فروکش ہوئے جہاں خلافت عثمانی میں فوت ہوئے۔ یہی ابن سعد کا قول ہے، ابن مندہ لکھتے ہیں: ان سے سیدنا ابو ہریرہ، سمرہ بن جندب ابو وائل نے روایت کی ہے۔ پھر لکھتے ہیں: صحیح یہ ہے کہ ابو وائل بواسطہ سمرہ بحوالہ ان کے روایت کرتے ہیں۔ میں کہتا ہوں: ان کی حدیث ترمذی وغیرہ صحیح سند سے بطریق منصور الاعمش بحوالہ ابو وائل روایت کرتے ہیں کہ امیر معاویہ ہاشم بن عقبہ کے پاس ان کی عیادت کرنے آئے۔ کہنے لگے: ماموں! آپ کیوں رو رہے ہیں؟ کیا تکلیف کی وجہ سے رو رہے ہیں؟ یا دنیا کی لالچ پر رونا آ رہا ہے؟ فرمایا: ایسی کوئی بات نہیں، رونا اس بات پر آ رہا ہے رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ایک وصیت کی تھی میں اس پر عمل نہ کر سکا، آپ صلی اللہ علیہ وسلم نے فرمایا تھا: ”تمہارے لیے دنیا میں سے ایک خادم اور ایک سواری کافی نہیں؟“ جبکہ میں دیکھتا ہوں میں نے دنیا جمع کر رکھی ہے۔ اسے بغوی اور ابن السکن نے بطریق خیرہ، بواسطہ ابو وائل بحوالہ سمرہ بن اسہم اپنی قوم کے آدمی سے نقل کیا ہے، فرمایا: ہاشم ابو ہاشم بن عقبہ بن ربیعہ کے ہاں ٹھہرا اور معاویہ ان کی عیادت کرنے آئے، ابو ہاشم رو پڑے۔ پھر اس کا ذکر کیا۔ دنیا کی حرص کے بعد یہ بات مزید نقل کی، دنیا کے اچھے لوگ چل بسے۔ اسی میں ہے، ایک عہد تھا کاش میں اس میں آپ کی پیروی کر سکتا۔ فرما شاید تمہیں اتنا مال ملے جو تم لوگوں میں تقسیم کرو جبکہ تمہارے لیے اتنا کافی ہے۔ پھر اس کا ذکر کیا۔ ابو ہریرہ رضی اللہ عنہ نے ابی ابو ہاشم سے ایک حدیث نقل کی ہے جسے ابو داؤد، نسائی، ترمذی، بغوی اور حاکم نے بطریق کبیر بن حرملہ نقل کیا ہے، فرماتے ہیں: سیدنا ابو ہریرہ رضی اللہ عنہ دمشق آئے تو ابو کلثوم دوسی کے ہاں فروکش ہوئے۔ ہم لوگ آپ کے پاس آئے \"درمیانی نماز\" کے بارے میں بات چیت ہوئی جس میں ہمارا اختلاف ہو گیا۔ سیدنا ابو ہریرہ رضی اللہ عنہ فرمانے لگے: جس طرح تم لوگوں کا اختلاف ہوا ہے اسی طرح ایک دفعہ ہمارا بھی اختلاف ہوا، اس وقت ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے صحن میں بیٹھے تھے۔ ہمارے درمیان نیک شخص ابو ہاشم بن عقبہ بن ربیعہ تھے وہ کھڑے ہوئے رسول اللہ صلی اللہ علیہ وسلم کے پاس پہنچے، وہ آپ صلی اللہ علیہ وسلم کے سامنے بولنے کی ہمت کر لیتے تھے۔ وہاں سے واپس ہوئے اور ہمیں بتایا وہ عصر کی نماز ہے۔ ابو حسین رازی کا بیان ہے ان کی حویلی کا احاطہ تانبے کا کام کرنے والوں کے بازار سے لوہاری بازار تک ہے۔ یعقوب بن سفیان کی روایت ہے: ابو ہاشم بن عقبہ بن ربیعہ نے اہل انطاقیہ سے دونوں شہروں کے قبرستان وغیرہ کے بارے ۲۱ھ میں صلح کی۔ ابن البرقی کا قول ہے: جنگ یرموک میں ان کی آنکھ شہید ہوگئی تھی اور خلافت معاویہ میں وفات پائی۔ خلیفہ کا بیان ہے: امیر معاویہ نے انہیں جزیرہ کا گورنر بنایا تھا۔ ابو زرعہ دمشقی کا قول ہے: ابو مسہر فرماتے ہیں: ان کی وفات بہت پہلے ہو چکی تھی ابو عبد اللہ بے نسبت صحابی کے حالات میں ان کا ذکر ہوا ہے۔"],[9272,"§۱۰۶۶۲ ۔ ابو ہالہ تیمی\nنباش بن زرارہ۔ حاکم نے بحوالہ یحیی بن معین ان کا ذکر کیا ہے۔"],[9273,"§۱۰۶۶۳ ۔ ابو ہانی(1)\nعبد الرحمن بن مالک کے دادا۔ ابو عمر نے ان کا ذکر کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، آپ نے سر پر ہاتھ پھیرا اور برکت کی دعا دی۔ اور یزید بن ابی سفیان رضی اللہ عنہ کے ہاں ٹھہرایا۔ ان کی حدیث ان کا پوتا اپنے والد سے بحوالہ اپنے دادا روایت کرتا ہے۔","",{"fn":"(1) الطبقات (۱۲۸/۷) اسد الغابہ (۶۳/۵) تجرید (۲۰۹/۲)"}],[9274,"§۱۰۶۶۴ ۔ ابو ہبیرہ\nعائذ بن عمرو مزنی درخت تلے بیعت کرنے والوں میں سے ہیں۔ ناموں میں تذکرہ ہو چکا ہے۔ ابن المدینی نے ان کی کنیت لکھی ہے اور ابو احمد الحاکم نے ان سے مسنداً یہ بات نقل کی ہے۔"],[9275,"§۱۰۶۶۵ ۔ ابو ہبیرہ بن حارث\nبن علقمہ بن عمرو بن کعب بن مالک بن مبذول انصاری خزرجی بخاری۔(1) ابن اسحاق نے شہداء احد میں ان کا ذکر کیا ہے۔ حرف الف میں ان کا ذکر ہو چکا ہے کیونکہ واقدی وغیرہ نے انہیں ابو اسیرہ کہا ہے۔ بقول ابو عمر: ابو ہبیرہ کا نام ان کی کنیت ہی ہے۔","",{"fn":"(1) السیرۃ النبویہ (۹۷/۳) اسد الغابہ (۶۳/۶) تجرید (۲۰۹/۲)"}],[9276,"§۱۰۶۶۶ ۔ ابو ہبیرہ انصاری(1) (بے نسبت)\nابو یعلی نے اپنی مسند میں ان کا ذکر کیا ہے، بطریق مخرمہ بن بکیر بواسطہ ان کے والد بحوالہ سعید بن نافع روایت ہے، فرمایا: مجھے ابو ہبیرہ انصاری صحابی رسول اللہ صلی اللہ علیہ وسلم کو سورج طلوع ہوتے وقت چاشت کی نفل نماز پڑھتے دیکھا تو مجھے ڈانٹا اور منع کر دیا، پھر فرمایا، رسول اللہ صلی اللہ علیہ وسلم کا ارشاد ہے: \"جب تک سورج بلند نہ ہو جائے نماز نہ پڑھا کرو کیونکہ وہ شیطان کے دو سینگوں میں طلوع ہوتا ہے۔\"  ابن الاثیر  نے انہیں سابقہ شخصیت سے ملا دیا ہے۔ اس کے بعد فرمایا: سعید تابعی ہیں، انہوں نے اُحد میں شہید ہونے والے صحابی سے ملاقات نہیں کی، اور اگر یہ اور ہیں ورنہ یہ روایت منقطع ہے۔ اس میں منقطع کا احتمال کیسے ہو سکتا ہے وہ خود صراحت کر رہے ہیں کہ انہوں نے انہیں دیکھا، لہذا پہلا احتمال متعین ہوگا۔","",{"fn":"(1) مسند ابی یعلی (۱۷۵۲/۳) اسد الغابہ (۱۱۹/۵) تجرید (۲۰۹/۲)"}],[9277,"§۱۰۶۶۷ ۔ ابو ہدم بن الحضرمی(1)\nعلاء کے بھائی۔ دارقطنی نے ان کا ذکر کیا ہے، ایسا ہی تجرید میں ہے۔","",{"fn":"(1) اسد الغابہ (۶۳۱۷) تجرید (۲۰۹/۲)"}],[9278,"§۱۰۶۶۸ ۔ ابو ہدمہ انصاری(1)\nابو موسیٰ نے ذیل میں ان کا ذکر کیا ہے کہ مستغفری نے ان کا ذکر کیا ہے، فرماتے ہیں: ان سے ان کا بیٹا محمد حدیث ابن اخی زہری عن عمہ روایت کرتا ہے، ہمارے ہاں حدیث ابو حاتم رازی لکھی ہے۔ مستغفری لکھتے ہیں: یہ بردوگی کا قول ہے۔","",{"fn":"(1) اسد الغابہ (۶۳۱۸) تجرید (۲۰۹/۲)"}],[9279,"§۱۰۶۶۹ ۔ ابو ہذیل(1) (بے نسبت)\nان کا بھی ابو موسیٰ نے ذکر کیا ہے کہ ابو بکر بن علی نے ان کا تذکرہ کیا ہے اور بطریق ابو اشعث، عبد اللہ بن خداش سے بواسطہ اوسط بحوالہ ابو ہذیل روایت کی ہے۔ فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ارشاد فرمایا: \"آدمی اپنی قربانی میں سے کھائے\"۔","",{"fn":"(1) المعجم الکبیر (۱۲۷۱۰/۱۲) مجمع الزوائد (۲۵/۴) جامع المسانید والسنن (۷۱۳/۱۴) حلیۃ الاولیاء (۳۶۲/۴) اسد الغابہ (۱۱۹/۵)"}],[9280,"§۱۰۶۷۰ ۔ ابو ہراسہ\nقیس بن عاصم۔ بغوی نے بواسطہ ابن ابی خیثمہ بحوالہ ابن معین ان کا ذکر کیا ہے۔"],[9281,"§۱۰۶۷۱ ۔ ابو ہریرہ بن عامر(7) بن عبد ذی الشری(1)(2)(3)(4)(5)(6)\nبن طریف بن عتاب بن ابی صعب بن منبہ بن سعد بن ثعلبہ بن سلیم بن فہم بن غنم بن دوس بن عدنان بن عبد اللہ بن زہران بن کعب دوسی۔ ابن کلبی اور ان کے متبعین نے آپ کا یہی نام و نسب لکھا ہے اور ابو احمد دمیاطی نے اسے قوی کہا ہے۔ ابن اسحاق کا قول ہے: وہ دوس میں بڑے صاحب مرتبہ تھے۔ دولابی کی روایت ہے کہ ابو ہریرہ رضی اللہ عنہ کا نام: عبد نم بن عامر تھا۔ دوسی اور صدیق اکبر رضی اللہ عنہ کے حلیف ہیں۔ ابن البرقی نے دوسروں سے مختلف نسب ذکر کیا ہے۔ لکھتے ہیں: ابن عامر بن عبد شمس بن عبد السالح بن قیس بن مالک بن ذی الاسلم بن الاحمس بن معاویہ بن المسلم بن حارث بن دہمان بن سلم بن فہم بن عامر بن دوس۔ لکھتے ہیں: بقول بعض یہ ابن عقبہ بن عمرو بن عیسی بن حرب بن سعد بن ثعلبہ بن عمرو بن فہم بن دوس ہیں۔ ابو علی بن السکن کا قول ہے: ان کے نام میں اختلاف ہے، اہل نسب ان کا نام عمیر بن عامر بتاتے ہیں۔ ابن اسحاق(8) فرماتے ہیں: مجھے کسی ساتھی نے بحوالہ سیدنا ابو ہریرہ رضی اللہ عنہ بتایا: جاہلیت میں میرا نام عبد شمس بن صحر تھا، رسول اللہ صلی اللہ علیہ وسلم نے میرا نام عبد الرحمن رکھا۔ میری کنیت ابو ہریرہ ہے جس کی وجہ یہ ہے کہ ایک دفعہ مجھے ایک بلی ملی جسے میں نے اپنی آستین میں ڈال لیا تو مجھے ابو ہریرہ کہا جانے لگا۔ ایسا ہی حاکم نے ابن اسحاق سے نقل کیا ہے اور ابن مندہ نے اسی سند سے طویل ذکر کیا ہے۔ ترمذی نے حسن سند سے لکھا ہے عبید اللہ بن ابی رافع فرماتے ہیں: میں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے پوچھا: آپ کی کنیت ابو ہریرہ رضی اللہ عنہ کیوں ہے؟ فرمایا: میں اپنے گھر والوں کی بکریاں چرا رہا تھا۔ میری ایک چھوٹی سی بلی تھی جسے میں رات کے وقت درخت پر بٹھا دیتا تھا اور دن کے وقت اپنے ساتھ لے جاتا تھا میں اس سے کھیلتا تھا تو لوگوں نے میری کنیت ابو ہریرہ رکھ دی۔ بقول ابن خزیمہ ذہلی نے فرمایا: ہمارے ہاں قلب (تبدیلی) کی یہ سب سے واضح مثال ہے۔ ابن خزیمہ کا قول ہے: ابو سلمہ سے محمد بن عمرو کی سند سفیان بن حسین کی زہری سے بحوالہ محرز والی سند سے زیادہ حسن ہے البتہ یہ ہو سکتا ہے کہ اسلام سے قبل ان کے دو نام تھے۔ جہاں تک اسلام لانے کے بعد کی بات ہے تو میرے خیال میں ان کا نام نہیں چلا۔ میں کہتا ہوں: اکثر اقوال کی وجہ یہ ہے کہ صرف ان کے نام میں دس(۱۰) اقوال ہیں اور ان کے والد کے نام میں بھی تقریباً اتنے ہیں۔ لیکن یہ سارے منقول نہیں۔ لہذا صرف ان کے نام میں اقوال کا مجموعہ بیس(۲۰) ہے۔ عبد شمس / عبد نم / عبد تیم / عبد غنم / عبد العزی / عبد یالیل جو اسلام لانے کے بعد باقی نہ رہے جیسا کہ ابن خزیمہ نے اس کی طرف اشارہ کیا ہے۔ بقول عبید بغیر اضافت ہے۔ عبد اللہ اضافت کے ساتھ، سکین تصغیر ہے اور سگن دو زبروں سے ہے۔ عمرو، عمیر، عامر، بریر، بز، یزید، سعد، سعید، عبد اللہ، عبد الرحمن، ان سب کا جاہلیت و اسلام میں احتمال ہے۔ صرف آخری نام یقیناً اسلامی ہیں۔ ان کے والد کے نام میں پندرہ اقوال ہیں: عائذ، عامر، عمرو، عمیر، غنم، دومہ، ہانی، ملن، عبد نہم، غنم، عبد شمس، عبد عمرو، حارث، عشرقہ، صحر۔ یہ مطلب ہوا جس نے کہا ہے کہ ان کے اور ان کے والد کے نام میں تیس سے زائد مختلف اقوال ہیں، البتہ ترکیب کی صورت میں ممکن ہے پھر تو اس سے بھی زیادہ ہو جائیں جو انیس(۱۹) کو تیرہ(۱۳) سے ضرب دینے سے تقریباً دو سو اقوال بن جاتے ہیں۔ اور اگر صراحت کی جائے تو بیس(۲۰) سے زیادہ نہیں۔ کیونکہ ان کا ایک نام آباء و اجداد کے تین یا چار ناموں سے مرکب ہوتا ہے۔ اور پھر انہیں شمار کیا جاتا ہے۔ ترکیب کے ساتھ فرق سے بچنے کے لیے خصوصاً ان کے نام کو الگ کیا جاتا ہے۔ تو وہ انیس(۱۹) بنتے ہیں جن میں سے بعض غلط لکھے ہیں بعض میں غلطی واقع ہوئی ہے جیسے بر اور بریر اور یزید جو صرف عشرقہ کے ساتھ استعمال ہوئے ہیں۔ بظاہر کسی راوی کی تبدیلی ہے اسی طرح سکن اور سکین اور سعد و سعید دونوں ایک ہیں جو حارث کے ساتھ ہیں ان کے بعض نام ان کے والد کے نام سے بدل گئے ہیں جیسے پہلے بیان ہوا ہے۔ عبد عمرو بن عبد غنم، عبد غنم بن عبد عمرو۔ غور کیا جائے تو یہ اقوال تیرہ سے زیادہ نہیں۔ صحیح نقل کے لحاظ سے تین ہیں: عمیر، عبد اللہ اور عبد الرحمن پہلے دونوں کا جاہلیت و اسلام میں احتمال ہے جبکہ عبد الرحمن خالص اسلامی نام ہے۔ ابن ابی داؤد کا قول ہے: میں ابو ہریرہ رضی اللہ عنہ کی سندیں جمع کر رہا تھا تو مجھے خواب میں ان کی زیارت ہوئی میں اس وقت اصبہان میں تھا، انہوں نے مجھ سے فرمایا: \"میں دنیا میں پہلا حدیث والا انسان ہوں۔\" محدثین کا اتفاق ہے کہ ان کی احادیث سب سے زیادہ ہیں۔ ابو محمد بن حزم کا قول ہے کہ مسند بقی بن مخلد سیدنا ابو ہریرہ رضی اللہ عنہ کی پانچ ہزار تین سو(۵۳۰۰) احادیث پر مشتمل ہے۔ سیدنا ابو ہریرہ رضی اللہ عنہ کی حدیث، ابو بکر، عمر، فضل بن عباس، ابی بن کعب، اسامہ بن زید، عائشہ، بسرہ غفاری، کعب احبار سے بھی مروی ہے۔ ان سے ان کا بیٹا محرز اور صحابہ رضی اللہ عنہم میں سے ابن عمر، ابن عباس، جابر، انس، واثلہ بن اسقع اور اکابر تابعین میں سے مروان بن الحکم، قبیصہ بن ذویب، عبد اللہ بن ثعلبہ، سعید بن المسیب، عروہ بن زبیر، سلمان الاغر والغر، ابو مسلم، شریح بن ہانی، خباب مقصورہ والے، ابو سعید المقبری، سلیمان بن یسار، سنان بن ابی سنان، عبد اللہ بن شقیق، عبد الرحمن بن ابی عمرہ، عراک بن مالک، ابو رزین اسدی، عبد اللہ بن قارظ، بسر بن سعید، بشیر بن نہیک، بھیجہ الجھنی، حنظلہ اسلمی، ثابت بن عیاض، حفص بن عاصم بن عمر، سالم بن عبد اللہ بن عمر، ابو سلمہ، اور حمید صاحبزادگان عبد الرحمن بن عوف، حمید بن عبد الرحمن حمیری، خلاس بن عمرو، زرارہ بن ابی اوفی، سالم ابو الغیث، سالم مولا شداد، عامر بن سعد بن ابی وقاص، سعید بن عمرو بن سعید بن عاص، ابو حباب سعید بن یسار، عبد اللہ بن حارث، بصری، محمد بن سیرین، سعید بن مرجانہ، اعرج عبد الرحمن بن ہرمز ان کا نام ہے۔ مقعد جو عبد الرحمن بن سعد ہیں انہیں بھی اعرج کہا جاتا ہے۔ عبد الرحمن بن ابی نعیم، عبد الرحمن بن یعقوب جو علاء کے والد ہیں۔ ابو صالح السمان، عبیدہ بن سفیان، عبید اللہ بن عبد اللہ بن عقبہ بن مسعود، عطاء بن مینا، عطاء بن ابی رباح، عطاء بن یزید لیثی، عطاء بن یسار، عبید بن حنین، محمد کے والد محجلان، عبید اللہ بن ابی رافع، عنبہ بن سعید بن عاص، عمرو بن حکم، ابو السائب مولا ابو زہرہ، موسی بن یسار، نافع بن جبیر بن مطعم، عبد اللہ بن رباح، عبد الرحمن بن مہران، عمرو بن ابی سفیان، محمد بن زیاد، یحیی بن طلحہ، محمد بن قیس بن مخرمہ، محمد بن عباد بن جعفر، محمد بن ابی عائشہ، ہشام بن ابی سنان، ابو حازم اعرج، ابو بکر بن عبد الرحمن بن حارث بن ہشام، ابو الشعثاء محاربی، یزید بن الاصم، نعیم المجمر، محمد بن المنکدر، ہمام بن منبہ، ابو عثمان التبذی، ابو قیس مولا ابو ہریرہ اور دیگر حضرات روایت کرتے ہیں۔ امام بخاری رحمہ اللہ کا قول ہے: ان سے تقریباً آٹھ سو(۸۰۰) اہل علم نے روایت کی ہے۔ وہ اپنے دور میں سب سے زیادہ حافظ حدیث تھے۔ وکیع اپنے نسخہ میں لکھتے ہیں: ہمیں اعمش نے بحوالہ ابو صالح بیان کیا کہ ابو ہریرہ رضی اللہ عنہ اصحاب رسول میں سے سب سے زیادہ حافظ الحدیث تھے۔ یہی روایت بغوی نے بحوالہ اعمش ان الفاظ میں نقل کی ہے: اگرچہ ان سے افضل نہ تھے لیکن حافظہ سب سے زیادہ تھا۔ ابن ابی خیثمہ بطریق سعید بن ابی الحسن روایت کرتے ہیں کہ ابو ہریرہ رضی اللہ عنہ سے بڑھ کر کسی کو زیادہ حدیث یاد نہ تھی۔ یہی قول امام شافعی رحمہ اللہ کا ہے۔ ابو زعزعہ جو مروان کے کاتب ہیں۔ فرماتے ہیں: مروان نے سیدنا ابو ہریرہ رضی اللہ عنہ کی طرف پیام بھیجا تو وہ ان سے احادیث بیان کرنے لگے اور مجھے پردے کے پیچھے لکھنے کے لیے بٹھا دیا، جب سال کا اختتام ہوا ان کی طرف پیام بھیجا اور ان سے وہی احادیث بیان کرنے کا سوال کیا اور مجھے کہا غور کرتے رہنا تو ایک حرف بھی ادھر کا اُدھر نہیں کیا۔ صحیح بخاری میں بطریق وہب بن ضبہ بواسطہ ان کے بھائی ہمام بحوالہ سیدنا ابو ہریرہ رضی اللہ عنہ مروی ہے کہ اصحاب رسول صلی اللہ علیہ وسلم میں سے سوائے عبد اللہ بن عمر کے مجھ سے زیادہ کسی کو احادیث یاد نہ تھیں کیونکہ وہ لکھتے تھے: میں لکھتا نہ تھا۔ حاکم ان کے نام سابقہ اختلاف ذکر کرنے کے بعد لکھتے ہیں: صحابی رسول اللہ صلی اللہ علیہ وسلم ہیں اور سب سے زیادہ آپ سے کسب فیض کیا ہے باوجود یکہ خالی پیٹ رہتے جہاں آپ جاتے وہاں ابو ہریرہ رضی اللہ عنہ ہوتے۔ وفات تک انہوں نے آپ علیہ السلام کا ساتھ نہیں چھوڑا۔ اسی بنا پر ان کی احادیث زیادہ ہیں۔ صحیح بخاری میں بواسطہ سعید المقبری بحوالہ سیدنا ابو ہریرہ رضی اللہ عنہ روایت ہے، میں نے عرض کی: اللہ کے رسول صلی اللہ علیہ وسلم آپ کی شفاعت کا زیادہ حقدار کون ہوگا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: میرا بھی یہی خیال تھا کہ تمہارے علاوہ مجھ سے یہ بات کوئی نہیں پوچھے گا، کیونکہ تمہیں حدیث کی بڑی لگن ہے۔ امام احمد رحمہ اللہ نے حدیث ابی بن کعب نقل کی ہے کہ ابو ہریرہ رسول اللہ صلی اللہ علیہ وسلم سے ایسی باتیں پوچھ لیتا تھا جن کی کسی کو ہمت نہ ہوتی تھی۔ ابو نعیم لکھتے ہیں: اصحاب رسول صلی اللہ علیہ وسلم میں سے حدیث کے سب سے بڑے حافظ تھے، آپ نے ان کے لیے دعا فرمائی تھی کہ اہل ایمان ان سے محبت رکھیں۔ حدیبیہ اور خیبر کے درمیانی عرصے میں مسلمان ہوئے۔ مدینہ ہجرت کر کے آئے اور صفہ میں رہنے لگے، ابو معشر مدائنی بحوالہ محمد بن قیس روایت کرتے ہیں کہ ابو ہریرہ رضی اللہ عنہ فرمایا کرتے تھے: مجھے ابو ہریرہ رضی اللہ عنہ نہ کہا کرو کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے میری کنیت ابو ہر رکھی ہے اور نر مادہ سے بہتر ہے۔ بغوی نے یہ روایت صحیح سند سے نقل کی ہے اور عبد الرحمن بن ابی لہیہ کا قول ہے: میں سیدنا ابو ہریرہ رضی اللہ عنہ کے پاس آیا ان کا گندمی رنگ چوڑے کندھے دو زلفوں والے سامنے کے دانتوں میں فرق تھا۔ ابن سعد کی روایت ہے کہ قرہ بن خالد نے محمد بن سیرین سے پوچھا: کیا ابو ہریرہ کھردرا کپڑا پہنتے تھے؟ فرمایا: نہیں، نرم پہنتے تھے، میں نے پوچھا: ان کا رنگ کیسا تھا؟ فرمایا: سفید، خضاب لگاتے گیرو سے رنگے ہوئے دو کپڑے زیب تن فرماتے۔ ایک دن کستان کے کپڑے سے ناک صاف کرتے ہوئے فرمایا: واہ کیا کہنے ابو ہریرہ کے!؟ کستان سے ناک پونچھ رہا ہے۔ ابو ہلال، محمد بن سیرین سے بحوالہ سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں۔ فرمایا: مجھے اچھی طرح یاد ہے میں منبر رسول اور حجرہ عائشہ کے درمیان بے ہوش پڑا رہتا تھا، لوگ مجھے مجنون کہتے، حالانکہ مجھے کوئی جنون نہ تھا، یزید بن ابراہیم نے یہ اضافہ نقل کیا ہے: یہ صرف بھوک کی کیفیت تھی۔ اس حدیث کے صحیح میں کئی طرق ہیں۔ اس میں صدیق اکبر اور پھر عمر رضی اللہ عنہ سے ایک آیت کے بارے میں پوچھتے ہیں، فرماتے ہیں: شاید وہ مجھ سے پہل کر کے مجھے آیت بتا دیں لیکن ایسا نہ کر سکے۔ حمید حمیری فرماتے ہیں: میں ایک صحابی کی خدمت میں رہا جو رسول اللہ صلی اللہ علیہ وسلم کے ساتھ چار سال رہ چکے تھے، جیسے ابو ہریرہ رضی اللہ عنہ آپ صلی اللہ علیہ وسلم کی صحبت میں رہ چکے تھے۔ قیس بن ابی حازم فرماتے ہیں: ہمارے پاس کوفہ میں ابو ہریرہ رضی اللہ عنہ تشریف لائے، جہاں امس قبیلہ کے لوگ اکٹھے ہو گئے تا کہ انہیں سلام کریں۔ فرمایا: مرحبا میں تین سال تک رسول اللہ صلی اللہ علیہ وسلم کے ساتھ رہا مجھ سے زیادہ کسی کو حدیث یاد کرنے کا حرص نہ تھا۔ امام بخاری رحمہ اللہ کی روایت ہے، ابو ہریرہ رضی اللہ عنہ فرمایا کرتے تھے۔ بھوک کی وجہ سے میں اپنا جگر زمین سے لگا لیتا اور اپنے پیٹ پر پتھر باندھ لیتا تھا۔ پھر پیالے اور دودھ والا واقعہ ذکر کیا۔ امام احمد رحمہ اللہ کی روایت ہے کہ سیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے، اللہ کی قسم! جو مومن بھی میرے بارے میں سنے گا یا مجھے دیکھے گا مجھ سے محبت کرے گا۔ ابو کثیر جو اس حدیث کے راوی ہیں کہنے لگے: آپ کو کیسے معلوم ہوا؟ فرمایا: میری والدہ مشرک تھی اور میں انہیں اسلام کی دعوت دیتا اور وہ انکار کر دیتیں۔ ایک بار میں نے انہیں اسلام کی دعوت دی تو انہوں نے مجھے رسول اللہ صلی اللہ علیہ وسلم کے بارے میں نازیبا الفاظ سنا دیئے۔ میں روتا ہوا رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور اس بات کا ذکر کیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: اے اللہ! ابو ہریرہ کی والدہ کو ہدایت عطا فرما۔ میں وہاں سے دوڑتا ہوا باہر آیا، گھر پہنچا تو دروازے پر کواڑ لگا تھا اور پانی سے غسل کرنے کی آواز آ رہی تھی۔ پھر انہوں نے دروازہ کھولا تو فرمانے لگیں: میں گواہی دیتی ہوں کہ اللہ کے سوا کوئی دعا و عبادت کے لائق نہیں اور محمد (صلی اللہ علیہ وسلم) اللہ کے رسول ہیں۔ میں وہیں سے پلٹا اور اب میں مارے خوشی کے رو رہا تھا۔ میں نے عرض کی: اللہ کے رسول صلی اللہ علیہ وسلم اللہ تعالی سے دعا کریں کہ میری والدہ اور میری والدہ کی محبت اہل ایمان کے دلوں میں پیدا فرما دے۔ تو آپ صلی اللہ علیہ وسلم نے یہ دعا بھی دے دی۔ جریری بواسطہ ابو بصرہ بحوالہ طفاوہ کے ایک آدمی روایت کرتے ہیں کہ میں سیدنا ابو ہریرہ رضی اللہ عنہ کے ہاں فروکش ہوا۔ میں نے کسی صحابی کو ان سے زیادہ مہمان کا خدمتگار اور چست نہیں دیکھا۔ عمرو بن علی الفلاس فرماتے ہیں: ان کی آمد خیبر کے سال محرم سات ہجری میں ہوئی۔ امام بخاری وغیرہ نے بطریق سعید المقبری بحوالہ سیدنا ابو ہریرہ رضی اللہ عنہ مختصر روایت کی ہے، میں نے عرض کی: اللہ کے رسول میں میں آپ کی بہت سی باتیں سن کر بھول جاتا ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: اپنی چادر پھیلاؤ! میں نے چادر پھیلائی۔ پھر فرمایا: اسے اپنے سینے سے لگا لو۔ چنانچہ میں نے ملا لی۔ اس کے بعد مجھے کبھی کوئی بات نہیں بھولی۔ ابو یعلی بطریق ولید بن صحیح بواسطہ ابو الطفیل بحوالہ ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں۔ میں نے رسول اللہ صلی اللہ علیہ وسلم سے یادداشت کی کمی کی شکایت کی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اپنی چادر کھولو!\" پھر اسی کا مفہوم ذکر کیا۔ ابو نعیم بطریق عبد اللہ بن ابی یحیی، سعید بن ابی ہند بحوالہ ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم مجھ سے ان غنیمتوں میں سے کچھ نہیں مانگتے؟ میں نے عرض کی: میں آپ صلی اللہ علیہ وسلم سے اس علم کا سوال کرتا ہوں جو اللہ تعالیٰ نے آپ صلی اللہ علیہ وسلم کو سکھایا ہے۔ آپ نے اپنے اوپر اوڑھی ہوئی چادر پشت مبارک سے اتار کر میرے اور اپنے درمیان بچھا دی، اور پھر مجھ سے گفتگو کرنے لگے یہاں تک کہ آپ صلی اللہ علیہ وسلم کی مکمل بات میرے ذہن نشین ہوگئی۔ پھر فرمایا: اس چادر کو لپیٹ کر اپنے ساتھ ملا لو۔\" پھر میری یہ حالت ہوگئی کہ آپ جو بات بیان کرتے اس کا ایک حرف بھی میرے حافظے سے نہ نکلتا۔ اس حدیث کے صحیح طرق پہلے بیان ہو چکے ہیں۔ اس کے اور طرق بھی ہیں ان میں سے ایک ابو یعلی نے بطریق یونس بن عبید بواسطہ حسن بحوالہ ابو ہریرہ رضی اللہ عنہ نقل کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کون مجھ سے ایک، دو، یا تین باتیں لے کر اپنے پلے باندھتا تا کہ انہیں سیکھے اور سکھائے، فرماتے ہیں: میں نے اپنا کپڑا بچھایا آپ گفتگو فرما رہے تھے، پھر میں نے لپیٹ لیا۔ مجھے امید ہے کہ جو بات بھی آپ صلی اللہ علیہ وسلم نے فرمائی ہے میں اسے نہیں بھولوں گا۔ امام احمد رحمہ اللہ نے بحوالہ حسن اس کا مفہوم نقل کیا ہے، اس میں ہے میں نے عرض کی: میں اس خدمت کے لیے تیار ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: اپنا کپڑا بچھاؤ، اس کے آخر میں ہے۔ مجھے امید ہے کہ اس کے بعد میں آپ کی سنی ہوئی کوئی بات نہیں بھولوں گا۔ ابن عساکر رحمہ اللہ کی روایت ہے کہ سیدنا ابو ہریرہ رضی اللہ عنہ نے فرمایا: میں نبی صلی اللہ علیہ وسلم کے پاس تھا، پھر میں نے اپنا کپڑا بچھایا اور اسے لپیٹ لیا اس کے بعد سے کبھی کوئی بات نہیں بھولا۔ یہ پہلے سے مختصر ہے مجھے وہ حدیث ملی ہے جو اس واقعہ میں رسول اللہ صلی اللہ علیہ وسلم نے ارشاد فرمائی تھی۔ اگر وہ حدیث ثابت ہو جائے۔ چنانچہ ابو یعلی نے نقل کیا ہے کہ ابو ہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم کے پاس آ کر آپ کی بیمار پرسی کرنے لگے۔ آپ نے اجازت دی، اندر گئے کھڑے کھڑے سلام کیا اور نبی صلی اللہ علیہ وسلم سیدنا علی رضی اللہ عنہ کے سینے سے ٹیک لگائے بیٹھے تھے اور آپ نے ان کا ہاتھ تھاما ہوا تھا۔ آپ علیہ السلام کے پاؤں دراز تھے۔ آپ نے فرمایا: ابو ہریرہ قریب آ جاؤ، چنانچہ یہ قریب ہوئے۔ پھر فرمایا: اور نزدیک ہو جاؤ، تو اور قریب ہو گئے۔ تیسری بار فرمایا: ابو ہریرہ رضی اللہ عنہ قریب ہو جاؤ! تو اتنے قریب ہو گئے کہ ابو ہریرہ نبی صلی اللہ علیہ وسلم کے پورے رسول اللہ صلی اللہ علیہ وسلم کی انگلیوں کو چھونے لگے۔ اس کے بعد ان سے فرمایا: \"بیٹھ جاؤ!\" وہ بیٹھ گئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اپنا کپڑا میرے قریب کرو۔ سیدنا ابو ہریرہ رضی اللہ عنہ نے اپنا کپڑا دراز کیا اور ہاتھ میں پکڑ کر کھولا، نبی صلی اللہ علیہ وسلم کے قریب کیا، نبی صلی اللہ علیہ وسلم نے فرمایا: \"ابو ہریرہ! میں تمہیں چند باتوں کی وصیت کرتا ہوں جب تک زندہ رہو انہیں نہ چھوڑنا\"۔ عرض کی: جو چاہیں وصیت فرمائیں۔ فرمایا: جمعے کے دن غسل کیا کرنا اور جمعہ کے لیے جلدی جانا، وہاں نہ لغو کام کرنا اور نہ غافل ہونا، ہر ماہ تین دن روزہ رکھنا، جو ہمیشہ کے روزوں کی طرح ہیں۔ فجر کی دو سنتیں کبھی نہ چھوڑنا اگرچہ تم پوری رات نوافل (نماز) پڑھتے رہے ہو کیونکہ ان دونوں میں (رغائب) رغبت کی برکتیں ہیں۔\" آپ صلی اللہ علیہ وسلم نے یہ باتیں تین بار ارشاد فرمائیں، پھر فرمایا: \"اپنا کپڑا سمیٹ لو۔ انہوں نے سمیٹ کر سینے سے لگا لیا۔ عرض کی: اللہ کے رسول! میرے ماں باپ آپ پر قربان ہوں، یہ بات پوشیدہ رکھوں یا سب کو بتا دوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ابو ہریرہ! سب کو بتا دو۔ یہ بھی آپ صلی اللہ علیہ وسلم نے تین بار فرمایا۔ مذکورہ حدیث علامات نبوت میں سے ہے، کیونکہ ابو ہریرہ رضی اللہ عنہ اپنے دور کے سب سے بڑے احادیث نبویہ کے حافظ تھے۔ طلحہ بن عبید اللہ کا قول ہے: اس میں کوئی شک نہیں جو باتیں ہم نے رسول اللہ صلی اللہ علیہ وسلم سے نہیں سنیں وہ ابو ہریرہ رضی اللہ عنہ نے سنی ہیں۔ سیدنا ابن عمر رضی اللہ عنہ کا قول ہے: ابو ہریرہ مجھ سے بہتر اور جو بیان کرتا ہے اسے زیادہ جانتا ہے۔ نسائی نے کتاب السنن میں عمدہ سند سے نقل کیا ہے کہ ایک شخص سیدنا زید بن ثابت کے پاس آ کر کوئی مسئلہ پوچھنے لگا، آپ نے فرمایا: ابو ہریرہ رضی اللہ عنہ سے پوچھا کرو کیونکہ ایک دفعہ میں، ابو ہریرہ اور ایک شخص مسجد میں دعا مانگ رہے تھے اور اللہ تعالیٰ کا ذکر کر رہے تھے، اتنے میں رسول اللہ صلی اللہ علیہ وسلم باہر تشریف لائے اور ہمارے پاس آ کر بیٹھ گئے، فرمانے لگے: \"تم لوگ جس بات میں مشغول تھے اسے جاری رکھو!\" زید فرماتے ہیں: میں اور میرا ساتھی دعا کرنے لگے اور رسول اللہ صلی اللہ علیہ وسلم آمین کہنے لگے۔ پھر ابو ہریرہ رضی اللہ عنہ نے دعا کی: \"میں وہی دعا کروانا چاہتا ہوں جو آپ کے دونوں صحابیوں نے کی، میں ایسا علم مانگتا ہوں جو بھولے نہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"آمین\"۔ ہم نے عرض کی \"اللہ کے رسول صلی اللہ علیہ وسلم ہم بھی آپ صلی اللہ علیہ وسلم سے ایسے علم کی دعا کی درخواست کرتے ہیں جو بھولے نہیں\"۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"دوسی نوجوان تم سے پہلے کر گیا۔\" ترمذی(9) کی روایت ہے: ابو ہریرہ رضی اللہ عنہ فرماتے ہیں، میں نے عرض کی: اللہ کے رسول صلی اللہ علیہ وسلم میں آپ کی بہت سی باتیں سنتا ہوں لیکن وہ مجھے یاد نہیں رہتیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اپنی چادر بچھاؤ!\" میں نے چادر بچھائی۔ آپ صلی اللہ علیہ وسلم نے کئی احادیث بیان کیں تو ان میں سے میں کوئی بھی نہ بھولا۔ اس کی سند صحیح ہے، اصل اس کی بخاری میں ان الفاظ میں ہے: پھر میں آپ صلی اللہ علیہ وسلم کی سنی ہوئی کوئی بات نہیں بھولا۔ ترمذی ہی کی روایت بحوالہ عمر رضی اللہ عنہ ہے آپ نے سیدنا ابو ہریرہ رضی اللہ عنہ سے فرمایا: \"تم ہم سے زیادہ رسول اللہ صلی اللہ علیہ وسلم کے پاس رہے ہو اور ہم سے زیادہ آپ صلی اللہ علیہ وسلم کی حدیث کے حافظ ہو، ابن سعد کی روایت ہے سالم مولا بنی نصر فرماتے ہیں: میں نے ابو ہریرہ رضی اللہ عنہ کو فرماتے سنا: مجھے رسول اللہ صلی اللہ علیہ وسلم نے علاء بن حضرمی کے ساتھ بھیجا، انہیں میرے بارے میں خیر سگالی کی وصیت کی، وہ مجھ سے کہنے لگے تمہیں کیا بات پسند ہے؟ میں نے کہا: میں تمہارے لشکر میں اذان دوں گا اور تم آمین کہنے میں مجھ سے پہل نہ کرنا۔ بخاری میں بواسطہ سعید المقبری بحوالہ ابو ہریرہ رضی اللہ عنہ ہے، فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے دو دعائیں یاد کی ہیں۔ ایک میں نے پھیلی دی ہے۔ دوسری اگر پھیلاؤں تو یہ گردن کٹ جائے۔ مسند احمد میں بطریق یزید بن الاصم بحوالہ ابو ہریرہ مروی ہے کسی نے آپ سے کہا: آپ بہت زیادہ احادیث بیان کرتے ہیں! آپ نے فرمایا: میں اگر تم سے ہر وہ بات بیان کر دوں جو میں نے سنی ہے تو تم مجھے کوڑے لگانے لگو۔ صحیح میں نافع سے منقول ہے، کسی نے ابن عمر رضی اللہ عنہ سے کہا: ابو ہریرہ نے حدیث بیان کی ہے جو شخص نماز تک جنازے کے پیچھے چلے اس کے لیے ایک قیراط ہے.... (حدیث) آپ نے فرمایا: ابو ہریرہ رضی اللہ عنہ بڑی احادیث سناتا ہے، سیدہ عائشہ رضی اللہ عنہا سے پوچھا، انہوں نے تصدیق کی جس پر ابن عمر رضی اللہ عنہ فرمانے لگے: \"ہم سے تو کئی قیراط میں کوتاہی ہوگئی\"۔ بغوی نے صحیح سند کے ذریعہ ولید بن عبد الرحمن سے بحوالہ ابن عمر رضی اللہ عنہ روایت کی ہے کہ انہوں نے ابو ہریرہ رضی اللہ عنہ سے کہا: تم ہم سے زیادہ رسول اللہ صلی اللہ علیہ وسلم کے پاس رہتے ہو اور ہم سے زیادہ تمہیں احادیث یاد ہیں۔ ابن سعد نے عمدہ سند سے سعید بن عمرو بن سعید بن عاص کی روایت کی کہ سیدہ عائشہ رضی اللہ عنہا نے سیدنا ابو ہریرہ رضی اللہ عنہ سے فرمایا: تم ایسی احادیث بیان کر دیتے ہو جو میں نے نہیں سنیں، عرض کی: اماں جی! میں نے یہ احادیث تلاش کی ہیں، اور آپ شیشے سرے میں مشغول تھیں۔ اور ابو ہریرہ رضی اللہ عنہ کو کوئی اور کام نہ تھا جس کے متعلق بہت زیادہ روایات ہیں۔ بیہقی نے مدخل میں روایت کی ہے کہ ابو ہریرہ رضی اللہ عنہ کی کعب سے ملاقات ہوئی تو ان سے احادیث بیان کر کے ان سے پوچھنے لگے، کعب کا کہنا ہے: میں نے ابو ہریرہ رضی اللہ عنہ سے بڑھ کر کوئی شخص نہیں دیکھا جس نے تورات پڑھی نہیں لیکن تورات کی باتوں کا زیادہ عالم ہے۔ امام احمد رحمہ اللہ بطریق عاصم بن کلیب وہ اپنے والد سے کہ میں نے ابو ہریرہ رضی اللہ عنہ کو فرماتے سنا وہ حدیث بیان کرنے سے پہلے یہ الفاظ کہا کرتے تھے: \"رسول اللہ صلی اللہ علیہ وسلم جو بچے ابو القاسم ہیں، ارشاد فرمایا: جس نے جان بوجھ کر میرے متعلق جھوٹ بولا اس کا ٹھکانہ جہنم ہے\"۔ مسدد اپنی مسند میں سیدنا ابو ہریرہ رضی اللہ عنہ کی روایت نقل کرتے ہیں کہ سیدنا عمر رضی اللہ عنہ کو میری حدیث پہنچی تو وہ مجھے کہنے لگے تمہیں یاد ہوگا ایک دن ہم فلاں گھر میں اکٹھے تھے؟ میں نے کہا: ہاں! اسی دن رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا: جس نے میرے متعلق جھوٹ بولا... (حدیث) جس پر عمر بے ساختہ بولے: جاؤ! اب حدیث سناتے رہو۔ مسدد کی ہی روایت ہے کہ ابن عمر جب ابو ہریرہ رضی اللہ عنہ کو حدیث بیان کرتے سنتے تو فرماتے: ہمیں معلوم ہے جو تم بیان کرتے ہو لیکن ہم ڈرتے اور تم جرات سے کام لیتے ہو۔ ہم نے فوائد مزکی میں دارقطنی کی تخریج بحوالہ ابو ہریرہ رضی اللہ عنہ مرفوع نقل کی ہے: \"جب تم میں سے کوئی فجر کی دو رکعتیں (سنتیں) پڑھ لے تو دائیں ہاتھ کی ٹیک لگا کر لیٹ جایا کرے۔ جس پہ مروان نے کہا: ہمارے لیے چل کر مسجد آنا کافی نہیں، پھر آ کر ہمیں یہاں بھی لیٹیں؟ آپ نے فرمایا: نہیں۔ سیدنا ابن عمر رضی اللہ عنہ تک یہ بات پہنچی، آپ نے فرمایا: ابو ہریرہ بڑی احادیث بیان کرتا ہے۔ کسی نے ان سے پوچھا: آپ کو ان کی کوئی روایت اوپری لگی ہے؟ فرمایا: نہیں۔ لیکن وہ جرات مند اور ہم بزدل ہیں۔ ابو ہریرہ رضی اللہ عنہ کو معلوم ہوا تو فرمایا: میرا کیا گناہ ہے اگر میں نے یاد رکھا اور یہ لوگ بھول گئے؟ یہ مرفوع حدیث ابو داؤد نے نقل کی ہے۔ ابن سعد کی روایت ہے ولید بن رباح نے کہا: میں نے اس وقت ابو ہریرہ رضی اللہ عنہ کو مروان سے فرماتے سنا جب لوگوں نے سیدنا حسن رضی اللہ عنہ کو ان کے نانا کے پاس دفن کرنا چاہا: تم فضول کام میں دخل اندازی کر رہے ہو۔ اس وقت گورنر کوئی اور تھا۔ حقیقت یہ ہے تم ایک غائب آدمی کی رضا مندی کی تلاش میں ہو۔ مروان غصے سے بھڑک اٹھا فوراً ابو ہریرہ رضی اللہ عنہ پر چوٹ ماری کہ لوگ تو کہتے ہیں: ابو ہریرہ بہت زیادہ حدیثیں بیان کرتا ہے۔ جبکہ یہ نبی صلی اللہ علیہ وسلم کی وفات سے پہلے ہی کچھ عرصہ آیا ہے۔ سیدنا ابو ہریرہ رضی اللہ عنہ بولے: میں جب آیا تھا رسول اللہ صلی اللہ علیہ وسلم خیبر میں تھے، میری عمر تیس(۳۰) سے کچھ اوپر تھی۔ میں آپ صلی اللہ علیہ وسلم کی وفات تک آپ صلی اللہ علیہ وسلم کے ساتھ رہا۔ آپ اپنی ازواج مطہرات رضی اللہ عنہن کے گھر تشریف لے جاتے تو ابو ہریرہ ساتھ ساتھ خدمت گزاری میں رہتا۔ غزووں میں حج میں آپ کے ساتھ رہا، مجھے آپ صلی اللہ علیہ وسلم کی حدیث کا سب سے زیادہ علم ہے۔ اللہ کی قسم! جن لوگوں کو مجھ سے پہلے آپ صلی اللہ علیہ وسلم کا صحابی ہونے کا شرف حاصل ہے وہ آپ صلی اللہ علیہ وسلم کے ساتھ میرا رہنا جانتے ہیں وہ لوگ مجھ سے آپ صلی اللہ علیہ وسلم کی حدیث پوچھتے تھے جن میں عمر، عثمان، علی، طلحہ اور زبیر شامل ہیں۔ اللہ کی قسم! مدینہ میں کوئی حدیث مجھ سے مخفی نہیں۔ اور اس کی حدیث جسے رسول اللہ صلی اللہ علیہ وسلم کے ہاں قدر و منزلت حاصل تھی اور جسے آپ صلی اللہ علیہ وسلم نے مدینہ میں سے نکال دیا ہو کہ وہ وہاں رہے۔ راوی کا بیان ہے: اللہ کی قسم! اس کے بعد مروان ان سے باز رہا۔ ابن ابی خیثمہ کی روایت ہے کہ عمر یا عثمان بن عروہ بحوالہ اپنے والدہ روایت کرتے ہیں کہ مجھ سے فرمایا: مجھے اس یمانی کے نزدیک کرنا (یعنی ابو ہریرہ رضی اللہ عنہ) کیونکہ یہ بہت حدیثیں بیان کرتے ہیں۔ میں نے ان کے قریب کر دیا، تو وہ حدیثیں بیان کرنے لگے اور زبیر فرماتے جاتے تھے: یہ بیچ ہے یہ جھوٹ ہے۔ میں نے عرض کی: یہ کیا بات ہوئی؟ فرمایا: یہ تو سچ ہے انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے لیکن بعض باتیں بے موقع بیان کر دی ہیں۔ پہلے سیدنا طلحہ کا قول گزر چکا ہے کہ جسے ابو ہریرہ رضی اللہ عنہ نے سنا ویسا ہی ہم نے سنا لیکن اسے یاد رہا اور ہم بھول گئے۔ فوائد تمام میں بطریق اشعث بن سلیم وہ اپنے والد سے کہ میں نے اپنے والد کو سیدنا ابو ہریرہ رضی اللہ عنہ کے حوالہ سے حدیث بیان کرتے سنا کہ ابو ہریرہ رضی اللہ عنہ نے سنا ہے۔ امام احمد نے \"کتاب الزہد میں صحیح سند کے ذریعہ بحوالہ ابو عثمان نہدی روایت کی ہے میں ستر بار ابو ہریرہ رضی اللہ عنہ کا مہمان بنا ان کی روٹین (ترتیب) یہ تھی کہ وہ ان کی اہلیہ اور ان کی خادمہ رات کو تین حصوں میں بانٹ لیتے تھے۔ یہ نماز پڑھتے تو وہ سو جاتے اور پھر انہیں بیدار کر دیتے۔ ابن سعد صحیح سند سے نقل کرتے ہیں کہ عکرمہ نے فرمایا: ابو ہریرہ رضی اللہ عنہ روزانہ بارہ ہزار بار سبحان اللہ پڑھتے تھے اور فرماتے: میں اپنے گناہ کی مقدار تسبیح پڑھتا ہوں۔ حلیہ میں تاریخ ابو العباس سراج کے حوالہ سے صحیح سند کے ذریعہ مضارب بن حزن کا قول ہے ایک رات میں جا رہا تھا کوئی شخص اللہ اکبر کی صدا بلند کر رہا تھا میں اس کے پاس پہنچ گیا، میں نے کہا: یہ کیا سلسلہ ہے؟ کہنے لگا: میں اس بات پر اللہ کا شکر ادا کر رہا ہوں کہ پہلے میں بسرہ بنت غزوان کے ہاں اپنے اور اپنے گھوڑے کے خرچ پر ملازم تھا جب وہ لوگ سوار ہو کر چلتے میں ان کی سواریاں لے کر جاتا اور جب فروکش ہوتے ان کی خدمت کرتا تھا۔ اللہ تعالیٰ نے میری شادی اسی سے کرا دی۔ اب میں سوار ہوتا ہوں اور جب اترتا ہوں تو میری خدمت میں خادم موجود ہوتے ہیں۔ ابن خزیمہ نے اسی سند سے یہ روایت اس اضافے کے ساتھ نقل کی ہے۔ جب وہ نرم زمین پر پہنچتی تو مجھے کہتی: میرے لیے عصیدہ (گھی آٹا ملا کھانا) تیار کرو۔ اب میں کہتا ہوں: میرے لیے عصیدہ تیار کرو۔ عبد الرزاق، معمر، ایوب، بحوالہ ابن سیرین روایت کرتے ہیں کہ سیدنا عمر رضی اللہ عنہ نے ابو ہریرہ رضی اللہ عنہ کو بحرین کا گورنر مقرر کیا تو وہ ان کے پاس دس ہزار(۱۰۰۰۰) لے کر آئے۔ سیدنا عمر رضی اللہ عنہ نے ان سے کہا: تم نے یہ مال اپنے لیے مخصوص کیا ہے، تمہیں کیسے ملا؟ فرمایا: میری گھوڑیاں حمل سے فارغ ہوئیں، پے در پے کے عطیے، اور میرے غلام کا خراج ہے جب سیدنا عمر رضی اللہ عنہ نے حساب دیکھا تو واقعی ایسا ہی تھا۔ پھر دوبارہ انہیں مقرر کرنا چاہا تو انہوں نے انکار کر دیا، سیدنا عمر رضی اللہ عنہ نے فرمایا: یہ عہدہ تو تم سے زیادہ بہتر شخص نے بھی طلب کیا ہے؟ پوچھا: وہ کون ہے؟ فرمایا: یوسف علیہ السلام۔ فرمایا: یوسف نبی اور نبی علیہ السلام کے بیٹے تھے اور میں ابو ہریرہ امیمہ کا بیٹا ہوں۔ مجھے تین باتوں کا خوف ہے۔ بغیر علم کوئی بات کہہ دوں، یا بغیر حکم کوئی فیصلہ کر دوں جس کے نتیجے میں مجھے کوڑے لگیں، میری بے عزتی ہو اور میرا مال ضبط ہو جائے۔ کتاب المزاح میں ابن ابی الدنیا اور زبیر بن بکار نے بطریق ابن عجلان، سعید سے بحوالہ ابو ہریرہ رضی اللہ عنہ روایت کی ہے کہ ایک شخص نے ان سے پوچھا: میں روزے سے تھا اپنے والد کے گھر آیا جہاں روٹی اور گوشت پکا ہوا تھا اور بھولے سے پیٹ بھر کر کھا لیا ہے۔ ابو ہریرہ رضی اللہ عنہ فرمانے لگے: اللہ نے تجھے کھلایا ہے وہ صاحب کہتے ہیں: میں وہاں سے نکل کر کسی اور کے ہاں گیا وہاں اونٹنی(10) دوہی جا رہی تھی میں نے سیراب ہو کر اس کا دودھ پی لیا۔ ابو ہریرہ رضی اللہ عنہ فرمانے لگے: اللہ تعالیٰ نے تجھے سیراب کیا ہے۔ پھر وہ صاحب کہتے ہیں: میں اپنے گھر گیا، قیلولہ (دوپہر کا آرام) کیا۔ بیدار ہوا تو پانی مانگا جسے پی گیا۔ سیدنا ابو ہریرہ رضی اللہ عنہ فرمانے لگے: بھتیجے! تم روزے کی طرف کیوں آتے ہو؟ اور ابن ابی الدنیا ہی \"المحتضرین\" میں بحوالہ ابو سلمہ بن عبد الرحمن صحیح سند سے لکھتے ہیں کہ میں ابو ہریرہ رضی اللہ عنہ کے ہاں گیا تو وہ سخت بیمار تھے میں ان سے لپٹ کر دعا کرنے لگا: \"اے اللہ! ابو ہریرہ رضی اللہ عنہ کو شفا دے\" فوراً بولے: \"اے اللہ! اسے نہ لوٹا۔ تین بار ایسا فرمایا، پھر فرمانے لگے: \"اگر تم سے ہو سکے تو مر جاؤ، اس ذات کی قسم جس کے قبضہ میں میری جان ہے ایسا زمانہ آنے والا ہے کہ گزرنے والا قبر میں پڑے شخص کی جگہ ہونے کی تمنا کر کے رہے گا\"۔ میں کہتا ہوں: یہ حدیث ابو ہریرہ رضی اللہ عنہ سے مرفوعاً مروی ہے عمر بن ہانی کہتے ہیں، ابو ہریرہ رضی اللہ عنہ فرمایا کرتے تھے: معاویہ کی کنپٹیاں پکڑ لیا کرو، اے اللہ! ساٹھ(۶۰) سے مجھے بچا۔ امام احمد اور نسائی نے صحیح سند کے ذریعہ بواسطہ عبد الرحمن بن مہران بحوالہ ابو ہریرہ رضی اللہ عنہ روایت کی ہے کہ آپ صلی اللہ علیہ وسلم نے وفات کے وقت فرمایا: مجھ پر نہ خیمہ لگانا، نہ دھونی لے جانا بلکہ (سارے کام چھوڑ کر) میری نعش کو جلدی لے جانا۔ ابو القاسم بن الجراح اپنے \"امالی\" میں بطریق عثمان غطفانی، محمد بن عمرو سے بواسطہ ابو سلمہ بحوالہ ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں، فرمایا: جب میں مر جاؤں تو نہ مجھے یہ نوحہ (بین کر کے رونا) نہ دھونی ساتھ لے جانا۔ بلکہ مجھے جلدی لے جانا۔ بغوی نے دوسری سند سے لکھا ہے کہ وفات کے وقت ابو ہریرہ رضی اللہ عنہ رو پڑے، کسی نے پوچھا، فرمایا: \"توشہ کم ہے اور سفر لمبا ہے۔\" ابن ابی الدنیا بطریق مالک، بواسطہ سعید المقبری روایت کرتے ہیں کہ مروان ابو ہریرہ رضی اللہ عنہ کے مرض الوفات میں ان کے پاس آیا، مروان کہنے لگا: اللہ آپ کو شفا یاب کرے۔ ابو ہریرہ رضی اللہ عنہ بولے: اللہ! مجھے آپ کی ملاقات محبوب ہے، آپ بھی میری ملاقات کو پسند فرمائیے! مروان ابھی بازار کے درمیان بھی نہ پہنچا ہوگا کہ آپ رضی اللہ عنہ کی روح پرواز کر گئی۔ واقدی کا بیان ہے ولید بن عقبہ بن ابی سفیان نے لوگوں کو عصر کی نماز پڑھانے کے بعد ابو ہریرہ رضی اللہ عنہ کا جنازہ پڑھایا۔ لوگوں میں ابن عمر اور ابو سعید خدری رضی اللہ عنہما بھی تھے۔ ولید نے امیر معاویہ کو تحریراً وفات کی اطلاع دی۔ انہوں نے لکھ بھیجا ان کے وارثوں کو دیکھنا کون ہیں۔ انہیں دس ہزار درہم دینا اور ان سے اچھا سلوک کرنا۔ کیونکہ محاصرہ عثمان کے روز انہوں نے مدد کی تھی۔ ابو سلیمان بن زبر اپنی تاریخ میں لکھتے ہیں: ابو ہریرہ رضی اللہ عنہ اٹھہتر(۷۸) برس زندہ رہے۔","",{"fn":"(1) اسد الغابہ (۶۳۱۹) تجرید (۲۰۹/۲)\n(2) صحیح بخاری میں ہے نبی صلی اللہ علیہ وسلم نے انہیں فرمایا: ابو ہر۔ بغوی نے بطریق ابراہیم بن فضل مخزومی جو ضعیف راوی ہے نقل کیا ہے کہ ابو ہریرہ رضی اللہ عنہ کا جاہلیت میں نام عبد شمس تھا اور کنیت ابو الاسود تھی۔ رسول اللہ صلی اللہ علیہ وسلم نے ان کا نام عبد اللہ رکھا اور کنیت ابو ہریرہ ہی رکھی۔ ابن خزیمہ قوی سند سے لکھتے ہیں: سیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے عبد شمس کا تعلق ازد میں سے دوس سے تھا۔ دولابی حسن سند سے بحوالہ عبید اللہ بن ابی رافع اور مقبری روایت کرتے ہیں۔ دونوں کا قول ہے: سیدنا ابو ہریرہ رضی اللہ عنہ کا نام عبد شمس بن عامر بن عبد الشری تھا۔ شری دوس کے بت کا نام ہے جب اسلام لائے تو ان کا نام عبد اللہ بن عامر رکھا گیا۔ عبد اللہ بن ادریس بحوالہ شعبہ روایت کرتے ہیں، ابو ہریرہ رضی اللہ عنہ کا نام عبد شمس تھا۔ یہی یحیی بن معین، احمد بن صالح مصری اور ہارون بن حاتم کا قول ہے اور یہی ابو زرعہ کا بحوالہ ابو مسہر قول ہے۔ ابو نعیم فضل بن دکین نے یہی الفاظ اس اضافے کے ساتھ نقل کیے ہیں، بقول بعض: عبد عمرو، دوسری بار لکھتے ہیں: ابو ہریرہ سکین۔ بقول بعض: عامر بن غنم۔ ایسا ہی اسماعیل بن ابی اویس کا قول ہے کہ میں نے اپنے والد کی کتاب میں دیکھا ہے ابو ہریرہ کا نام عبد شمس تھا اور اسلام میں ان کا نام عبد اللہ تھا۔ ابو نمیر سے بھی یہی الفاظ مروی ہیں، اور ترمذی نے بخاری سے یہی الفاظ نقل کیے ہیں۔ صالح بن احمد بن حنبل بحوالہ اپنے والد روایت کرتے ہیں: ابو ہریرہ عبد شمس، بقول بعض: عبد نم / عبد غنم / اسکین / عبد اللہ بن عامر۔ یہ قول بغوی نے بحوالہ صالح نقل کیا ہے اور ایسا ہی احوص بن مفضل علائی نے اپنے والد سے اور یعقوب بن سفیان نے اپنی تاریخ میں لکھا ہے۔ ابن ابی شیبہ نے یہی الفاظ اس اضافے کے ساتھ نقل کیے ہیں۔ بقول بعض: عبد الرحمن بن صحر۔ بغوی عبد اللہ بن احمد سے روایت کرتے ہیں، فرمایا: میں نے اپنے ایک عمر رسیدہ بزرگ سے سنا: ابو ہریرہ رضی اللہ عنہ کا نام سکین بن دومہ تھا، یہ قول حسن بن سفیان اپنی سند سے بحوالہ ابو عمر ضریر اس اضافے کے ساتھ نقل کیا ہے، بقول بعض: عبد عمرو بن غنم۔ عمرو بن علی فلاس، سفیان بن حسین سے بواسطہ زہری بحوالہ محرز بن ابی ہریرہ روایت کرتے ہیں: میرے والد کا نام عبد عمرو بن عبد غنم تھا، یہی قول اسلم بن سہل نے اپنی تاریخ میں اور بغوی نے مقدمی سے انہوں نے بحوالہ اپنے چچا سفیان سے ان الفاظ میں نقل کیا ہے: ابو ہریرہ رضی اللہ عنہ کا نام عبد الرحمن بن غنم تھا۔ ایسا ہی بغوی سے عیسی بن علی کی روایت میں ہے۔ ابن ابی الدنیا نے بطریق مقدمی عمرو بن علی کے قول جیسا قول نقل کیا ہے ذہلیات میں عمرو بن بکار سے بحوالہ عمرو بن علی مقدمی ایسا ہی لکھا ہے۔\n(3) السیرۃ والمغازی (۲۸۶)\n(4) میں کہتا ہوں: انہوں نے اس بات کا انکار کیا ہے کہ نبی صلی اللہ علیہ وسلم نے ان کا نام تبدیل کیا تھا اور عبد الرحمن رکھا تھا۔ جیسا کہ امام احمد رحمہ اللہ نے ابو عبیدہ الحداد سے نقل کیا ہے اور ابو محمد بن زید اصمعی سے روایت کرتے ہیں کہ ان کا نام عبد عمرو بن عبد غنم تھا۔ بقول بعض: عمرو بن غنم، پہلے پر نسائی نے اعتماد ظاہر کیا ہے۔ بغوی کا قول ہے: ہمیں ابو اسماعیل المؤدب نے بتایا کہ ابو ہریرہ رضی اللہ عنہ کا نام عبد الرحمن بن صحر تھا۔ میں کہتا ہوں: ابو اسماعیل عجیب و غریب باتیں نقل کرتا ہے۔ باوجود یکہ ان کی یہ بات کہ ان کا نام عبد الرحمن بن صحر تھا، اس میں احتمال ہے کہ یہ ابو صالح یا بعد کے کسی آدمی کا قول ہو اور زیادہ قرین قیاس ہے کہ ابو اسماعیل کا ہی قول ہو جو اس میں منفرد ہے اور محفوظ محمد بن اسحاق کا قول ہے۔ ابو نعیم بطریق اسحاق بن راہویہ روایت کرتے ہیں کہ ابو ہریرہ رضی اللہ عنہ کے نام میں اختلاف ہے۔ سکین بن مل / ابی صانی / عامر بن عبد شمس / ابن عبد نم۔ عباس ڈوری بحوالہ ابو بکر بن ابی الاسود: سکین بن جابر نقل کرتے ہیں۔ حاکم صحیح سند کے ذریعہ بحوالہ صالح بن کیسان روایت کرتے ہیں ان کا نام عامر تھا اور ہیشم بن عدی بحوالہ ابن عباس المسوق یہ اضافہ نقل کرتے ہیں۔ ابن عبد شمس بن عبد غنم بن عبد ذی الشری۔ ابو مسہر بحوالہ سعید بن عبد العزیز: عامر بن عبد شمس۔ بقول بعض: عبد غنم اور سکین بن عامر نقل کرتے ہیں۔ خلیفہ فرماتے ہیں، ان کے نام میں اختلاف ہے: عمیر بن عامر / سکین بن دومہ / عبد عمرو بن عبد غنم / عبد اللہ بن عامر / بریر / یزید بن عشرقہ۔ فلاس کا قول ہے: ان کے نام میں اختلاف ہے، صحیح یہ ہے کہ ان کا نام عبد عمرو بن غنم، بقول بعض: سکین ہے۔ بغوی فرماتے ہیں: ہمیں محمد بن حمید نے ابو میلہ سے بحوالہ محمد بن عبید اللہ بتایا ان کا نام سعد بن حارث تھا۔ بغوی فرماتے ہیں: مجھے یہ بھی معلوم ہوا ہے کہ ان کا نام عبد یالیل تھا۔ ابن سعد ✳ بحوالہ واقدی: عبد شمس اور اسلام میں عبد اللہ نقل کرتے ہیں اور بہیثم سے یہی الفاظ منقول ہیں۔ بغوی نے یہ اضافہ نقل کیا ہے ان کا نام عبد اللہ بن عائذ تھا۔ ابن البرقی کا قول ہے: عبد الرحمن نام تھا، بقول بعض: عبد شمس / عبد غنم / عبد اللہ بلکہ عبد انہم ایک قول عبد تیم ہے۔ ابن مندہ ان کے ناموں میں عبد بغیر اضافت اور ان کے والد کا نام عبد غنم لکھتے ہیں۔ ابو نعیم اسے عبد العزی اور سکن روایت کرتے ہیں۔ نووی اپنی کسی کتاب میں لکھتے ہیں: ابو ہریرہ کا نام عبد الرحمن بن صحر تین اقوال میں سے سب سے زیادہ صحیح قول ہے۔ (یہ قول ریاض الصالحین میں ہے۔ [از عامر تقی ندوی]) قطب حلبی کا قول ہے: ان کے اور ان کے والد کے نام میں چوالیس (۴۴) اقوال ہیں جو حاکم کی الکنی، استیعاب اور تاریخ ابن عساکر میں مذکور ہیں۔\n(5) الطبقات الکبری (۵۲/۴)\n(6) صحیح میں اعرج سے مروی ہے کہ سیدنا ابو ہریرہ رضی اللہ عنہ نے فرمایا: تم لوگ کہتے ہو ابو ہریرہ رسول اللہ صلی اللہ علیہ وسلم سے بہت زیادہ احادیث کی روایت کرتا ہے، اللہ سے ڈرانے والا ہے، میں مسکین آدمی تھا جو خالی پیٹ رسول اللہ صلی اللہ علیہ وسلم کے پاس پڑا رہتا تھا مہاجرین بازار کی سودے بازی میں، اور انصار کو اپنے مال کی دیکھ بھال کی مشغولی نے اس سعادت سے محروم رکھا۔ میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"جو میری بات کہنے تک اپنی چادر پھیلائے بیٹھا رہے گا اور پھر اسے لپیٹ لے گا تو وہ کبھی میری بات نہیں بھولے گا۔ چنانچہ میں نے اپنی چادر بچھائی، آپ صلی اللہ علیہ وسلم نے اپنی بات مکمل کی پھر میں نے اسے لپیٹ لیا۔ اس ذات کی قسم جس کے قبضہ میں میری جان ہے! اس کے بعد آپ صلی اللہ علیہ وسلم سے سنی ہوئی بات کبھی نہیں بھولا۔ ✳ (مسند احمد، بخاری، مسلم، نسائی بطریق زہری بحوالہ اعرج اور بطریق زہری بحوالہ سعید بن المسیب و ابو سلمہ سیدنا ابو ہریرہ رضی اللہ عنہ سے ایک دوسرے کی روایت میں کمی زیادتی ہے)۔\n(7) بخاری کتاب العلم باب حفظ العلم (۱۱۸) کتاب الحرث والمزارعۃ باب ما جاء فی الفرس (۲۳۵۰) مسلم کتاب فضائل الصحابہ باب فضائل ابی ہریرۃ (۶۳۴۷) ابن ماجہ مقدمہ (۲۶۲) مسند احمد (۲۴۰/۲) (۲۷۴/۲)\n(8) ترمذی کتاب المناقب باب مناقب ابی ہریرہ (۳۸۳۶)\n(9) لقحہ دودھیا اونٹنی، زیر لفحہ ایک لغت ہے۔\n(10) میں کہتا ہوں: شاید یہ بات سابقہ اثر (قول صحابی) سے ماخوذ ہے کہ وہ عہد نبوی میں تیس (۳۰) سے کچھ اوپر برس کے تھے۔ ان کی وفات عقیق میں اپنے محل میں ہوئی، جنازہ مدینہ لایا گیا۔ ہشام بن عروہ، خلیفہ اور ایک جماعت کا کہنا ہے: ابو ہریرہ رضی اللہ عنہ کی وفات ۵۷ھ میں ہوئی۔ جبکہ ہیشم بن عدی، ابو معشر، ضمرہ بن ربیعہ کا قول ہے: ۵۸ھ میں فوت ہوئے۔ واقدی اور ابو عبید وغیرہ کا قول ہے: ۵۹ھ میں فوت ہوئے۔ واقدی نے یہ اضافہ بھی نقل کیا ہے انہوں نے رمضان ۵۸ھ میں سیدہ عائشہ رضی اللہ عنہا کا جنازہ پڑھایا اور شوال ۵۹ھ سیدہ ام سلمہ رضی اللہ عنہا کا جنازہ پڑھایا تھا، اس کے بعد خود فوت ہوئے۔ میں کہتا ہوں: ام سلمہ رضی اللہ عنہا کے جنازے کے بارے میں ان سے نادانستہ طور پر غلطی ہوئی، اگرچہ ایک جماعت نے ان کی اس بات پر متابعت کی ہے، کیونکہ صحیح میں جو روایت ہے اس سے پتہ چلتا ہے کہ ام سلمہ رضی اللہ عنہا خلافت یزید بن معاویہ تک حیات رہیں، جیسا کہ ان کے حالات میں بیان ہوگا۔ ابو ہریرہ رضی اللہ عنہ کی وفات کے بارے میں ہشام بن عروہ کا قول معتبر ہے۔ امام بخاری رحمہ اللہ کو اس میں تردد ہے، فرماتے ہیں: ۵۷ھ میں فوت ہوئے۔"}],[9282,"§۱۰۶۷۲ ۔ ابو ہلال الکلبی(1)(2)\nنبی صلی اللہ علیہ وسلم کے پاس آئے، ان کی حدیث علقمہ بن ہلال نے بحوالہ اپنے دادا روایت کی ہے۔ بقول بعض بواسطہ اپنے والد بحوالہ اپنے دادا روایت کی ہے ایسا ہی ابن مندہ نے مختصر ذکر کیا ہے۔ ابو نعیم لکھتے ہیں: ابو ہلال کلبی نبی صلی اللہ علیہ وسلم کے پاس آئے، ان کی حدیث ان کی اولاد سے مروی ہے، پھر بحوالہ طبرانی ان کی حدیث بیان کی جو بطریق ولید بن مسلم ہے کہ مجھ سے اس شخص نے بیان کیا جس نے علقمہ بن ہلال سے سنا جن کا تعلق بنی تیم اللہ سے ہے وہ بواسطہ اپنے والد بحوالہ اپنے دادا روایت کرتے ہیں کہ وہ اپنی قوم کے ساتھ نبی صلی اللہ علیہ وسلم کے پاس حاضر ہوئے، ان دنوں آپ صلی اللہ علیہ وسلم نے مدینہ کی طرف ہجرت کی تھی۔ فرماتے ہیں: ہم پہنچے تو آپ صلی اللہ علیہ وسلم تھوڑے پانی کے پاس قیدیوں کی گردنیں اتروا رہے تھے۔ خون سے پانی پر تہ جم گئی۔ ابو موسیٰ فرماتے ہیں: یحیی بن مندہ نے اپنے دادا کی کتاب پر اپنے استدراک میں ان کا ذکر کیا ہے، تو لکھا ہے: ابو ہلال تیمی، ان کے دادا نے ان کا ذکر کیا ہے لیکن ان کی سند سے کچھ بیان نہیں کیا۔ ابن الاثیر لکھتے ہیں: تیمی اور کلبی ایک ہے، کیونکہ تیم اللہ کلب کا بہت بڑا بطن ہے وہ تیم اللات بن رفیدہ بن ثور بن کلب بن وبرہ ہے۔","",{"fn":"(1) اسد الغابہ (۶۳۲۰) تجرید (۲۰۹/۲)\n(2) المعجم الکبیر (۹۴۸/۲۲) اسد الغابہ (۱۲۲/۵)"}],[9283,"§۱۰۶۷۳ ۔ ابو ہند(1)\nنعیم بن ابی ہند اشجعی کے والد، نعمان بن اشیم میں ان کا تذکرہ ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۶۳۲۱) استیعاب (۳۲۵۴) تجرید (۲۱۰/۲)"}],[9284,"§۱۰۶۷۴ ۔ ابو ہند الحجام(1)\nمولا بنی بیاضہ۔ بقول ابن السکن، کسی کا کہنا ہے: ان کا نام عبد اللہ ہے۔ ابن مندہ لکھتے ہیں، بقول بعض: ان کا نام سیار ہے یا سالم، فرماتے ہیں: ابن اسحاق کا قول ہے: یہ فروہ بن عمرو بیاضی جن کا تعلق انصار سے ہے ان کے مولا ہیں۔ ان سے ابن عباس، جابر، ابو ہریرہ رضی اللہ عنہم نے روایت کی ہے۔ موطا ابن وہب میں لکھا ہے ابو ہند نے نبی کریم صلی اللہ علیہ وسلم کے سینگی لگائی۔ مغازی میں ابن اسحاق بھی فرماتے ہیں: بدر سے واپسی کے بعد جب رسول اللہ صلی اللہ علیہ وسلم عرق الظبیہ مقام پر پہنچے تو سامنے سے ابو ہند آ گئے جو فروہ بن عمرو بیاضی کے مولا تھے، ان کے پاس کھجور کا حلوہ تھا۔ بدر میں شرکت نہ کر سکے تھے اس کے علاوہ معرکوں میں شریک رہے۔ ابن مندہ کی بحوالہ زہری روایت ہے کہ جابر بیان کرتے تھے، رسول اللہ صلی اللہ علیہ وسلم زہریلی بکری جو آپ نے کھائی تھی کی وجہ سے اپنے کندھے پر سینگی لگواتے جو ابو ہند مولا بنی بیاضہ نے سینگ سے لگائی۔ ابو نعیم کی روایت ہے سیدنا ابو ہریرہ رضی اللہ عنہ فرماتے ہیں: ابو ہند نے رسول اللہ صلی اللہ علیہ وسلم کو درد کی وجہ سے تالو پر سینگی لگائی۔ اور آپ صلی اللہ علیہ وسلم نے فرمایا: دوا دارو کی بہترین چیز حجامت (سینگی اور پچھنے لگوانا) ہے۔ دراوردی نے ان کے خلاف روایت کی ہے۔ محمد بن عمرو، ابو سلمہ سے بحوالہ ابو ہند روایت کرتے ہیں، فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو اوپر سینگی لگائی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: اگر علاج معالجہ میں کوئی بہتر طریقہ ہے تو وہ حجامت و سینگی لگوانا ہے۔ اے بنی بیاضہ! ابو ہند کا نکاح کرا دو اور اس سے رشتہ ناتا رکھو۔(2) یہی روایت ابن جریج، اور حاکم نے ان سے نقل کی ہے۔ حاکم نے الاکلیل میں لکھا ہے انہوں نے عمر بھر انہیں رسول اللہ صلی اللہ علیہ وسلم کا سر مونڈا تھا۔ ابن السکن اور طبرانی بطریق زہری عروہ سے بحوالہ سیدہ عائشہ رضی اللہ عنہا روایت کرتے ہیں، ابو ہند مولا بنی بیاضہ سینگی لگانے کا کام کرتے تھے۔ رسول اللہ صلی اللہ علیہ وسلم کو سینگی لگاتے تھے۔ آپ صلی اللہ علیہ وسلم نے ارشاد فرمایا: جو شخص یہ چاہے کہ وہ اس شخص کو دیکھے جس کے دل میں اللہ تعالیٰ نے ایمان کو صورت دی ہے وہ ابو ہند کو دیکھ لے، اور فرمایا: اس کا نکاح کرو اور اس سے رشتہ ناتا رکھو۔ زہری تک اس کی سند ضعیف ہے۔ حاکم نے اسے مختصر نقل کیا ہے اس میں یہ اضافہ ہے یہ آیت نازل ہوئی: لوگو! ہم نے تم کو ایک مرد اور ایک عورت (کے ملاپ) سے پیدا کیا ہے۔(3) واقدی نے کتاب الردہ میں فرمایا ہے، زرعہ بن عبد اللہ بن زیاد بن لبید سے مروی ہے کہ سیدنا ابو بکر الصدیق رضی اللہ عنہ نے ابو ہند مولا بنی بیاضہ کو زیاد بن لبید گورنر کندہ اور حضرموت کے پاس روانہ کیا، تا کہ انہیں بتائیں کہ نبی صلی اللہ علیہ وسلم کے بعد ابو بکر خلیفہ بنے ہیں۔","",{"fn":"(1) اسد الغابہ (۶۳۲۲) استیعاب (۳۲۵۳) تجرید (۲۱۰/۲)\n(2) ابوداؤد کتاب النکاح باب الاکفاء (۲۱۰۲) المستدرک (۱۶۴/۲) السنن الکبری للبیہقی (۱۳۶/۷)\n(3) سورۃ الحجرات (۱۳) اسد الغابہ (۶۳۲۲) استیعاب (۳۲۵۶) تجرید (۲۱۰/۲)"}],[9285,"§۱۰۶۷۵ ۔ ابو ہند الداری(1)\nاز بنی الدار بن ہانی بن حبیب۔ کنیت سے مشہور ہیں، نام میں اختلاف ہے۔ بریر یا بر بن عبد اللہ بن ربیعہ بن دراع بن عدی بن الدار، تمیم الداری کے چچا زاد بھائی۔ بقول ابن حبان صحیح یہ ہے کہ ان کا نام بر بن بز یا بریر یا برین ہے۔ میں نے ابن الحذاء اندلسی کی کتاب رجال المؤطا میں تمیم داری کے حالات میں لکھا دیکھا ہے کہ ابو ہند تمیم کے بھائی نہیں، کیونکہ ابو ہند وہ لیث بن عبد اللہ بن رزین ہیں۔ معتبر نسخہ میں ایسا ہی لکھا ہے، مجھے معلوم نہیں آیا وہ یہی ہیں یا نہیں؟ ابو عمر فرماتے ہیں: بقول بعض: ان کے سگے بھائی نہیں ہیں بلکہ ماں شریک بھائی اور چچا زاد ہیں۔ ابو نعیم لکھتے ہیں: تمیم کے بھائی ہیں، تمیم کے ساتھ نبی صلی اللہ علیہ وسلم کے پاس آئے۔ ان لوگوں نے آپ صلی اللہ علیہ وسلم سے درخواست کی کہ انہیں شام میں جائیداد دیں۔ تو آپ صلی اللہ علیہ وسلم نے دونوں کے لیے یہ پروانہ لکھوا دیا۔ جب سیدنا ابو بکر رضی اللہ عنہ کا دور آیا تو وہ تحریر لے کر ان کے پاس آئے۔ آپ نے ابو عبیدہ رضی اللہ عنہ کو لکھا کہ اس حکم پر عمل کیا جائے۔ میں کہتا ہوں: وہ تحریر تمیم کی اولاد میں اب تک مشہور ہے۔ میں نے اس کے متعلق البناء الجلیل بحکم بلد الخلیل نامی ایک رسالہ بھی دیکھا ہے۔ بقول ابو عمر: اہل شام میں شمار ہوتے ہیں، ان کی اولاد سے ان کی حدیث مروی ہے۔ میں کہتا ہوں: ابو نعیم وغیرہ نے بحوالہ ابو ہند روایت کی ہے، فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا، اللہ تعالیٰ فرماتے ہیں: جو میرے فیصلے پر راضی نہیں اور میری آزمائش پر صابر نہیں اسے چاہیے کہ مجھے چھوڑ کر کوئی اور رب تلاش کر لے (اگر اسے ملتا ہے، جو محال ہے) زیاد اور فائد دونوں باپ بیٹا ضعیف ہیں۔ دونوں سے بہت سی منکر احادیث مروی ہیں۔ حارث بن ابی اسامہ نے اپنی مسند میں بطریق مکحول روایت کی ہے میں نے ابو ہند الداری کو فرماتے سنا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: جو شخص اپنے (مسلمان) بھائی کے مقابلہ میں اپنی عزت دکھانا چاہے اور اپنے متعلق باتیں سننا چاہے قیامت کے روز اللہ تعالیٰ اس سے بدلہ لے گا۔","",{"fn":"(1) المعجم الکبیر (۸۰۷/۲۲) مجمع الزوائد (۲۰۷/۷) اسد الغابہ (۱۲۳/۵)"}],[9286,"§۱۰۶۷۶ ۔ ابو ہند (مولا النبی صلی اللہ علیہ وسلم)\nمحمد بن حبیب نے کتاب المحبر میں ان کا ذکر کیا ہے۔"],[9287,"§۱۰۶۷۷ ۔ ابو ہنیدہ\nوائل بن حجر الحضرمی، ناموں میں تذکرہ ہوا ہے۔ الکنی میں ابو احمد نے بطریق محمد بن حجر روایت کی ہے میں نے اپنے والدہ چچا کو فرماتے سنا: ہمارے گھرانے کے لوگ کہتے ہیں: وائل بن حجر کی کنیت ابو ہنیدہ تھی اور محمد بن حجر نے شاعر کا یہ شعر پڑھا: اغر ابو ہنیدہ نے تعلقات اور کشادہ گھر دے کر مجھ سے محبت نبھائی۔"],[9288,"§۱۰۶۷۸ ۔ ابو ہود\nسعید بن بربوع مخزومی، ناموں میں تذکرہ گزر چکا ہے۔"],[9289,"§۱۰۶۷۹ ۔ ابو الہیثم\nعباس بن مرداس۔ امام بخاری رحمہ اللہ نے الکنی المجردة میں ان کی یہ کنیت لکھی ہے۔ ابو احمد کا قول ہے: ناموں میں ان کا ذکر ہوا ہے۔"],[9290,"§۱۰۶۸۰ ۔ ابو الہیثم بن التیہان\nابن مالک بن عتیک بن عمرو بن عبد الاعلم بن عامر بن زعوراء انصاری اوسی۔ زعوراء عبد الاشہل کے بھائی ہیں۔ بقول بعض تیہان لقب ہے اور نام مالک ہے، کنیت سے مشہور ہیں۔ المصنف عبد الرزاق میں لکھا ہے ان کا نام عبد اللہ ہے۔ ابن اسحاق(1) شرکاء بدر میں فرماتے ہیں: ابو الہیثم جن کا نام مالک ہے اور ان کے بھائی تیہک دونوں تیہان کے بیٹے ہیں، اور بیعۃ العقبہ فرماتے ہیں: بنی عبد الاشہل کے نقیب اسید بن حضیر اور ابو الہیثم بن تیہان تھے۔ ابن السکن کا قول ہے: ابن اسحاق(2) کا بیان ابو الہیثم کا تعلق بنی عمرو بن الحاف بن قضاعہ سے بنی عبد الاشہل کے حلیف ہیں۔ نبی صلی اللہ علیہ وسلم نے ان میں اور عثمان بن مظعون رضی اللہ عنہ کے درمیان مواخات قائم کی۔ تمام معرکوں میں شریک رہے۔ یہی موسیٰ بن عقبہ کا بحوالہ ابن شہاب شرکاء بدر و بیعت عقبہ کے بارے میں ہے۔ سب سے پہلے انہوں نے بیعت کی۔ ابن السکن فرماتے ہیں: سیدنا ابو ہریرہ رضی اللہ عنہ نے ابو الہیثم بن تیہان کا واقعہ نقل کرتے ہے، جب انہیں رسول اللہ ابو بکر اور عمر رضی اللہ عنہم نے دیکھا تھا۔ ایسا ہی عکرمہ سے بحوالہ ابن عباس رضی اللہ عنہما یہ واقعہ طویل منقول ہے جس میں سے بعض نے مختصر حدیث نقل کی ہے: جس سے مشورہ لیا جائے وہ امانت دار ہے۔ جو ابو الہیثم سے مسنداً بیان کی ہے۔ ان سے ایک اور حدیث مروی ہے پھر بحوالہ مالک بن تیہان یہ روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے السلام علیکم کہا اس کے لیے نیکیاں لکھی جائیں گی، اور جس نے السلام علیکم و رحمۃ اللہ کہا اس کے لیے بیس(۲۰) نیکیاں لکھی جائیں گی اور جس نے السلام علیکم و رحمۃ اللہ و برکاتہ کہا اس کے لیے تیس(۳۰) لکھی جائیں گی۔ فرماتے ہیں: ابو الہیثم سے مروی تمام روایات قابل نظر ہیں۔ کسی سند سے کوئی روایت ثابت نہیں۔ کیونکہ ان کی وفات بہت پہلے ہوگئی تھی۔ بقول بعض: ۲۰ھ میں فوت ہوئے۔ ایک قول ہے: صفین میں ۳۷ھ میں فوت ہوئے۔ ابو عمر اصمعی سے نقل کرتے ہیں، فرمایا: میں نے ابو الہیثم کی قوم سے پوچھا، انہوں نے بتایا: ان کا انتقال نبی صلی اللہ علیہ وسلم کی حیات میں ہوا تھا۔ فرماتے ہیں: اس قائل کی کسی نے متابعت نہیں کی۔ لکھتے ہیں، بقول بعض: ان کا انتقال ۲۱ھ میں ہوا۔ بقول بعض بلکہ اکثریت کا یہ قول ہے کہ جنگ صفین میں سیدنا علی رضی اللہ عنہ کا ساتھ دیا۔ ایک قول ہے: اسی میں شہید ہوئے۔ یہ قول ابو بشر دولابی نے بطریق صالح بن الوجیہ نقل کیا ہے کہ صفین میں شہید ہونے والوں میں ابو الہیثم بن التیہان اور عبد الرحمن بن بدیل وغیرہ ہیں۔ پھر ابو عمر سند کے ساتھ بطریق ابو نعیم فضل بن دکین روایت کرتے ہیں کہ ابو الہیثم سیدنا علی رضی اللہ عنہ کا ساتھ دیتے شہید ہوئے۔ حاکم فرماتے ہیں، بقول بعض: عہد نبوی میں فوت ہوئے۔ بعض نے کہا: ۲۰ھ میں بعض نے ۲۱ھ میں کسی نے کہا: صفین میں شریک ہوئے۔ زیادہ درست قول یہی ہے کہ ۲۰ھ یا ۲۱ھ میں فوت ہوئے۔ امام واقدی رحمہ اللہ فرماتے ہیں: مجھے معلوم نہیں کہ کوئی اس صفین میں ان کی شہادت سے خبر دار ہو۔ ۲۰ھ والا قول ابن ابی خیثمہ نے صالح بن کیسان سے بحوالہ زہری نقل کیا ہے۔ ابو ربیع بن سالم کلائی نے نبی صلی اللہ علیہ وسلم کی وفات کے موقع پہ ابو الہیثم کا مرثیہ پڑھا ہے: جس صبح ہمیں حضور محمد نبی کریم صلی اللہ علیہ وسلم کی وفات کی خبر سنائی گئی تو ہماری ناکیں اور کان کٹ کے رہ گئے۔","",{"fn":"(1) اسد الغابہ (۶۳۲۴) تجرید (۲۱۰/۲)\n(2) السیرۃ النبویہ (۶۵/۲) ایضاً"}],[9291,"§۱۰۶۸۱ ۔ ابو الہیثم(1)(2)\nدوسرے ہیں۔ ابو موسیٰ نے ذیل میں ان کا ابن تیہان سے علیحدہ ذکر کیا ہے جو درست اقدام ہے۔ اور بطریق طبرانی ولید بن مسلم تک ان کی سند سے بواسطہ ابن لہیعہ، بکر بن سوادہ سے بحوالہ ابو الہیثم روایت کی ہے، فرمایا: مجھے رسول اللہ صلی اللہ علیہ وسلم نے وضو کرتے دیکھا تو فرمایا: \"ابو الہیثم! پاؤں کا تلوا دھیان سے دھونا! (خشک نہ رہ جائے)\" کسی مسند والے نے یہ حدیث مسند ابو الہیثم بن التیہان میں درج کر دی ہے جو بہتر نہیں، اس واسطے کہ بکر بن سوادہ نے ان کا دور نہیں پایا ہے جس سے معلوم ہوا یہ اور ہیں۔","",{"fn":"(1) اسد الغابہ (۶۳۲۵) تجرید (۲۱۰/۲)\n(2) المعجم الکبیر (۹۱۱/۲۲) مجمع الزوائد (۲۳۰/۱) جامع المسانید (۷۱۷/۱۴) اسد الغابہ (۱۲۳/۵)"}],[9292,"§۱۰۶۸۲ ۔ ابو الہیثم بن عقبہ بن ابی لہب بن عبد المطلب بن ہاشم ہاشمی\nایک حدیث میں ان کا ذکر آتا ہے جس سے ان کا صحابی ہونا معلوم ہوتا ہے، چنانچہ میں ابو الحسن بن السری، جو ابن السنی کی اولاد کے ماموں ہیں، کی کتاب السنتہ میں پڑھا محمد بن صالح، مروان بن ضرار فزاری، عبد الرحمن بن الحکم بن البراء بن قبیصہ ثقفی، ان کے سلسلہ سند سے منقول ہے، فرمایا: ہم سے ابی نے بواسطہ عامر بن الاسود بحوالہ عبد اللہ بن الغسیل روایت کی ہے، فرمایا: میں نبی صلی اللہ علیہ وسلم کے ساتھ تھا، آپ صلی اللہ علیہ وسلم عباس کے پاس سے گزرے، فرمانے لگے: چچا جان! اپنے بیٹے میرے ساتھ بھیجو، تو ابو الہیثم بن عقبہ بن ابی لہب نے کہا: چچا جان! میرے آنے تک ٹھہرئیے لیکن وہ نہ آئے تو سیدنا عباس رضی اللہ عنہ اپنے چھ(۶) بیٹوں کو لے کر روانہ ہو گئے۔ پھر ایک واقعہ نقل کیا۔"],[9293,"§۱۰۶۸۳ ۔ ابو الہیثم (جنات میں سے ایک)\nشلبی نے آکام المرجان میں لکھا ہے کہ مدینہ میں ایک شخص آیا جس نے ابو موسیٰ اشعری کے بارے میں کوئی بات بیان کی جو پھیل گئی لیکن کوئی اس شخص کو نہ پہچان سکا۔ سیدنا عمر رضی اللہ عنہ تک بات پہنچی، آپ رضی اللہ عنہ نے فرمایا: یہ جنات میں سے ابو الہیثم تھا جو مسلمانوں کا جنات کی طرف سے قاصد ہے۔ عنقریب انسانوں کا قاصد بیان ہوگا، اس کے کچھ دن بعد وہ آ گیا۔"],[9294,"§۱۰۶۸۴ ۔ ابو ہیصم مزنی\nابن زبالہ کی اخبار مدینہ نامی کتاب میں ان کا ذکر ہوتا ہے۔ زبیر بن بکار کا قول ہے: ابو ہیصم مزنی سے بحوالہ ان کے والد منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں بلا کر فرمایا: میں تمہیں اس وادی پر مقرر کرنے والا ہوں جو تمہارے پاس ادھر یا ادھر سے آنا چاہے اس (کی سواری) کو روک دینا۔ انہوں نے عرض کی: میں صرف بیٹیوں والا ہوں میرا کوئی (مرد) معاون نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: عنقریب اللہ تعالیٰ تجھے بیٹے سے نوازے گا اور تمہارے وارث بنائے گا۔ فرماتے ہیں: وہ اس پر مقرر ہو گئے، بعد میں ان کے بیٹا ہوا۔ پھر حکمران اس پر مقرر کرنے لگے۔ اسی سند سے محمد بن ہیصم تک منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے بقیع کے درمیان میں چڑھ کر نماز پڑھی۔"],[9295,"§۱۰۶۸۵ ۔ ابو ہارون\nمسعود بن الحکم الزرقی، ناموں میں تذکرہ ہوا ہے۔"],[9296,"§۱۰۶۸۶ ۔ ابو ہاشم بن مسعود\nبن سنان بن ابی حارثہ المزنی، دور نبوی پایا ہے۔ ابراہیم بن محمد بن زیاد بن سوید بن ابی ہاشم ان کی اولاد سے ہے، وہی اس شعر کے قائل ہیں: \"تم نے جب بھی کوئی کام کیا تو تمہارے دونوں حالوں میں سے تمہارے پاس وہی ہے جو میرے پاس ہے\"۔"],[9297,"§۱۰۶۸۷ ۔ ابو ہاشم (مولا رسول اللہ صلی اللہ علیہ وسلم)(1)\nتابعی ہیں، مرسل حدیث ذکر کی ہے جس کی وجہ سے ابو موسیٰ نے \"ذیل علی المعرفة\" میں ان کا ذکر کر دیا اور بطریق ابو نعیم غالباً ان کی کتاب فضائل الصحابہ میں بطریق یحیی بن یعلی بواسطہ ابو عبد الرحمن حلو بن السری ازدی بحوالہ ابو ہاشم مولا رسول اللہ صلی اللہ علیہ وسلم روایت کی ہے۔ فرماتے ہیں: میری والدہ رسول اللہ صلی اللہ علیہ وسلم کی باندی تھیں، آپ صلی اللہ علیہ وسلم نے میرے والدین کو آزاد کیا تھا کہ رسول اللہ صلی اللہ علیہ وسلم مسجد سے تشریف لائے تو اپنی بیٹی کے گھر گئے تو وہ لوگ قیلولہ کر رہے تھے، ان پر دھوپ پڑ رہی تھی، آپ صلی اللہ علیہ وسلم ان کے سرہانے کھڑے ہو گئے، آپ کی یہ تم پر خیبر کی چادر تھی ان کے آگے چادر پھیلا کر فرمایا: اے دیہات اور شہر کے پسندیدہ دونوں کھڑے ہو جاؤ۔ تین بار ایسا فرمایا(2) اور بطریق عبد اللہ بن موسیٰ، حلو الازدی، بواسطہ ابو ہاشم بحوالہ ان کے والد جو مولا رسول اللہ صلی اللہ علیہ وسلم تھے، فرمایا: رسول اللہ صلی اللہ علیہ وسلم ایک غزوہ پر روانہ ہوئے، پھر لمبی حدیث ذکر کی۔ ابو موسیٰ فرماتے ہیں: اس سے معلوم ہوا یہ حدیث ابو ہاشم کے والد کی ہے جو بیٹی بن یعلی سے مروی ہے، فرمایا: عن حلو عن ابی ھاشم عن ابیہ۔","",{"fn":"(1) اسد الغابہ (۶۳۱۴) تجرید (۲۰۹/۲)\n(2) جامع المسانید (۷۱۱/۱۴) اسد الغابہ (۱۱۸/۵) تجرید (۲۱۰/۲)"}],[9298,"§۱۰۶۸۸ ۔ ابو ہاشم نافع\nبقول امام مسلم: نام عمر ہے ان سے ان کا بیٹا عبد اللہ روایت کرتا ہے۔ جبکہ امام بخاری رحمہ اللہ فرماتے ہیں: نافع مولا بنی ہاشم نے سیدنا عمر رضی اللہ عنہ سے سماع کیا ہے، یہ حکم بن عیینہ کا بواسطہ ابن قانع بحوالہ ان کے والد نقل کردہ قول ہے جسے حاکم نے نقل کیا ہے۔ پھر فرمایا: محمد بن اسماعیل کی بات دل کو لگتی ہے۔ میں کہتا ہوں: گویا وہ سمجھے کہ امام مسلم کا قول \"ابو ہاشم\" لفظی غلطی ہے۔ اصل میں بنی ہاشم تھا، اگر ایسا ہی ہے جیسا امام مسلم رحمہ اللہ کے ہاں لکھا ہے تو پھر یہ قسم ثالث سے تعلق رکھتے ہیں۔ واللہ اعلم!"],[9299,"§۱۰۶۸۹ ۔ ابو ہند انصاری\nابن مندہ نے انہیں بیاضی سے علیحدہ ذکر کیا ہے، جبکہ دونوں ایک ہیں۔ ابن مندہ کہتے ہیں: حجاج نے ابن جریج سے بواسطہ ابو زبیر بحوالہ جابر روایت کی جس میں انہیں وہم ہوا۔ جبکہ ابو زبیر کے شاگردوں نے ابو زبیر سے بحوالہ جابر نقل کیا ہے کہ ابو حمید نبی صلی اللہ علیہ وسلم کے پاس ایک برتن لے کر آئے۔ یہی درست ہے۔ ابن مندہ کا میلان اس طرف ہے کہ ابو حمید سے لفظی غلطی ہے۔ اور ابن السکن نے ان کا تذکرہ ابو ہند بیاضی کے حالات میں کر کے درست اقدام کیا ہے۔ اور ساتھ خبر دار بھی کیا ہے کہ محفوظ حدیث ابو حمید کے حوالہ سے ہے۔ دونوں تقدیروں کے باوجود انہیں زائد شمار کرنا غلط ہے۔ ابن السکن نے اسے بیان کیا ہے جو بروایت زیاد بن ایوب عن حجاج ہے، پھر فرمایا بقول بعض: یہ غلط ہے، کیونکہ زکریا بن اسحاق نے اسے ابو زبیر سے بواسطہ جابر بحوالہ ابو حمید نقل کیا ہے۔ اسی طرح اعمش نے یہ روایت ابو سفیان سے بواسطہ جابر بحوالہ ابو حمید نقل کی ہے۔"],[9300,"§۱۰۶۹۰ ۔ ابو ہند البجلی\nشامی تابعی ہیں۔ کوئی ایک روایت مرسلا نقل کی ہے جس کی وجہ سے عسکری نے صحابہ رضی اللہ عنہم میں ان کا تذکرہ کر دیا ہے۔ عبد الحق الاحکام میں لکھتے ہیں: مشہور ہیں۔ ان سے عبد الرحمن بن ابی عوف روایت کرتے ہیں، ان کی حدیث ابو داؤد اور نسائی میں ہے۔"],[9301,"§۱۰۶۹۱ ۔ ابو واثلہ الہذلی(1)\nبقول ابن عساکر: صحابی ہیں۔ فتوحات شام میں شریک ہوئے۔ امام احمد رحمہ اللہ نے اپنی مسند میں ان کی حدیث بطریق ابن اسحاق روایت کی ہے۔ ابان بن صالح، شہر بن حوشب سے بحوالہ ان کی قوم کے ایک آدمی روایت کی ہے کہ انہوں نے اپنے والد کے بعد اپنی والدہ سے شادی کر لی، طاعون عمواس میں شریک تھے۔ فرماتے ہیں: جب بیماری نے شدت اختیار کی تو ابو عبیدہ کھڑے ہو کر ان کی وفات کی اور پھر معاذ بن جبل کی وفات کی خبر سنائی۔ ان کے بیٹے عبد الرحمن نے موصولاً ذکر کی ہے۔ پھر عمرو بن عاص رضی اللہ عنہ فی الفتنہ کھڑے ہوئے، اور فرمایا: اس بیماری کی وجہ سے پہاڑوں میں چھپ جاؤ۔ تو ابو واثلہ ہذلی نے ان سے کہا: اللہ کی قسم! تم غلط کہتے ہو! میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ رہا، تم تو میرے اس گدھے سے بھی برے ہو۔ انہوں نے فرمایا: اللہ کی قسم! میں تمہاری بات کی تردید نہیں کر رہا۔ پھر وہاں سے نکلے اور لوگ بھی نکل کر ادھر اُدھر پھیل گئے۔ اللہ تعالیٰ نے ان سے یہ بیماری ہٹائی۔(2) ابن عساکر لکھتے ہیں: مجھے صرف اس روایت سے ان کا علم ہوا ہے یہی واقعہ دوسری سند سے منقول ہے جو مفہوم کے اعتبار سے شرحبیل بن حسنہ کی طرف منسوب ہے شاید کئی لوگوں نے سیدنا عمرو کی تردید کی ہو۔ واللہ اعلم!","",{"fn":"(1) اسد الغابہ (۶۳۲۶) تجرید (۲۱۰/۲)\n(2) مسند احمد (۱۹۶/۱)"}],[9302,"§۱۰۶۹۲ ۔ ابو واقد لیثی(1)\nنام میں اختلاف ہے، حارث بن مالک / ابن عوف / عوف بن حارث بن اسید بن جابر بن عبد مناۃ بن شجیع بن عامر بن لیث بن بکر بن عبد مناۃ بن علی بن کنانہ۔ بنی اسد کے حلیف تھے۔ بقول امام بخاری، ابن حبان، حاکم اور باوردی: بدر میں شریک ہوئے۔ ابو عمر فرماتے ہیں: بقول بعض بدر میں شریک رہے جس کا ثبوت نہیں۔ ابن سعد فرماتے ہیں: بہت پہلے اسلام لے آئے تھے، فتح مکہ اور حنین میں بنی لیث، ضمرہ اور سعد بن بکر کے پرچم بردار تھے۔ اور غزوہ تبوک میں بنی لیث کو جنگ میں شرکت کی ترغیب دی۔ مکہ گئے تھے وہاں سال بھر مقیم رہے اور پھر وفات پا گئے۔ دوسرے مقام پر لکھتے ہیں: مقبرہ مہاجرین میں دفن ہوئے۔ روایت حدیث نبی صلی اللہ علیہ وسلم، سیدنا ابو بکر، عمر اور اسماء رضی اللہ عنہا بنت ابی بکر سے روایت کی ہے ان سے ان کے دونوں بیٹے عبد الملک اور واقد، ابو سعید خدری، عطاء بن یسار اور عروہ وغیرہ روایت کرتے ہیں۔ اہل مدینہ میں شمار ہوتے ہیں۔ ابو نعیم اس شخص پر اعتراض کیا ہے جو اس بات کا قائل ہے کہ یہ بدر میں شریک ہوئے تھے۔ وہ لکھتے ہیں: فتح مکہ کے سال یا اس سے پہلے مسلمان ہوئے اور وہ خود بتاتے ہیں: ہم حنین میں شریک تھے اور تازہ تازہ کفر کو خیر باد کہا ہوا تھا۔ زہری رحمہ اللہ نے صراحت کی ہے کہ فتح مکہ کے روز اسلام، جسے سنان بن ابی سنان دیلی سے مسنداً بیان کیا ہے اور ابن مندہ نے اسے زہری تک کی صحیح سند کے ذریعہ نقل کیا ہے جو ان کے بدر میں شریک ہونے کا قائل ہے، اس کی دلیل وہ روایت ہے جو یونس بن بکیر نے مغازی ابن اسحاق بحوالہ ان کے بواسطہ اپنے والد نقل کی ہے کہ بنی مازن کے لوگ بحوالہ ابو واقد روایت کرتے ہیں، انہوں نے فرمایا: بدر کے روز میں ایک مشرک کو اپنی تلوار سے قتل کرنے کے درپے تھا کہ اس تک میری تلوار پہنچنے سے پہلے ہی اس کا سر قلم ہو گیا۔ میں سمجھا کہ میرے علاوہ کسی نے اسے قتل کر دیا ہے۔ اسی طرح واقدی کی روایت اس سے ٹکراتی ہے جو کہتا ہے: وہ بدر میں شریک ہوئے تھے۔ ان کا انتقال ۶۸ھ پچھتر(۷۵) برس کی عمر میں ہوا، جس کا تقاضا ہے ان کی ولادت معرکہ بدر کے بعد ہوئی۔ اس لحاظ سے وہ بدر میں بارہ سال کے ہوں گے، اسی پر ابو حسان زیادی کا قول منطبق (فٹ) آتا ہے کہ یہ اسی سال پیدا ہوئے جس سال ابن عباس رضی اللہ عنہما کی ولادت ہوئی۔ ابو عمر نے واقدی کے قول کی موافقت کی ہے، پھر لکھتے ہیں: بقول بعض ۸۵ھ میں فوت ہوئے۔ اس آخری قول پر بغوی وغیرہ نے اعتماد کیا ہے۔ امام بخاری یہ فرماتے ہیں: خلافت معاویہ میں فوت ہوئے۔ امام بخاری رحمہ اللہ نے اسحاق مولا محمد بن زیاد سے صحیح سند کے ذریعہ روایت کی ہے کہ انہوں نے ابو واقد کو فرماتے سنا: یرموک میں میں نے دشمن کا ایک شخص گر کر مرتے دیکھا۔ یہ روایت خلیفہ نے اسی سند سے نقل کی ہے۔ انہوں نے لکھا: اسحاق مولا زائدہ، اس کے آخر میں یہ اضافہ نقل کیا ہے۔ میں دل میں کہنے لگا: اگر میں انہیں چادر کے پلو سے بھی مارتا تو وہ مر جاتے۔ ابن عساکر رحمہ اللہ یہ فرماتے ہیں: مسند ابن اسحاق میں غیر معروف راوی ہیں۔ صحیح بات وہی جو زہری بحوالہ سنان بیان کی ہے۔ ابن اسحاق نے جو قصہ ابو واقد کا بیان کیا ہے وہ یرموک کے روز پیش آیا جیسا کہ پہلے بیان ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۶۳۲۷) تجرید (۲۱۰/۲)"}],[9303,"§۱۰۶۹۳ ۔ ابو واقد(1) (مولا النبی صلی اللہ علیہ وسلم)\nابن مندہ نے ان کا ذکر کیا ہے کہ ان سے زاذان بن عمر نے روایت کی ہے۔ پھر بواسطہ زاذان بحوالہ ان کے مرفوع روایت کی ہے: جس نے اللہ کی اطاعت کی اس نے اللہ کا ذکر کیا اگرچہ وہ بکثرت نماز پڑھتا، روزے رکھتا اور قرآن کی تلاوت کرتا ہو۔ ...... (حدیث)(2)","",{"fn":"(1) اسد الغابہ (۶۳۲۸) تجرید (۲۱۰/۲)\n(2) مجمع الزوائد (۲۵۸/۲) جامع المسانید (۷۲۸/۱۴) تجرید (۱۷۳)"}],[9304,"§۱۰۶۹۴ ۔ ابو واقد(1)\nذہبی لکھتے ہیں ممکن ہے وہ ہوں جن کے متعلق امام بخاری رحمہ اللہ نے کہا ہے بدر میں شریک ہوئے اور لیثی کے علاوہ کوئی صاحب ہیں۔","",{"fn":"(1) اسد الغابہ (۶۳۲۹) تجرید (۲۱۰/۲)"}],[9305,"§۱۰۶۹۵ ۔ ابو واقد نمیری(1)\nابن شاہین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور بطریق ابن فیہم بواسطہ نافع بن سرجس بحوالہ ابو واقد نمیری روایت کی ہے کہ \"رسول اللہ صلی اللہ علیہ وسلم لوگوں کو بہت کم دعا سے نوازتے اور اپنے اوپر ہمیشہ درود بھیجتے تھے۔\"(2)","",{"fn":"(1) مسند احمد (۲۱۹/۵)\n(2) المعجم الکبیر (۳۳۱۲/۳) جامع المسانید (۷۲۵/۱۴)"}],[9306,"§۱۰۶۹۶ ۔ ابو وحوح انصاری(1)\nبغوی نے ان کا ذکر کیا اور بطریق ابن لہیعہ، حارث بن یعقوب سے بواسطہ ابو شعیب مولا ابو وحوح روایت کی ہے کہ ہم نے ایک میت کو غسل دیا، اتنے میں ابو وحوح انصاری صحابی رسول اللہ صلی اللہ علیہ وسلم آ گئے۔ انہوں نے بغلوں تک کپڑا ہٹایا ہوا تھا اور اسے ظاہر کر رہے تھے۔ فرمانے لگے: \"اللہ کی قسم! ہم (مسلمان) زندہ ہوں یا مردہ نجس نہیں ہوتے، اللہ کی قسم! مجھے خدشہ ہے یہ کام (میت کو غسل دینے کے بعد غسل کرنا) سنت نہ ہو جائے۔\"(2)","",{"fn":"(1) اسد الغابہ (۶۳۳۱) تجرید (۲۱۱/۲)\n(2) اسد الغابہ (۱۲۵/۵)"}],[9307,"§۱۰۶۹۷ ۔ ابو وداعہ السہمی(1)\nنام حارث بن صبرہ ہے یہ اور ان کا بیٹا مطلب فتح مکہ کے موقعہ پر مسلمان ہوئے۔ ابن عبد البر نے فرمایا: اور ابن مندہ نے سنداً بحوالہ ابو وداعہ سہمی روایت کی ہے، فرمایا: \"میں نے رسول اللہ صلی اللہ علیہ وسلم کو باب بنی ہم میں نماز پڑھتے دیکھا لوگ آپ صلی اللہ علیہ وسلم کی اقتداء میں نماز پڑھ رہے تھے۔\" حالانکہ یہ حدیث ابو سفیان بن عبد الرحمن بن ابی وداعہ سے مروی ہے۔","",{"fn":"(1) اسد الغابہ (۶۳۳۱) تجرید (۲۱۱/۲)"}],[9308,"§۱۰۶۹۸ ۔ ابو ودیعہ\nبغوی نے ان کا بغیر کسی حدیث کے ذکر کیا ہے۔"],[9309,"§۱۰۶۹۹ ۔ ابو الورد المازنی(1)\nابو عمر نے ان کا ذکر کیا ہے کہ بقول بعض ان کا نام حرب ہے اور صحابی ہیں۔ مصر کے رہائشی تھے مصریوں سے ان کی ایک حدیث مروی ہے: \"ایسے سریے (غزوے) سے بچو اگر دشمن سے مقابلہ ہو تو بھاگنا پڑے اور جب غنیمت حاصل ہو تو اس میں خیانت ہو جائے\"۔(2) ان سے مرفوع بھی روایت کی جاتی ہے، ابن لہیعہ نے اسے یزید بن ابی حبیب سے بواسطہ لبیعہ بن عقبہ بحوالہ ان کے نقل کیا ہے۔ میں کہتا ہوں: اسے ابن ماجہ اور بغوی نے نقل کیا ہے، عبید بن قیس کے حالات میں ان کا ذکر ہوا ہے وہیں ان کے نام میں اختلاف کا بیان ہے۔","",{"fn":"(1) اسد الغابہ (۶۳۳۴) تجرید (۲۱۱/۲)\n(2) المعجم الکبیر (۹۵۳/۲۲)"}],[9310,"§۱۰۷۰۰ ۔ ابو الورد بن قیس(1)\nبن فہد (قہد) انصاری۔ بقول ابن کلبی: صفین میں سیدنا علی رضی اللہ عنہ کا ساتھ دیا۔ ابو عمر نے سابقہ شخصیت سے انہیں خلط ملط کر دیا ہے۔ مجھے لگتا ہے بظاہر یہ اور ہیں۔","",{"fn":"(1) سابقہ شخصیت کے حالات میں۔"}],[9311,"§۱۰۷۰۱ ۔ ابو الورد (بے نسبت)\nبقول ابن مندہ: حبیب بن الشہید بواسطہ محمد بن سیرین بحوالہ ابو ایوب انصاری روایت کرتے ہیں کہ میں نبی صلی اللہ علیہ وسلم کے پاس اپنا چچا زاد بھائی لے کر آئے، ایک سرخ رنگ کا آدمی آپ سے بیعت کر رہا تھا تو نبی صلی اللہ علیہ وسلم نے اسے فرمایا: \"یا ابا الورد\"۔ انہوں نے اور عہدان نے بطریق جبارہ بن المغلس ابن المبارک سے بواسطہ حمید الطویل، ابن الدرداء سے بحوالہ اپنے والد روایت کی ہے کہ نبی صلی اللہ علیہ وسلم نے سرخ رنگ کے شخص کو دیکھ کر فرمایا: \"تم ابو الورد(1) ہو\"۔ فرماتے ہیں: مجھے خیال آتا ہے یہ وہی ہیں جن کا ابو ایوب نے ذکر کیا ہے۔","",{"fn":"(1) المعجم الکبیر (۹۵۳/۲۲)"}],[9312,"§۱۰۷۰۲ ۔ ابو الوصل(1)\nابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے اور ابن مندہ نے اپنی تاریخ میں ان کے کسی پوتے کے حالات میں ان کا ذکر کیا ہے۔ لیکن صحابہ رضی اللہ عنہم میں ان کا ذکر کرنے سے غفلت ہوگئی۔ پھر بطریق احمد بن رشدین بحوالہ ابو الوصل صحابی رسول اللہ صلی اللہ علیہ وسلم روایت کی ہے کہ ابو الوصل نے نبی صلی اللہ علیہ وسلم کے ساتھ غزوات میں شرکت کی۔(2) ابراہیم بن اسماعیل کے حالات میں اس کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۳۳۵) تجرید (۲۱۱/۲)\n(2) اسد الغابہ (۱۲۶/۵)"}],[9313,"§۱۰۷۰۳ ۔ ابو الوقاص(1) (بے نسبت)\nمستغفری نے اور ابو موسیٰ نے اپنے استدراک میں ان کے طریق سے پھر بروایت صالح بن سلیمان بحوالہ ابو وقاص صحابی رسول اللہ صلی اللہ علیہ وسلم ان کا ذکر کیا ہے، قیامت کے روز مؤذنوں کے اللہ تعالیٰ کے ہاں حصہ مجاہدین کی طرح ہوگا وہ اذان و اقامت کے درمیانی گھڑی میں اللہ کی راہ میں خون میں لتھڑے ہوئے شخص کا درجہ رکھیں گے۔(2) سیدنا عمر رضی اللہ عنہ نے فرمایا: \"اگر میں مؤذن ہوتا تو میرا معاملہ صاف تھا۔\"(3) اس میں سیدنا عمر رضی اللہ عنہ سے ایک مرفوع روایت کی جاتی ہے اسی میں ہے: \"اللہ تعالیٰ نے مؤذنوں کے گوشت کو جہنم کے لیے حرام کر دیا ہے۔\" اس سے پتہ چلتا ہے مذکورہ واقعہ میں سیدنا عمر رضی اللہ عنہ بھی تھے۔ اسی لیے یہ بات فرمائی، لہذا اس صحابی سے حدیث مرفوع منقول ہوئی۔ بظاہر یہی ہے کیونکہ ایسی بات رائے سے نہیں کہی جاسکتی۔ یہ بھی احتمال ہے سیدنا عمر رضی اللہ عنہ سے اسے بیان کیا ہو اور آپ نے سن کر بیان کر دیا ہو۔ پھر دوسری سند کے ذریعہ بواسطہ صالح بن سلیمان اس کا مفہوم نقل کیا ہے اس میں یہ اضافہ ہے: عبد اللہ بن مسعود رضی اللہ عنہ نے فرمایا: \"مجھے اس کی کوئی پروا نہیں میں اگرچہ حج، عمرہ اور جہاد نہ کروں\"۔ سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں، ان لوگوں کی دلیل یہ آیت ہے: \"اس سے بڑھ کر کس کا عمل اچھا ہوگا جو اللہ تعالیٰ کی طرف بلائے اور نیک عمل کرے۔\"(4) میں کہتا ہوں: یہ صالح بن سلیمان ضعیف راوی ہے۔ اور ان کے شیخ غیاث کا تذکرہ ذہبی(5) نے میزان میں کیا ہے کہ اس کی حدیث منکر ہے۔ میرے خیال میں اس کے علاوہ ان کی کوئی حدیث نہیں پھر اسے ذکر کیا۔ میں کہتا ہوں: جیسا انہوں نے سمجھا ایسی بات نہیں۔ یہ دوسرے ہیں۔ چنانچہ خطیب نے المؤتلف میں بروایت یعقوب بن سفیان بحوالہ صالح غیاث کے حالات ذکر کیے ہیں۔ پھر فرمایا: پھر انہوں نے لمبی حدیث ذکر کی، صحابی کی روایت سے اسے موصولاً نہیں ذکر کیا۔","",{"fn":"(1) اسد الغابہ (۶۳۳۶) تجرید (۲۱۱/۲)\n(2) خون میں لت پت۔\n(3) جامع المسانید (۷۳۲/۱۴) اسد الغابہ (۱۲۶/۵)\n(4) سورۃ فصلت (۳۳)\n(5) میزان الاعتدال (۳۳۸/۳)"}],[9314,"§۱۰۷۰۴ ۔ ابو الولید\nحسان بن ثابت انصاری خزرجی، سہل بن حنیف انصاری۔ عبادہ بن الصامت اور عقبہ بن عبد السلمی سب کا تذکرہ ناموں میں ہو چکا ہے۔"],[9315,"§۱۰۷۰۵ ۔ ابو وہب الجشمی(1)\nابو داؤد اور نسائی نے بطریق محمد بن مہاجر بحوالہ ابو وہب جشمی جو صحابی ہیں روایت کی ہے جو گھوڑوں کے بارے میں ہے اس میں ان کی پیشانیوں پر ہاتھ پھیرا کرو۔ اسی سند سے مرفوع روایت ہے: \"ایسا گھوڑا رکھو جس میں سرخ اور سیاہ رنگ ہو، جس کی پیشانی پر سفید ٹیکہ یا دھبہ ہو اور جس کے گھر سفید ہوں۔\" ...... (حدیث)(2) بقول بغوی: شام کے رہائشی تھے ان کی دو حدیثیں ہیں پھر حدیث الخیل (گھوڑوں والی) نقل کی پھر یہ حدیث انبیاء کے نام رکھا کرو اور اللہ تعالیٰ کے ہاں سب سے زیادہ پسندیدہ نام عبد اللہ اور عبد الرحمن ہے۔ (حدیث) ابن السکن اور کئی لوگوں نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ حاکم الکنی میں لکھتے ہیں: صحابی ہیں، اہل یمامہ سے ان کی حدیث روایت کی جاتی ہے اور بطریق ابو زرعہ رازی، گھوڑوں کے بارے میں دونوں حدیثیں اور ناموں کے بارے میں جو حدیث ہے ایک سیاق سے نقل کی۔ اس کے آغاز میں بھی لکھتے ہیں: یہ صحابی ہیں۔ ادھر ابو حاتم رازی کے بیٹے نے جو ان سے العلل میں روایت کی ہے اس میں ان جشمی کو الکلاعی مشہور تابعی ہونے کا دعویٰ کیا ہے کہ کسی راوی کو ان کے بارے میں وہم ہوا ہے جو جشمی کہہ دیا۔ اور یہ بات انہیں شرف صحابیت حاصل ہے۔ ابن القطان الفاسی کا گمان ہے۔ ابن ابی حاتم کو ان جشمی کو الکلاعی کے حالات کے ساتھ رلانے ملانے میں وہم ہوا ہے۔ میں بھی یہی سمجھتا تھا جیسا انہوں نے کہا پھر کتاب العلل کی طرف رجوع کیا تو دیکھا ان کا ذکر کتاب العین میں کیا ہے اور اپنے والد کے حوالہ سے بیان کیا کہ انہوں نے اس حدیث کے بارے میں بڑی چھان پھٹک کی یہاں تک کہ یہ بات ظاہر ہوگئی کہ یہ حدیث ابو وہب کلاعی سے مروی ہے اور ہے بھی مرسل کسی راوی کو انہیں جشمی بتانے میں اور صحابی کہنے میں وہم ہوا ہے۔ جس کی بڑی وضاحت کی ہے۔","",{"fn":"(1) اسد الغابہ (۶۳۳۷) تجرید (۲۱۱/۲)\n(2) ابوداؤد کتاب الجہاد باب ما یستحب من الوان الخیل (۲۵۴۳) (۲۵۵۳) (۴۹۵۰) نسائی کتاب الخیل (۳۵۵۷) مسند احمد (۳۴۵/۴) جامع المسانید (۷۳۳/۱۴)"}],[9316,"§۱۰۷۰۶ ۔ ابو وہب\nصفوان بن امیہ الجمحی، شجاع بن وہب اسدی، ولید بن عقبہ اسدی اور مجزأۃ بن ثور۔ سب کا ناموں میں ذکر ہوا ہے۔"],[9317,"§۱۰۷۰۷ ۔ ابو وہب الجیشانی(1)\nذہبی لکھتے ہیں: دیلم بن حوشع۔ حرف دال میں ان کے حالات کی تفصیل بیان ہو چکی ہے، اعادہ کی ضرورت نہیں۔","",{"fn":"(1) اسد الغابہ (۶۳۳۸) تجرید (۲۱۱/۲)"}],[9318,"§۱۰۷۰۸ ۔ ابو وہب انصاری(1)\nنبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ جب آدمی سونے لگے تو کیا کہے، جو بروایت خالد بن معدان ہے۔ ذہبی(2) لکھتے ہیں: یہ روایت سلفی نے فوائد ابن طیوری میں سے انتخاب میں ذکر کی ہے کہ اس کی سند قوی ہے اور شاید مرسل ہے۔","",{"fn":"(1) تجرید (۲۱۱/۵)\n(2) تجرید (۱۷۲)"}],[9319,"§۱۰۷۰۹ ۔ ابو وہب الکلبی(1)\nابن مندہ نے ان کا ذکر کیا اور بطریق سعد بن الصلت بحوالہ یحیی بن وہب کلبی روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے آل اکیدر کی جانب ایک خط بھیجا جس میں تھا: \"انہیں ظلم سے امان ہے\"۔ ان دنوں آپ کے پاس مہر نہ تھی آپ صلی اللہ علیہ وسلم نے اپنے ناخن سے مہر لگا دی۔ واقدی کا بیان ہے: یہ اسحاق بن حبان سے بحوالہ یحیی بن وہب مروی ہے ابو نعیم کا دعویٰ ہے یہ شاہ دومۃ الجندل عبد الملک ہیں، جس میں تامل ہے۔ ابن الاثیر نے اس کی تردید کی ہے مجھے بھی ان کی بات درست لگتی ہے۔","",{"fn":"(1) اسد الغابہ (۶۳۳۹) تجرید (۲۱۱/۲)"}],[9320,"§۱۰۷۱۰ ۔ ابو الولید\nعبد اللہ بن عبد اللہ بن الہادی ناموں میں ذکر ہوا ہے۔"],[9321,"§۱۰۷۱۱ ۔ ابو وائل\nشقیق (شقیف) ابی سلمہ (ابو سلمہ اسدی کے سگے بھائی) ناموں میں ذکر ہوا ہے۔"],[9322,"§۱۰۷۱۲ ۔ ابو وجزہ سعدی\nدور نبوی صلی اللہ علیہ وسلم پایا ہے۔ بقول ابن عساکر: میرے خیال میں یہ ابو وجزہ شاعر کے دادا ہیں، جن سے ہشام بن عروہ نے روایت کی ہے۔ شام سیدنا عمر رضی اللہ عنہ کے ساتھ آئے۔ پھر بطریق ابو رجاء قیمی روایت کی ہے کہ سائب بن یزید مخزومی نے فرمایا: جب سیدنا عمر شام تشریف لائے تو لوگوں کو خالد بن ولید رضی اللہ عنہ کی تعریف کرنے سے روک دیا، اتنے میں ابو وجزہ آ گئے، خالد سیدنا عمر رضی اللہ عنہ کے پاس تھے، کہنے لگے: تو خالد یہاں ہیں؟ سیدنا خالد رضی اللہ عنہ نے چہرہ سے نقاب ہٹا دیا تو ابو وجزہ بولے: اللہ کی قسم! آپ ان لوگوں میں سے خوبصورت گال بزرگ دادا والے، زیادہ عزت والے، زیادہ عطا کرنے والے ہیں۔ پھر سیدنا عمر رضی اللہ عنہ نے انہیں مدینہ دیکھا تو فرمایا: کیا میں نے تمہیں خالد کی مدح سے منع نہیں کیا تھا۔ ابو وجزہ بولے: جو ہمیں عطا کرتا ہے ہم اس کی مدح کرتے ہیں اور جو محروم رکھتا ہے اسے ایسے ہی برا بھلا کہتے ہیں جیسے غلام اپنے آقا کو برا بھلا کہتا ہے۔ سیدنا عمر رضی اللہ عنہ نے فرمایا: ابو وجزہ! غلام اپنے آقا کو کیسے برا بھلا کہتا ہے؟ کہا: جہاں سے اسے معلوم نہ ہو اور نہ سن سکے۔ ابن عساکر نے یہ جواز پیش کیا ہے کہ ممکن ہے یہ حارث بن ابی وجزہ ہوں جن کا قسم اول میں ذکر ہوا ہے، جو ٹھیک نہیں۔ کیونکہ وہ قرشی ہیں۔ اور یہ سعدی ہیں اور دونوں واقعات کا طرز بیان بہت مختلف ہے۔"],[9323,"§۱۰۷۱۳ ۔ ابو ودیعہ(1) (بے نسبت)\nابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے کہ محمد بن المسیب اور جعفر مستغفری نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، اور دونوں کے طریق سے بروایت بشر بن ولید، ابو معشر، بواسطہ مقبری، ان کے والد سے بحوالہ ابو ودیعہ صحابی رسول اللہ صلی اللہ علیہ وسلم روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے جمعہ کے روز غسل جنابت کی طرح غسل کیا اور اپنے پاس رکھے تیل یا خوشبو کو لگایا اور اپنے پاس رکھے عمدہ کپڑے پہنے اس کے بعد مسجد میں پہلے سے بیٹھے دو آدمیوں کے درمیان نہیں بیٹھا، اور امام کے آنے تک خاموش رہا۔ تو اس کے دو جمعوں کے درمیانی گناہوں کی بخشش کر دی جائے گی۔\"(2) میں کہتا ہوں: سند میں راوی کا یہ کہنا \"صحابی رسول اللہ صلی اللہ علیہ وسلم\" وہم ہے کیونکہ یہ ابو ودیعہ مشہور تابعی ہیں ان کا نام عبد اللہ بن ودیعہ ہے ان کی حدیث امام بخاری رحمہ اللہ نے بطریق ابن ابی ذئب، سعید بن المقبری سے بواسطہ ان کے والد بحوالہ سلمان روایت کی ہے۔ اسے یحیی بن قطان نے محمد بن عجلان سے بواسطہ سعید نقل کیا تو سلمان کی جگہ فرمایا: ابو ذر سے مروی ہے، جسے ابن ماجہ نے نقل کیا ہے اور ابن الاثیر(3) نے اسی کو برقرار رکھا اس کی علت سے خبردار نہیں ہوئے۔ اس سے بڑھ کر ذہبی(4) نے کمال کر دیا وہ تجرید میں لکھتے ہیں: مستغفری نے مقارب سند سے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے یعنی جو ابو موسیٰ نے روایت کی ہے۔ میں کہتا ہوں: ابو معشر وہ بیج مدنی، ضعیف راوی ہیں اور اس کی سند واقعی مقارب ہے جیسا انہوں نے کہا اگر مخالف نہ ہو لیکن مخالفت کے باوجود اتنا کہا جائے گا یہ منکر ہے۔ صحابی کا تذکرہ ساقط کرنے اور ان کی صفت باقی رکھنے میں ان سے غلطی ہوئی۔ واللہ المستعان!","",{"fn":"(1) اسد الغابہ (۶۳۳۳) تجرید (۲۱۱/۲)\n(2) جامع المسانید (۷۲۹/۱۴) الجرح والتعدیل (۱۹۲/۵)\n(3) اسد الغابہ (۱۲۵/۵)\n(4) تجرید (۱۷۳)"}],[9324,"§۱۰۷۱۴ ۔ ابو یحیی\nصہیب بن سنان رومی۔ ابو یحیی عبد اللہ بن انیس الجہنی، ابو یحیی، سنان، یحیی بن عباد کے دادا، سب کا تذکرہ ناموں میں ہوا ہے۔"],[9325,"§۱۰۷۱۵ ۔ ابو یحیی\nاسید بن حضیر انصاری۔ بقول بعض: ان کی کنیت ابو عتیک ہے، پہلے تذکرہ ہوا ہے۔"],[9326,"§۱۰۷۱۶ ۔ ابو یحیی\nمقدام بن معد یکرب کندی۔ بقول بعض: ان کی کنیت ابو کریمہ ہے۔"],[9327,"§۱۰۷۱۷ ۔ ابو یحیی\nخریم بن فاتک اسدی، بقول بعض: ان کی کنیت ابو ایمن ہے۔"],[9328,"§۱۰۷۱۸ ۔ ابو یحیی\nخباب بن الارت تمیمی، بقول بعض: ان کی کنیت ابو عبد اللہ ہے۔"],[9329,"§۱۰۷۱۹ ۔ ابو یحیی\nسہل بن ابی محمد انصاری، بقول بعض: ان کی کنیت ابو محمد ہے۔"],[9330,"§۱۰۷۲۰ ۔ ابو یحیی\nعبد اللہ بن کعب بن عمرو بن عوف انصاری بدری۔ حاکم فرماتے ہیں، بقول واقدی: میں نے کسی انصاری سے سنا کہ ان کی کنیت ابو یحیی ہے۔ سب کا تذکرہ ناموں میں ہوا ہے۔"],[9331,"§۱۰۷۲۱ ۔ ابو یحیی انصاری\nاز بنی حارثہ۔ ابن اسحاق نے عاصم بن عمر سے بحوالہ سیدنا انس رضی اللہ عنہ ان کا ذکر کیا ہے کہ انصار کے دو آدمیوں کے گھر مسجد سے سب سے زیادہ دور تھے۔ ابو لبابہ اور ابو یحیی جن کا تعلق بنی حارثہ سے تھا، پھر فرماتے ہیں: طبرانی نے ابو لبابہ کے حالات میں ان کا ذکر کیا ہے۔"],[9332,"§۱۰۷۲۲ ۔ ابو یحیی انصاری\nبقول بعض: مجھے معلوم نہیں آیا یہ صحابی ہیں یا نہیں۔ پھر بطریق لیث، عبد اللہ بن یحیی سے بواسطہ ان کے والد بحوالہ ان کے دادا روایت کی ہے کہ ان کی دادی نبی صلی اللہ علیہ وسلم کے ہاں آئیں ان کے پاس ان کا زیور تھا۔ ...... (حدیث) اسی میں ہے: عورت کو اپنے مال میں اپنے خاوند کی اجازت کے بغیر کوئی تصرف کرنا جائز نہیں۔"],[9333,"§۱۰۷۲۳ ۔ ابو یربوع\nسعید بن یربوع، ابو احمد نے ان کا ذکر کیا ہے ناموں میں ان کا تذکرہ ہو چکا ہے۔"],[9334,"§۱۰۷۲۴ ۔ ابو یزید\nعقیل بن ابی طالب ہاشمی۔"],[9335,"§۱۰۷۲۵ ۔ ابو یزید\nسہیل بن عمرو العامری۔"],[9336,"§۱۰۷۲۶ ۔ ابو یزید\nسائب بن یزید ابن اخت نمر۔"],[9337,"§۱۰۷۲۷ ۔ ابو یزید\nانیس بن مرثد بن ابی مریم الغنوی۔"],[9338,"§۱۰۷۲۸ ۔ ابو یزید\nمعن بن یزید الانفس الاسلمی۔ ان سب کا تذکرہ بھی ناموں میں ہو چکا ہے۔"],[9339,"§۱۰۷۲۹ ۔ ابو یزید\nمعقل بن سنان انجہی، بقول بعض: ان کی کنیت ابو محمد یا ابو عبد الرحمن ہے پہلے ذکر ہو چکا ہے۔"],[9340,"§۱۰۷۳۰ ۔ ابو یزید\nحارثہ بن قدامہ بن مالک تمیمی، سعدی، بقول بعض: ان کی کنیت ابو ایوب ہے، پہلے ذکر ہو چکا ہے۔"],[9341,"§۱۰۷۳۱ ۔ ابو یزید بن عمرو الجذامی(1)\nواقدی نے جذام میں سے اسلام قبول کرنے والوں میں ان کا ذکر کیا ہے۔ ابو علی جیانی اور ابن الدباغ نے اپنے اپنے استدراک میں ان کا ذکر کیا ہے۔ حرف زاء میں کنتیوں میں ابو زید جذامی کا تذکرہ ہوا ہے، معلوم نہیں یہ وہی ہیں یا کوئی اور ہیں؟","",{"fn":"(1) اسد الغابہ (۶۳۴۱) تجرید (۲۱۲/۲)"}],[9342,"§۱۰۷۳۲ ۔ ابو یزید(1) (حکیم کے والد)\nان کی ایک حدیث ہے جس میں عطاء بن سائب سے آگے اختلاف ہے۔ دوری لکھتے ہیں: ابن معین سے منقول ہے عطاء بن سائب نے حکیم بن ابی یزید الکرخی سے انہوں نے اپنے والد سے بحوالہ نبی صلی اللہ علیہ وسلم روایت کی ہے، کسی نے ان سے پوچھا کیا ان کے والد صحابی ہیں، انہوں نے فرمایا: مجھے معلوم نہیں۔ میں کہتا ہوں: اس میں اختلاف کی وضاحت کچھ اس طرح ہے۔ جریر عن عطاء عن حکیم بن ابی یزید الکرخی عن ابیہ قال قال رسول اللہ صلی اللہ علیہ وسلم: لوگوں کو چھوڑ دو وہ ایک دوسرے سے جو کچھ حاصل کریں جب تم میں سے کوئی اپنے بھائی سے خیر خواہی کا طالب ہو تو وہ اس سے خیر خواہی کرے۔\"(2) امام بخاری رحمہ اللہ نے یہ روایت تعلیقاً اور ابو احمد نے موصولاً ذکر کی ہے یہی قول عبد الوارث بن سعید کا بحوالہ عطاء ہے۔ اور حماد بن زید، اسماعیل بن علیہ نے عطاء سے اسی طرح نقل کی ہے۔ دونوں روایتوں کو ابن السکن نے درج کیا ہے اور ابن علیہ والی روایت حسن بن سفیان نقل کرتے ہیں۔ وہیب بن خالد کا قول ہے: عن عطاء عن حکیم بن ابی یزید میں کسی ضرورت سے ان کے ساتھ گیا تو انہوں نے بواسطہ اپنے والد بحوالہ نبی صلی اللہ علیہ وسلم نے مجھ سے بیان کیا۔ جسے ابن ابی خیثمہ نے روایت کیا ہے الکنی میں امام بخاری رحمہ اللہ لکھتے ہیں: ابو یزید ان لوگوں میں سے ہیں جنہوں نے نبی صلی اللہ علیہ وسلم سے سماع کیا ہے ابو عوانہ فرماتے ہیں: عن عطاء بن السائب عن حکیم بن ابی یزید عن ابیہ اور تاریخ میں بواسطہ مسدد بحوالہ ابو عوانہ موصولاً ذکر کیا ہے اسی طرح امام احمد رحمہ اللہ نے ابو عوانہ کی روایت سے نقل کیا ہے، طیالسی کی کتاب میں ہمام بن یحیی نے ان کی موافقت کی ہے۔ میں کہتا ہوں: احتمال ہے اگر یہ بات محفوظ ہے جس نے انہیں \"ابن ابی یزید کہا ہے\" ان کو دادا کی طرف منسوب کیا ہو۔ ابن مندہ نے ان کا عنوان ابو یزید جد حکیم، قائم کیا ہے۔ لہذا ابو عوانہ والی روایت میں دادا مبہم ہے۔ اضطراب عطاء بن سائب کی طرف سے ہے کیونکہ وہ بھولنے لگے تھے۔ بقول بعض: حماد بن سلمہ نے ان سے اس حالت سے پہلے سماع کیا تھا۔ واللہ اعلم! اور حماد اس کی سند یوں بیان کرتے ہیں، عن عطاء عن حکیم بن یزید عن ابیہ اور ہمام نے ان کی موافقت کی ہے جیسا کہ حرف یاء میں بیان ہوا ہے اکثریت کا کہنا یہ ہے: یہ ابن ابی یزید ہیں۔ واللہ اعلم! ابو عمر فرماتے ہیں: میں جو کہتا ہوں وہ یہ ہے کہ تین افراد وہیب، جریر بن حازم اور اسماعیل بن علیہ کی بات درست ہے۔ اور ابو عوانہ کو اس میں وہم ہوا ہے۔ میں نے اس کا ذکر کیا ہے جس نے یہ روایت موصولاً ذکر کی ہے البتہ ان کا جریر بن حازم کہنا غلط ہے۔ صحیح جریر بن عبد الحمید ہے کیونکہ انہوں نے ذکر کیا ہے یہ ابو خیثمہ کی روایت سے ہے اور ابو خیثمہ نے لامحالہ اپنے والد سے بواسطہ جریر نقل کی ہے اسی طرح حاکم نے اسے بروایت محمد بن قدامہ عن جریر موصولاً نقل کیا ہے اور ابن قدامہ اور ابو خیثمہ کی جریر بن حازم سے ملاقات نہیں ہوئی۔ میں نے اس پر عبد الوارث اور حماد بن زید کا اضافہ کیا ہے، جبکہ حماد بن سلمہ نے ان کی مخالفت میں روایت کی ہے۔ وہ فرماتے ہیں: عن عطاء بن السائب عن حکیم بن یزید عن ابیہ۔","",{"fn":"(1) اسد الغابہ (۶۳۴۲) تجرید (۲۱۲/۲)\n(2) مسند احمد (۴۱۸/۲) (۴۱۹/۲)"}],[9343,"§۱۰۷۳۳ ۔ ابو یزید اللقیطی\nحزابہ بن نعیم کی حدیث میں ان کا ذکر آتا ہے، ناموں میں ذکر ہو چکا ہے۔"],[9344,"§۱۰۷۳۴ ۔ ابو یزید النمیری\nآخری قسم میں ذکر ہوتا ہے۔"],[9345,"§۱۰۷۳۵ ۔ ابو الیسر انصاری(1)\nنام کعب بن عمرو بن عباد بن عمرو بن سواد بن غنم بن کعب بن سلمہ ہے۔ بقول بعض: کعب بن عمرو بن تمیم بن سواد بن غنم بن کعب بن سلمہ انصاری سلمی ہے۔ نام و کنیت سے مشہور ہیں۔ بیعت عقبہ اور بدر میں شریک تھے جس میں ان کے بہت زیادہ کارنامے ہیں۔ انہوں نے سیدنا عباس رضی اللہ عنہ کو گرفتار کر لیا تھا۔ ابن اسحاق(2) فرماتے ہیں: بدر اور باقی معرکوں میں شرکت کی۔ بقول امام بخاری: صحابی ہیں، بدر میں شریک تھے، مدائنی ان کا حلیہ بیان کرتے ہیں پستہ قد اور بڑے پیٹ والے تھے۔ مدینہ میں ۵۵ھ میں انتقال کیا۔ بقول ابن اسحاق: صحابہ میں رضی اللہ عنہم میں آخری صحابی یہی فوت ہوئے ہیں۔ شاید ان کی مراد اہل بدر صحابہ رضی اللہ عنہم سے ہو۔ ان سے عبادہ بن ولید بن عبادہ بن الصامت نے روایت کی ہے ان کی لمبی حدیث ہے جسے مسلم نے نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۳۴۵) تجرید (۲۱۲/۲)\n(2) السیرۃ النبویہ (۲۵۸/۲)"}],[9346,"§۱۰۷۳۶ ۔ ابو الیسع(1)\nابن مندہ نے ان کا ذکر کیا ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کے بارے میں پوچھا، کسی نے بتایا وہ عرفات(2) میں ہیں۔ ان کی حدیث محمد بن خالد نے عبید اللہ بن ابی حمید سے بواسطہ ابو عثمان نہدی طویل نقل کی ہے۔ ابو عمر فرماتے ہیں: ان کی حدیث عبید اللہ بن ابی حمید سے بواسطہ ابو اسلیح بن ابی اسامہ بحوالہ ان کے مروی ہے، فرمایا: میں نبی صلی اللہ علیہ وسلم کے پاس آ کر عرض کرنے لگا: اللہ کے رسول صلی اللہ علیہ وسلم کون سا عمل مجھے جنت میں لے جائے گا؟ (حدیث)","",{"fn":"(1) اسد الغابہ (۶۳۴۶) تجرید (۲۱۲/۲)\n(2) جامع المسانید (۷۵۳/۱۴) اسد الغابہ (۱۳۰/۵)"}],[9347,"§۱۰۷۳۷ ۔ ابو یعقوب\nیوسف بن عبد اللہ بن سلام، یہ اور ان کے والد دونوں صحابی ہیں، ناموں میں ذکر ہو چکا ہے۔"],[9348,"§۱۰۷۳۸ ۔ ابو یعلی\nحمزہ بن عبد المطلب نبی صلی اللہ علیہ وسلم کے چچا، اور ابو یعلی، شداد بن اوس انصاری، دونوں کا تذکرہ ناموں میں ہوا ہے۔"],[9349,"§۱۰۷۳۹ ۔ ابو الیقظان(1) (بے نسبت)\nحاکم فرماتے ہیں: محمد بن اسماعیل کا قول ہے: یہ صحابی ہیں۔ ابن مندہ لکھتے ہیں: امام بخاری(2) رحمہ اللہ نے بغیر حدیث کے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ اور ابن ابی حاتم(3) فرماتے ہیں: ابو زرعہ رازی نے مسند میں ان کی صرف یہی ایک حدیث نقل کی ہے۔ جو مسند بصریین میں بطریق ابن وہب، عمرو بن حارث، ابن لہیعہ بواسطہ ابو حسانہ مروی ہے کہ انہوں نے ابو الیقظان صحابی رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: تمہیں مبارک ہو تم لوگوں کو رسول اللہ صلی اللہ علیہ وسلم سے سب سے زیادہ محبت ہے۔ عموماً جن لوگوں نے انہیں دیکھا ہے انہوں نے ان سے یہ روایت نہیں کی۔ ابو عمر لکھتے ہیں: مصر کے رہائشی صحابہ رضی اللہ عنہم میں ان کا ذکر آتا ہے۔ میں کہتا ہوں: محمد بن الربیع الجیزی نے مصر آنے والے صحابہ رضی اللہ عنہم میں ان کا ذکر نہیں کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۳۴۷) استیعاب (۳۲۶۷) تجرید (۲۱۲/۲)\n(2) التاریخ الکبیر (۸۲/۸)\n(3) الجرح والتعدیل (۴۶۰/۴)"}],[9350,"§۱۰۷۴۰ ۔ ابو الیقظان\nعمار بن یاسر العنسی، نام سے مشہور ہیں، پہلے تذکرہ ہوا ہے۔"],[9351,"§۱۰۷۴۱ ۔ ابو الیمان\nبشر یا بشیر بن عقربہ یا ابن عقرب الجہنی، باء میں ذکر ہوا ہے۔"],[9352,"§۱۰۷۴۲ ۔ ابو یوسف\nعبد اللہ بن سلام، نام سے مشہور ہیں۔ ناموں میں پہلے ذکر ہو چکا ہے۔"],[9353,"§۱۰۷۴۳ ۔ ابو یونس ظفری(1)\nابن ابی حاتم نے وحدان میں ان کا ذکر کیا ہے اور ان کی یہ روایت نقل کی ہے کہ وہ حجۃ الوداع کے موقعہ پر رسول اللہ صلی اللہ علیہ وسلم کے پاس تھے۔ اس وقت ان کی عمر تیس(۳۰) سال تھی۔ ان کی روایت ہے۔ میں کہتا ہوں: ان کا نام محمد بن انس بن فضالہ ہے، یہ ان کے والد اور ان کے دادا صحابہ ہیں، سب کا تذکرہ ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۶۳۴۸) تجرید (۲۱۲/۲)"}],[9354,"§۱۰۷۴۴ ۔ ابو یحیی\nعبد الرحمن بن حاطب بن ابی بلتعہ، ناموں میں ذکر ہوا ہے۔"],[9355,"§۱۰۷۴۵ ۔ ابو یحیی (بے نام و نسبت)\nخطیب نے ایک واقعہ نقل کیا ہے جو یحیی بن ابی یحیی کے حالات میں ہے، اس میں ان کا ذکر آتا ہے کہ ابو یحیی فرماتے ہیں: دور جاہلیت میں میں اپنے گھوڑے پر جا رہا تھا اچانک مجھے طرف یعنی ابن العبد مشہور عامل گیا۔ پھر ایک واقعہ ذکر کیا جس میں ہے اس نے ان کے سامنے اپنی زبان نکالی تو وہ سیاہ تھی جیسے ہرن کی زبان ہوتی ہے۔"],[9356,"§۱۰۷۴۶ ۔ ابو یزید سعدی\nمخضل، پہلے تذکرہ ہوا ہے۔"],[9357,"§۱۰۷۴۷ ۔ ابو یحیی\nقیس کے ایک شخص ہیں، نبی صلی اللہ علیہ وسلم کے حوالہ سے یہ حدیث نقل کرتے ہیں: کیا تمہیں عرب کا بہترین قبیلہ نہ بتاؤں...؟ (حدیث) اسی میں سکاسک اور سکون کا ذکر ہے۔ ان کی حدیث ابن لہیعہ نے مرثد بن ابی حبیب سے بواسطہ ربیعہ بن لقیط، بنی اور کے شخص سے جو الکمیین کے شخص جنہیں ابو یحیی کہا جاتا تھا روایت کی ہے۔ بغوی نے اپنی معجم میں اور ابن عساکر نے الکمیین میں ان کے طریق سے روایت کی ہے کہ مرسل ہے۔"],[9358,"§۱۰۷۴۸ ۔ ابو یزید النمیری(1)\nابو عمر نے ان کا ذکر کیا ہے کہ صحابی ہیں۔ ایوب بحتانی ان سے روایت کرتے ہیں کہ انہوں نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے عہد مبارک میں اپنی قوم کی امامت کی اس وقت میری عمر سات سال تھی۔ ابن الاثیر(2) فرماتے ہیں: النمیری کا کوئی وجود نہیں میرے خیال میں یہ جرمی عمرو بن سلمہ ہیں ان کی کنیت ابو یزید (باء پر پیش سے تصغیر ہے) انہوں نے ہی اپنی قوم کی امامت کی تھی جب وہ چھ یا سات سال کے تھے۔ ان سے ایوب اور ابو قلابہ وغیرہ روایت کرتے ہیں۔ ذہبی نے انہیں برقرار رکھا ہے اور ابن فتحون نے ادوام الاستیعاب میں ان کا ذکر کیا ہے۔ فرماتے ہیں: انہیں دو جگہ ان کے متعلق وہم ہوا ہے۔ ایک نمیری کہنے میں حالانکہ یہ جرمی ہیں، دوسرا ان کی کنیت بتانے میں جو باء سے برید ہے۔ جبکہ ابو عمر نے باب میں ان کا درست ذکر کیا ہے۔(3) میں کہتا ہوں: ایک بعید احتمال ہے کہ یہ دوسرے ہوں۔","",{"fn":"(1) اسد الغابہ (۶۳۴۴) تجرید (۲۱۲/۲)\n(2) اسد الغابہ (۱۲۹/۵)\n(3) تجرید (۱۷۲)"}],[9359,"§۱۰۷۴۹ ۔ ابو یزید بن ابی مریم(1)\nذہبی(2) نے اپنے استدراک میں ان کا ذکر کیا ہے کہ مسند بقی میں ان کی ایک حدیث ہے۔ استدراک میں انہیں وہم ہوا ہے جبکہ یہ ابو مریم سلولی ہیں جو یزید کے والد ہیں۔ ان کا نام مالک بن ربیعہ ہے جیسا کہ ناموں میں گزرا ہے ان کی حدیث امام احمد، بخاری نے تاریخ میں اور نسائی نے بطریق یزید بن ابی مریم بحوالہ اپنے والد نقل کی ہے۔ اگر ایسی بات ہوتی کہ جس کا بیٹا ہے وہ اس کے بغیر کوئی کنیت رکھ لے اور اسی سے مشہور ہو جائے اور دوسرے بیٹے کے نام کنیت کر لے تو ہر ایک اپنی اولاد کی مقدار کنیتیں رکھ لیتا، کیونکہ کسی کے دس بیٹے تھے، بلکہ بیس تیس تک بھی ہوئے ہیں۔ اب اگر کوئی صدیق اکبر کا عنوان ابو بکر قائم کرے اور کتبوں میں ابو محمد بن ابی بکر کا ذکر کرے تو اسے معذور سمجھا جائے گا کیونکہ اس سے فوراً تو یہی سمجھ آتا ہے کہ مذکورہ عنوان ابو محمد کا ہے نہ کہ ان کے والد کا۔ اسی طرح اوروں کا حال سمجھ لیں یا جیسے سیدنا عثمان رضی اللہ عنہ کا عنوان ابو عمرو بن عثمان قائم کرے۔ تو انتہائی درجہ کی رکاکت و کمزور علمی ہوگی جو بالکل واضح ہے کسی قسم کا خفا و پوشیدگی نہیں۔ واللہ المستعان!","",{"fn":"(1) تجرید (۲۱۲/۲)\n(2) تجرید (۱۷۲)"}],[9360,"§۱۰۷۵۰ ۔ آسیہ بنت الحارث السعدیہ\nنبی کریم صلی اللہ علیہ وسلم کی رضاعی بہن، ابوسعید نیشاپوری نے شرف المصطفیٰ میں ان کا ذکر کیا ہے۔"],[9361,"§۱۰۷۵۱ ۔ آسیہ بنت الفرج الجرہمیہ\n(1) ابن مندہ نے ان کا ذکر کیا ہے، اور ایوب بن محمد الوزان کی سند سے یعلیٰ بن الاشدق کے حوالے سے نقل کر کے فرمایا: آسیہ بنت الفرج جو جرہم قبیلہ کی خاتون تھی جن کا گھر مکہ میں جون کے مقام پر تھا۔ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں۔ عرض کیا: یا رسول اللہ! مجھ سے غلطی ہو گئی ہے۔ اور میں زنا کر بیٹھی ہوں، مجھے پاک کیجئے! آپ صلی اللہ علیہ وسلم نے فرمایا: کیا تم نے بچہ جن لیا ہے؟ انہوں نے عرض کی: نہیں! آپ صلی اللہ علیہ وسلم نے فرمایا: تمہارے بچے کی ولادت میں کتنی مدت رہ گئی ہے؟ انہوں نے کہا: ایک مہینہ۔ آپ صلی اللہ علیہ وسلم نے فرمایا: جب تک تو بچہ نہ جن لے میں تمہیں پاک کرنے والا نہیں۔ وہ کہتی ہیں: میں نے بچہ جن لیا اور اس کو لے کر آپ صلی اللہ علیہ وسلم کے پاس آئی، اور آپ صلی اللہ علیہ وسلم کو ساری بات بتائی......(2) پھر راوی نے طویل حدیث ذکر کی، اسی طرح اصل نسخے میں ہے۔ اور ابن مندہ نے اسے نقل نہیں کیا۔","",{"fn":"(1) اسد الغابہ (ت: ۶۶۸۲) تجرید اسماء الصحابہ (۲۴۲/۲)\n(2) اسد الغابہ (۲۰۶/۵)"}],[9362,"§۱۰۷۵۲ ۔ آمنہ بنت الأرقم\n(1) ابوالسائب المخزومی نے اپنی دادی آمنہ بنت الارقم کے حوالے سے نقل کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے انہیں عقیق کی وادی میں ایک کنواں عطا کیا، اسے بئر آمنہ کہا جاتا تھا اور ان کے لیے اس میں برکت کی دعا کی، اور وہ مہاجر صحابیات میں سے تھیں۔ ابن مدباغ نے استیعاب پر اضافہ کر کے ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۶۸۴) تجرید اسماء الصحابہ (۲۴۲/۲)"}],[9363,"§۱۰۷۵۳ ۔ آمنہ بنت حرملہ\nولید بن ولید بن المغیرہ کی والدہ ہیں۔ کہا جاتا ہے کہ ان کا نام عاتکہ ہے۔ ان کے بیٹے کے حالات میں کسی ایسی شے کا کر ہے جس سے معلوم ہوتا ہے کہ انہیں شرف صحابیت حاصل ہے۔"],[9364,"§۱۰۷۵۴ ۔ آمنہ بنت ابی الحکم\nیا بنت الحکم الغفاریہ، دوسری قسم میں ان کے حالات آئیں گے۔"],[9365,"§۱۰۷۵۵ ۔ آمنہ بنت خلف الاسلمیہ\n(1) ابو موسیٰ نے ان کا ذیل میں ذکر کیا ہے۔ دو غیر معتبر سندوں سے مبارک بن فضالہ کے واسطے سے حسن سے نقل کیا کہ آمنہ بنت خلف الاسلمیہ سے جب گناہ سرزد ہوا تو نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور کہا، یا رسول اللہ صلی اللہ علیہ وسلم! میں شادی شدہ عورت ہوں اور میرا خاوند موجود نہیں، مجھ سے گناہ سرزد ہو گیا ہے مجھے پاک کیجئے! پھر راوی نے طویل قصہ ذکر کیا۔ آپ صلی اللہ علیہ وسلم نے ان کے لیے سنگساری کے وقت بہت زیادہ دعا کی جو تقریباً دو ورقوں میں ہے۔(2) اصل میں اسی طرح ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۶۸۴) تجرید اسماء الصحابہ (۲۴۲/۲)\n(2) مستدرک (الحدیث: ۲۹۲/۵)"}],[9366,"§۱۰۷۵۶ ۔ آمنہ بنت ابی الغیار\nمطیع بن الاسود کی زوجہ اور عبداللہ بن مطیع کی والدہ ہیں، بعض کا قول ہے کہ ان کا نام امیمہ ہے (دو میموں کے ساتھ تصغیر ہے)۔"],[9367,"§۱۰۷۵۷ ۔ آمنہ بنت قیس\n(1) بن عبداللہ بن رئاب بن یعمر، وہ ام المؤمنین سیدہ زینب بنت جحش الاسدیہ کی چچا زاد بہن ہیں از بنی غنم بن دودان۔ ابن اسحاق(2) نے ذکر کیا ہے کہ وہ اور ان کے والد ام حبیبہ بنت ابی سفیان کے ساتھ حبشہ میں تھے۔ اور ان کے والد کے ساتھ ان کی بیوی برکتہ بنت سیار تھیں اور وہ دونوں عبداللہ بن جحش کی دائیاں تھیں۔ ابن اسحاق نے السیرۃ النبویۃ میں ان کا ذکر کیا ہے۔ اور مستغفری نے ابن اسحاق کے حوالے سے نقل کیا ہے۔ ابو موسیٰ نے اس کا استدراک کیا ہے۔ ابن سعد(3) نے کہا کہ وہ اسلام کے ابتدائی دور میں مکہ میں ایمان لائیں اور اپنے اہل خانہ کے ساتھ مدینہ ہجرت کی۔","",{"fn":"(1) اسد الغابہ (ت: ۶۶۹۹)\n(2) السیرۃ النبویۃ (۶/۴)\n(3) الطبقات الکبریٰ (۱۷۷/۸)"}]])